    return {"id":id,"created_at":created_at,"original_command":original_command,"command":command,"path":path,"envs":envs,"group":group,"dependencies":dependencies,"priority":priority,"label":label,"status":status}
def make_state(tasks_list, groups=None):
    if groups is None:
        groups={"default":{"status":"Running","parallel_tasks":1}}
