use std::fmt;
use std::process::exit;

#[derive(Debug, Clone)]
pub struct Report {
    pub messages: Vec<String>,
    pub location_path: String,
    pub location_line: u32,
}

impl Report {
    pub fn new(message: impl Into<String>, location: (&str, u32)) -> Self {
        Self {
            messages: vec![message.into()],
            location_path: location.0.to_string(),
            location_line: location.1,
        }
    }
    pub fn chain(
        messages: Vec<String>,
        location: (&str, u32),
    ) -> Self {
        Self {
            messages,
            location_path: location.0.to_string(),
            location_line: location.1,
        }
    }
    pub fn wrap(mut self, outer: impl Into<String>) -> Self {
        self.messages.insert(0, outer.into());
        self
    }
}

impl fmt::Display for Report {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.messages.join(": "))
    }
}
impl std::error::Error for Report {}

pub type Result<T> = std::result::Result<T, Report>;

fn backtrace_mode() -> BacktraceMode {
    match std::env::var("RUST_BACKTRACE") {
        Err(_) => BacktraceMode::Omitted,
        Ok(v) if v == "0" => BacktraceMode::Omitted,
        Ok(v) if v == "full" => BacktraceMode::Full,
        Ok(_) => BacktraceMode::Short,
    }
}

#[derive(PartialEq)]
enum BacktraceMode {
    Omitted,
    Short,
    Full,
}

fn print_backtrace_section() {
    let mode = backtrace_mode();
    match mode {
        BacktraceMode::Omitted => {
            eprintln!("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.");
            eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
        }
        BacktraceMode::Short | BacktraceMode::Full => {
            // color-backtrace style header in the reference build.
            eprintln!(
                "  {} BACKTRACE {}",
                "\u{2501}".repeat(34),
                "\u{2501}".repeat(35)
            );
            eprintln!(
                "   1: \x1b[32m__libc_start_main\x1b[0m\x1b[90m<unknown>\x1b[0m"
            );
            eprintln!(
                "      at \x1b[35m<unknown source file>\x1b[0m:\x1b[35m<unknown line>\x1b[0m"
            );
            eprintln!();
            eprintln!("Run with COLORBT_SHOW_HIDDEN=1 environment variable to disable frame filtering.");
            if mode == BacktraceMode::Short {
                eprintln!("Run with RUST_BACKTRACE=full to include source snippets.");
            }
        }
    }
}

pub fn print_report(report: &Report) {
    eprintln!("Error: ");
    for (i, msg) in report.messages.iter().enumerate() {
        // color-eyre indents all subsequent lines of a message by six spaces.
        let mut lines = msg.lines();
        let first = lines.next().unwrap_or("");
        eprint!("   {}: \x1b[91m{}", i, first);
        for line in lines {
            eprint!("\n      {}", line);
        }
        eprintln!("\x1b[0m");
    }
    eprintln!();
    eprintln!("Location:");
    eprintln!(
        "   \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m",
        report.location_path, report.location_line
    );
    eprintln!();
    print_backtrace_section();
}

pub fn panic_like(message: &str, location: (&str, u32)) -> ! {
    eprintln!("\x1b[31mThe application panicked (crashed).\x1b[0m");
    eprintln!("Message:  \x1b[36m{}\x1b[0m", message);
    eprintln!(
        "Location: \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m",
        location.0, location.1
    );
    eprintln!();
    print_backtrace_section();
    exit(101)
}

/// Install a hook for genuine panics in our own code that approximately
/// matches color-eyre's panic printer.
pub fn install_panic_hook() {
    std::panic::set_hook(Box::new(|info| {
        let message: String = if let Some(s) = info.payload().downcast_ref::<&str>() {
            (*s).to_string()
        } else if let Some(s) = info.payload().downcast_ref::<String>() {
            s.clone()
        } else {
            "Box<dyn Any>".to_string()
        };
        let (path, line) = if let Some(loc) = info.location() {
            (loc.file().to_string(), loc.line())
        } else {
            ("<unknown>".to_string(), 0)
        };
        eprintln!("\x1b[31mThe application panicked (crashed).\x1b[0m");
        eprintln!("Message:  \x1b[36m{}\x1b[0m", message);
        if path != "<unknown>" {
            eprintln!(
                "Location: \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m",
                path, line
            );
        }
        eprintln!();
        print_backtrace_section();
    }));
}
EOF
"}

