{"command":"cat > src/logging.rs <<'EOF'
use chrono::Local;
use std::sync::atomic::{AtomicU8, Ordering};

static VERBOSE: AtomicU8 = AtomicU8::new(0);
static SUPPRESS_VERSION_WARN: AtomicU8 = AtomicU8::new(0);

pub fn init(verbose: u8) {
    VERBOSE.store(verbose, Ordering::Relaxed);
}
pub fn verbose() -> u8 {
    VERBOSE.load(Ordering::Relaxed)
}
pub fn set_suppress_version_warn(v: bool) {
    SUPPRESS_VERSION_WARN.store(if v { 1 } else { 0 }, Ordering::Relaxed);
}
pub fn suppress_version_warn() -> bool {
    SUPPRESS_VERSION_WARN.load(Ordering::Relaxed) != 0
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

fn max_level() -> Level {
    match verbose() {
        0 => Level::Warn,
        1 => Level::Info,
        2 => Level::Debug,
        _ => Level::Trace,
    }
}

pub fn enabled(level: Level) -> bool {
    (level as u8) <= (max_level() as u8)
}

fn level_text(level: Level) -> &'static str {
    match level {
        Level::Error => "ERROR",
        Level::Warn => " WARN",
        Level::Info => " INFO",
        Level::Debug => "DEBUG",
        Level::Trace => "TRACE",
    }
}
fn level_color(level: Level) -> u32 {
    match level {
        Level::Error => 31,
        Level::Warn => 33,
        Level::Info => 32,
        Level::Debug => 34,
        Level::Trace => 35,
    }
}

fn time_str() -> String {
    Local::now().format("%H:%M:%S").to_string()
}

pub fn is_pretty() -> bool {
    verbose() >= 4
}

/// Simple event: same message text in both formats.
pub fn log_event(level: Level, target: &str, pretty_loc: &str, message: &str) {
    if !enabled(level) {
        return;
    }
    let color = level_color(level);
    if is_pretty() {
        eprintln!(
            "  \x1b[2m{}\x1b[0m \x1b[{}m{}\x1b[0m \x1b[1;{}m{}\x1b[0m\x1b[{}m: \x1b[{}m{}\x1b[0m",
            time_str(),
            color,
            level_text(level),
            color,
            target,
            color,
            color,
            message
        );
        eprintln!(
            "    \x1b[2;3mat\x1b[0m {} \x1b[2;3mon\x1b[0m main",
            pretty_loc
        );
        eprintln!();
    } else {
        eprintln!(
            "\x1b[2m{}\x1b[0m \x1b[{}m{}\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m {}",
            time_str(),
            color,
            level_text(level),
            target,
            message
        );
    }
}

/// The exit-special "Handling command" trace event.  `pretty_debug` is the
/// {:#?} representation used by the compact formatter, `inline_debug` the
/// {:?} representation used by the pretty formatter.
pub fn log_handling_command(pretty_debug: &str, inline_debug: &str) {
    if !enabled(Level::Trace) {
        return;
    }
    let target = "pueue::client::commands";
    let loc = "pueue/src/client/commands/mod.rs:159";
    if is_pretty() {
        // Build message manually so the field name is styled like the
        // tracing-subscriber pretty formatter does.
        eprintln!(
            "  \x1b[2m{}\x1b[0m \x1b[35mTRACE\x1b[0m \x1b[1;35m{}\x1b[0m\x1b[35m: \x1b[35mHandling command, \x1b[1;35msubcommand\x1b[0m\x1b[35m: {}\x1b[0m",
            time_str(),
            target,
            inline_debug
        );
        eprintln!(
            "    \x1b[2;3mat\x1b[0m {} \x1b[2;3mon\x1b[0m main",
            loc
        );
        eprintln!();
    } else {
        eprintln!(
            "\x1b[2m{}\x1b[0m \x1b[35mTRACE\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m Handling command \x1b[3msubcommand\x1b[0m\x1b[2m=\x1b[0m{}",
            time_str(),
            target,
            pretty_debug
        );
    }
}

// Convenience wrappers used throughout the codebase.
pub fn info_settings(message: &str, line: u32) {
    log_event(
        Level::Info,
        "pueue_lib::settings",
