/// {:#?} representation used by the compact formatter, `inline_debug` the
/// {:?} representation used by the pretty formatter.
pub fn log_handling_command(pretty_debug: &str, inline_debug: &str) {
    if !enabled(Level::Trace) {
        return;
    }
    let target = "pueue::client::commands";
    let loc = "pueue/src/client/commands/mod.rs:159";
    if is_pretty() {
        // Build message manually so the field name is styled like the
        // tracing-subscriber pretty formatter does.
        eprintln!(
            "  \x1b[2m{}\x1b[0m \x1b[35mTRACE\x1b[0m \x1b[1;35m{}\x1b[0m\x1b[35m: \x1b[35mHandling command, \x1b[1;35msubcommand\x1b[0m\x1b[35m: {}\x1b[0m",
