        eprintln!(
            "    \x1b[2;3mat\x1b[0m {} \x1b[2;3mon\x1b[0m main",
            loc
        );
        eprintln!();
    } else {
        eprintln!(
            "\x1b[2m{}\x1b[0m \x1b[35mTRACE\x1b[0m \x1b[2m{}\x1b[0m\x1b[2m:\x1b[0m Handling command \x1b[3msubcommand\x1b[0m\x1b[2m=\x1b[0m{}",
            time_str(),
            target,
            pretty_debug
        );
    }
