// Convenience wrappers used throughout the codebase.
pub fn info_settings(message: &str, line: u32) {
    log_event(
        Level::Info,
        "pueue_lib::settings",
        &format!("pueue_lib/src/settings.rs:{}", line),
        message,
    );
}
