{"command":"cat >> Cargo.toml <<'EOF'
libc = "0.2"
EOF
cat > src/settings.rs <<'EOF'
use crate::errors::{Report, Result};
use crate::logging;
use serde::{Deserialize, Deserializer, Serialize};
use std::collections::BTreeMap;
use std::fs::File;
use std::path::PathBuf;

pub const PROTOCOL_VERSION: &str = "0.31.1";

pub fn expand_tilde_path(path: PathBuf) -> PathBuf {
    // The upstream behaviour expands a leading "~" or "~/" but not
    // "~user" style prefixes.
    let text = path.to_string_lossy();
    if text == "~" {
        if let Some(home) = dirs::home_dir() {
            return home;
        }
    } else if let Some(rest) = text.strip_prefix("~/") {
        if let Some(home) = dirs::home_dir() {
            let home_text = home.to_string_lossy();
            return PathBuf::from(format!("{}/{}", home_text, rest));
        }
    }
    path
}

fn deserialize_option_path<'de, D>(deserializer: D) -> std::result::Result<Option<PathBuf>, D::Error>
where
    D: Deserializer<'de>,
{
    let opt = Option::<PathBuf>::deserialize(deserializer)?;
    Ok(opt.map(expand_tilde_path))
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum EditMode {
    Toml,
    Files,
}
impl Default for EditMode {
    fn default() -> Self {
        EditMode::Toml
    }
}

fn default_true() -> bool {
    true
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
pub struct Shared {
    #[serde(default, deserialize_with = "deserialize_option_path")]
    pub pueue_directory: Option<PathBuf>,
    #[serde(default, deserialize_with = "deserialize_option_path")]
    pub runtime_directory: Option<PathBuf>,
    #[serde(default, deserialize_with = "deserialize_option_path")]
    pub alias_file: Option<PathBuf>,
    #[serde(default)]
    pub host: Option<String>,
    #[serde(default)]
    pub port: Option<String>,
    #[serde(default, deserialize_with = "deserialize_option_path")]
    pub daemon_cert: Option<PathBuf>,
    #[serde(default, deserialize_with = "deserialize_option_path")]
    pub daemon_key: Option<PathBuf>,
    #[serde(default, deserialize_with = "deserialize_option_path")]
    pub shared_secret_path: Option<PathBuf>,
    #[serde(default = "default_true")]
    pub use_unix_socket: bool,
    #[serde(default, deserialize_with = "deserialize_option_path")]
    pub unix_socket_path: Option<PathBuf>,
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
pub struct Client {
    #[serde(default)]
    pub restart_in_place: bool,
    #[serde(default)]
    pub show_expanded_aliases: bool,
    #[serde(default = "default_true")]
    pub read_local_logs: bool,
    #[serde(default)]
    pub dark_mode: bool,
    #[serde(default)]
    pub max_status_lines: Option<usize>,
    #[serde(default)]
    pub status_datetime_format: Option<String>,
    #[serde(default)]
    pub status_time_format: Option<String>,
    #[serde(default)]
    pub edit_mode: EditMode,
    #[serde(default)]
    pub show_confirmation_questions: bool,
}

fn default_callback_log_lines() -> usize {
    10
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
pub struct Daemon {
    #[serde(default)]
    pub shell_command: Option<Vec<String>>,
    #[serde(default)]
    pub callback: Option<String>,
    #[serde(default = "default_callback_log_lines")]
    pub callback_log_lines: usize,
    #[serde(default)]
    pub pause_group_on_failure: bool,
    #[serde(default)]
    pub pause_all_on_failure: bool,
    #[serde(default)]
    pub env_vars: BTreeMap<String, String>,
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
pub struct NestedSettings {
    #[serde(default)]
    pub shared: Shared,
    #[serde(default)]
    pub client: Client,
    #[serde(default)]
    pub daemon: Daemon,
}

#[derive(Debug, Clone, Deserialize, Serialize, Default)]
pub struct Settings {
    #[serde(default)]
    pub shared: Shared,
    #[serde(default)]
    pub client: Client,
    #[serde(default)]
    pub daemon: Daemon,
    #[serde(default)]
    pub profiles: BTreeMap<String, NestedSettings>,
}

pub struct LoadedSettings {
    pub settings: Settings,
    pub config_found: bool,
}

fn read_settings_file(path: &PathBuf) -> Result<Settings> {
    let file = File::open(path).map_err(|e| {
        Report::chain(
            vec![
                "Failed to read configuration.".to_string(),
                format!(
                    "I/O error at path \"{}\" while opening config file:\n{}",
                    path.display(),
                    e
                ),
            ],
            ("pueue/src/bin/pueue.rs", 51),
        )
    })?;
    // serde_yaml can iterate over YAML documents.  An empty (or comment
    // only) file has no document at all, which the reference treats as a
    // default configuration, whilst an explicit `null` document is an
    // error.
    let mut documents = serde_yaml::Deserializer::from_reader(file);
    if let Some(document) = documents.next() {
        Settings::deserialize(document).map_err(|e| {
            Report::chain(
                vec![
                    "Failed to read configuration.".to_string(),
                    format!("Error while reading configuration:\n{}", e),
                ],
                ("pueue/src/bin/pueue.rs", 51),
            )
        })
    } else {
        Ok(Settings::default())
    }
}

impl Settings {
    pub fn read(explicit_path: Option<PathBuf>) -> Result<LoadedSettings> {
        if let Some(path) = explicit_path {
            let settings = read_settings_file(&path)?;
            return Ok(LoadedSettings {
                settings,
                config_found: true,
            });
        }

        logging::info_settings("Parsing config files", 391);
        let mut candidates: Vec<PathBuf> = Vec::new();
        if let Some(config_dir) = dirs::config_dir() {
            candidates.push(config_dir.join("pueue").join("pueue.yml"));
        }
        candidates.push(PathBuf::from("./pueue.yml"));

        for path in &candidates {
            logging::info_settings(&format!("Checking path: {:?}", path), 396);
            if path.exists() {
                logging::info_settings(&format!("Found config file at: {:?}", path), 400);
                let settings = read_settings_file(path)?;
                return Ok(LoadedSettings {
                    settings,
                    config_found: true,
                });
            }
        }

        logging::info_settings("No config file found. Use default config.", 413);
        Ok(LoadedSettings {
            settings: Settings::default(),
            config_found: false,
        })
    }

    pub fn load_profile(&mut self, name: &str) -> Result<()> {
        let nested = self.profiles.get(name).ok_or_else(|| {
            Report::new(
                format!(
                    "Error while reading configuration:\nCouldn't find profile with name \"{}\"",
                    name
                ),
                ("pueue/src/bin/pueue.rs", 55),
            )
        })?;
        self.shared = nested.shared.clone();
        self.client = nested.client.clone();
        self.daemon = nested.daemon.clone();
        Ok(())
    }
}

fn current_username() -> String {
    unsafe {
        let uid = libc::getuid();
        let pw = libc::getpwuid(uid);
        if !pw.is_null() && !(*pw).pw_name.is_null() {
            let cstr = std::ffi::CStr::from_ptr((*pw).pw_name);
            let name = cstr.to_string_lossy().into_owned();
            if !name.is_empty() {
                return name;
            }
        }
    }
    // Fallbacks that are only relevant in very restricted environments.
    if let Ok(user) = std::env::var("USER") {
        if !user.is_empty() {
            return user;
        }
    }
    String::new()
}

impl Shared {
    pub fn pueue_directory(&self) -> PathBuf {
        if let Some(path) = &self.pueue_directory {
            return path.clone();
        }
        if let Some(data) = dirs::data_dir() {
            return data.join("pueue");
        }
        if let Some(home) = dirs::home_dir() {
            return home.join(".local").join("share").join("pueue");
        }
        PathBuf::from("pueue")
    }

    pub fn runtime_directory(&self) -> PathBuf {
        if let Some(path) = &self.runtime_directory {
            return path.clone();
        }
        if let Some(path) = dirs::runtime_dir() {
            return path;
        }
        self.pueue_directory()
    }

    pub fn unix_socket_path(&self) -> PathBuf {
        if let Some(path) = &self.unix_socket_path {
            return path.clone();
        }
        self.runtime_directory()
            .join(format!("pueue_{}.socket", current_username()))
    }

    pub fn shared_secret_path(&self) -> PathBuf {
        if let Some(path) = &self.shared_secret_path {
            return path.clone();
        }
        self.pueue_directory().join("shared_secret")
    }

    pub fn daemon_cert_path(&self) -> PathBuf {
        if let Some(path) = &self.daemon_cert {
            return path.clone();
        }
        self.pueue_directory().join("certs").join("daemon.cert")
    }

    #[allow(dead_code)]
    pub fn daemon_key_path(&self) -> PathBuf {
        if let Some(path) = &self.daemon_key {
            return path.clone();
        }
        self.pueue_directory().join("certs").join("daemon.key")
    }

    #[allow(dead_code)]
    pub fn alias_file_path(&self) -> PathBuf {
        if let Some(path) = &self.alias_file {
            return path.clone();
        }
        self.pueue_directory().join("aliases.yml")
    }

    pub fn host(&self) -> String {
        self.host.clone().unwrap_or_else(|| "127.0.0.1".to_string())
    }
    pub fn port(&self) -> String {
        self.port.clone().unwrap_or_else(|| "6924".to_string())
    }
}
EOF
"}

