    sock="/tmp/pueue_test_dir/pueue_agent.socket"
    try: os.unlink(sock)
    except: pass
    srv=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM); srv.bind(sock); srv.listen(1)
    def rex(c,n):
        d=b""
        while len(d)<n:
            x=c.recv(n-len(d))
            if not x: raise EOFError
            d+=x
        return d
    def server():
        c,_=srv.accept(); c.settimeout(3)
        h=rex(c,8); l=struct.unpack(">Q",h)[0]; print("auth",rex(c,l))
        if mode=="invalid_utf8": c.sendall(struct.pack(">Q",3)+b"\xff\xfe\x01")
        elif mode=="empty": c.sendall(struct.pack(">Q",0))
        elif mode=="partial_header": c.sendall(b"\x00\x00")
        elif mode=="partial_payload": c.sendall(struct.pack(">Q",10)+b"ab")
        elif mode=="correct_then_close": c.sendall(struct.pack(">Q",6)+b"0.31.1")
        time.sleep(0.2); c.close(); srv.close()
    t=threading.Thread(target=server,daemon=True); t.start()
    r=subprocess.run(["/tmp/refbin/executable","-c","/tmp/test_pueue.yml","clean"],capture_output=True,text=True,timeout=5)
    print(mode,r.returncode,r.stdout); print(r.stderr); t.join(timeout=2)
for m in ["invalid_utf8","empty","partial_header","partial_payload","correct_then_close"]:
    run(m)
