use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, HashMap};
use std::fmt;
use std::path::PathBuf;
use std::str::FromStr;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum TaskResult {
    Success,
    Failed(i32),
    Errored,
    Killed,
    DependencyFailed,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum TaskStatus {
    Locked {
        previous_status: String,
    },
    Stashed {
        enqueue_at: Option<DateTime<Utc>>,
    },
    Queued {
        enqueued_at: DateTime<Utc>,
    },
    Running {
        enqueued_at: DateTime<Utc>,
        start: DateTime<Utc>,
    },
    Paused {
        enqueued_at: DateTime<Utc>,
        start: DateTime<Utc>,
    },
    Done {
        enqueued_at: DateTime<Utc>,
        start: DateTime<Utc>,
        end: DateTime<Utc>,
        result: TaskResult,
    },
}

#[derive(Clone, PartialEq, Serialize, Deserialize)]
pub struct Task {
    pub id: usize,
    pub created_at: DateTime<Utc>,
    pub original_command: String,
    pub command: String,
    pub path: PathBuf,
    pub envs: HashMap<String, String>,
    pub group: String,
    pub dependencies: Vec<usize>,
    pub priority: i32,
    #[serde(default)]
    pub label: Option<String>,
    pub status: TaskStatus,
}

impl fmt::Debug for Task {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Task")
            .field("id", &self.id)
            .field("original_command", &self.original_command)
            .field("command", &self.command)
            .field("path", &self.path)
            .field("envs", &"hidden")
            .field("group", &self.group)
            .field("dependencies", &self.dependencies)
            .field("label", &self.label)
            .field("status", &self.status)
            .field("priority", &self.priority)
            .finish()
    }
}

impl Task {
    pub fn is_done(&self) -> bool {
        matches!(self.status, TaskStatus::Done { .. })
    }
    pub fn display_status(&self) -> String {
        match &self.status {
            TaskStatus::Locked { .. } => "Locked".to_string(),
            TaskStatus::Stashed { .. } => "Stashed".to_string(),
            TaskStatus::Queued { .. } => "Queued".to_string(),
            TaskStatus::Running { .. } => "Running".to_string(),
            TaskStatus::Paused { .. } => "Paused".to_string(),
            TaskStatus::Done { result, .. } => match result {
                TaskResult::Success => "Success".to_string(),
                TaskResult::Failed(code) => format!("Failed ({})", code),
                TaskResult::Errored => "Errored".to_string(),
                TaskResult::Killed => "Killed".to_string(),
                TaskResult::DependencyFailed => "Dependency failed".to_string(),
            },
        }
    }
    pub fn start(&self) -> Option<DateTime<Utc>> {
        match self.status {
            TaskStatus::Running { start, .. }
            | TaskStatus::Paused { start, .. }
            | TaskStatus::Done { start, .. } => Some(start),
            _ => None,
        }
    }
    pub fn end(&self) -> Option<DateTime<Utc>> {
        match self.status {
            TaskStatus::Done { end, .. } => Some(end),
            _ => None,
        }
    }
    pub fn enqueue_at(&self) -> Option<DateTime<Utc>> {
        match self.status {
            TaskStatus::Stashed { enqueue_at } => enqueue_at,
            _ => None,
        }
    }
}

