    pub send_logs: bool,
    pub lines: Option<usize>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct StreamRequest {
    pub tasks: TaskSelection,
    pub lines: Option<usize>,
}

