}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ResetRequest {
    pub target: ResetTarget,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Shutdown {
    Graceful,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum Request {
    Add(AddTask),
    Remove(Vec<usize>),
    Switch(SwitchRequest),
    Stash(StashRequest),
    Enqueue(EnqueueRequest),
    Start(StartRequest),
    Restart(RestartRequest),
