use crate::errors::{Report, Result};
use crate::logging;
use crate::protocol::{Request, Response};
use crate::settings::{Settings, PROTOCOL_VERSION};
use std::io::{self, Read, Write};
use std::os::unix::net::UnixStream;
use std::net::TcpStream;

trait ReadWrite: Read + Write {}
impl ReadWrite for UnixStream {}
impl ReadWrite for TcpStream {}
// A boxed stream returned by an external TLS helper process is defined in
// tls_stream.rs.
impl ReadWrite for crate::tls_stream::TlsStream {}

pub struct Client {
    stream: Box<dyn ReadWrite>,
}

fn io_error_display(e: &io::Error) -> String {
    if e.kind() == io::ErrorKind::UnexpectedEof {
        "early eof".to_string()
    } else {
        e.to_string()
    }
}

pub fn load_daemon_cert(settings: &Settings) -> Result<Vec<u8>> {
    let path = settings.shared.daemon_cert_path();
    let contents = std::fs::read(&path).map_err(|e| {
        Report::new(
            format!(
                "Invalid or malformed certificate: Failed to parse daemon certificate:\nIo({:?})",
                e
            ),
            ("pueue/src/bin/pueue.rs", 90),
        )
    })?;
    parse_first_pem_certificate(&contents).map_err(|msg| {
        Report::new(
            format!(
                "Invalid or malformed certificate: Failed to parse daemon certificate:\n{}",
                msg
            ),
            ("pueue/src/bin/pueue.rs", 90),
        )
    })
}

fn base64_value(c: u8) -> Option<u8> {
    match c {
        b'A'..=b'Z' => Some(c - b'A'),
        b'a'..=b'z' => Some(c - b'a' + 26),
        b'0'..=b'9' => Some(c - b'0' + 52),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}

fn decode_base64(input: &[u8]) -> std::result::Result<Vec<u8>, String> {
    // Remove whitespace, mirroring PEM handling.
    let mut clean: Vec<u8> = Vec::new();
    for &c in input {
        if !c.is_ascii_whitespace() {
            clean.push(c);
        }
    }
    // Find invalid characters first, reporting in the style of the
    // base64 crate used by rustls-pemfile.
    for &c in &clean {
        if c != b'=' && base64_value(c).is_none() {
            return Err(format!(
                "Base64Decode(\"InvalidCharacter({})\")",
                c
            ));
        }
    }
    if clean.len() % 4 == 1 {
        return Err("Base64Decode(\"InvalidLength\")".to_string());
    }
    // Pad if needed.
    while clean.len() % 4 != 0 {
        clean.push(b'=');
    }
    let mut out = Vec::new();
    for chunk in clean.chunks(4) {
        let mut vals = [0u8; 4];
        let mut pad = 0usize;
        for i in 0..4 {
            if chunk[i] == b'=' {
                pad += 1;
                vals[i] = 0;
            } else {
                vals[i] = base64_value(chunk[i]).unwrap();
            }
        }
        let triple = ((vals[0] as u32) << 18)
            | ((vals[1] as u32) << 12)
            | ((vals[2] as u32) << 6)
            | vals[3] as u32;
        out.push((triple >> 16) as u8);
        if pad < 2 {
            out.push((triple >> 8) as u8);
        }
        if pad < 1 {
            out.push(triple as u8);
        }
    }
    Ok(out)
}

fn parse_first_pem_certificate(data: &[u8]) -> std::result::Result<Vec<u8>, String> {
    let text = String::from_utf8_lossy(data);
    let mut in_cert = false;
    let mut b64 = String::new();
    for line in text.lines() {
        let line = line.trim_end_matches('\r');
        if !in_cert {
            if line.trim() == "-----BEGIN CERTIFICATE-----" {
                in_cert = true;
            }
            continue;
        }
        if line.trim() == "-----END CERTIFICATE-----" {
            if b64.is_empty() {
                return Err("NoItemsFound".to_string());
            }
            return decode_base64(b64.as_bytes());
        }
        // PEM headers within a block contain a colon and should be skipped.
        if line.contains(':') && !line.chars().all(|c| c.is_ascii_alphanumeric() || c == '+' || c == '/' || c == '=') {
            continue;
        }
        b64.push_str(line.trim());
    }
    Err("NoItemsFound".to_string())
}

impl Client {
    pub fn new(
        settings: &Settings,
        secret: Vec<u8>,
        cert_der: Option<Vec<u8>>,
        suppress_version_warn: bool,
    ) -> Result<Self> {
        let mut stream: Box<dyn ReadWrite> = if settings.shared.use_unix_socket {
            let path = settings.shared.unix_socket_path();
            match UnixStream::connect(&path) {
                Ok(s) => Box::new(s),
                Err(e) => {
                    return Err(Report::chain(
                        vec![
                            "Failed to initialize client.".to_string(),
                            "Failed to initialize stream.".to_string(),
                            format!(
                                "I/O error at path \"{}\" while connecting to daemon. Did you start it?:\n{}",
                                path.display(),
                                e
                            ),
                        ],
                        ("/workspace/pueue_lib/src/network/client.rs", 85),
                    ))
                }
            }
        } else {
            let host = settings.shared.host();
            let port = settings.shared.port();
            let address = format!("{}:{}", host, port);
            let tcp = TcpStream::connect(&address).map_err(|_| {
                Report::chain(
                    vec![
                        "Failed to initialize client.".to_string(),
                        "Failed to initialize stream.".to_string(),
                        format!(
                            "Failed to connect to the daemon on {}. Did you start it?",
                            address
                        ),
                    ],
                    ("/workspace/pueue_lib/src/network/client.rs", 85),
                )
            })?;
            // Establish TLS over this connection using the OpenSSL based
            // helper.  `cert_der` is the parsed daemon certificate that was
            // loaded by the caller in TCP mode.
            let _ = cert_der; // validation occurs inside the TLS helper via the file
            match crate::tls_stream::TlsStream::connect(tcp, settings, &host) {
                Ok(tls) => Box::new(tls),
                Err(e) => {
                    return Err(Report::chain(
                        vec![
                            "Failed to initialize client.".to_string(),
                            "Failed to initialize stream.".to_string(),
                            format!("Failed to initialize tls:\n{}", e),
                        ],
                        ("/workspace/pueue_lib/src/network/client.rs", 85),
                    ))
                }
            }
        };

        let mut client = Client { stream };

        // Authentication handshake: send the shared secret as a raw
        // length-prefixed payload and read back the daemon protocol
        // version as a raw payload.
        client.send_bytes(&secret).map_err(|r| {
            // Preserve an error that is already fully formed if it has
            // multiple levels; otherwise wrap it like stream setup.
            r
        })?;

        let version_bytes = client.receive_bytes_inner().map_err(|msg| {
            Report::chain(
                vec![
                    "Failed to initialize client.".to_string(),
                    "Failed to receive version during handshake with daemon.".to_string(),
                    msg,
                ],
                ("/workspace/pueue_lib/src/network/client.rs", 97),
            )
        })?;

        if version_bytes.is_empty() {
            return Err(Report::chain(
                vec![
                    "Failed to initialize client.".to_string(),
                    "Daemon went away after sending secret. Did you use the correct secret?"
                        .to_string(),
                ],
                ("/workspace/pueue_lib/src/network/client.rs", 99),
            ));
        }

        let version = String::from_utf8(version_bytes).map_err(|_| {
            Report::chain(
                vec![
                    "Failed to initialize client.".to_string(),
                    "Daemon sent invalid UTF-8. Did you use the correct secret?".to_string(),
                ],
                ("/workspace/pueue_lib/src/network/client.rs", 104),
            )
        })?;

        if version != PROTOCOL_VERSION && !suppress_version_warn {
            logging::log_event(
                logging::Level::Warn,
                "pueue_lib::network::client",
                "pueue_lib/src/network/client.rs:111",
                &format!(
                    "Different protocol version detected '{}'. Consider updating and restarting the daemon.",
                    version
                ),
            );
        }

        let _ = &mut client.stream;
        Ok(client)
    }

    pub fn send_bytes(&mut self, payload: &[u8]) -> Result<()> {
        let header = (payload.len() as u64).to_be_bytes();
        self.stream.write_all(&header).map_err(|e| {
            Report::new(
                format!("I/O error while sending request:\n{}", io_error_display(&e)),
                ("/workspace/pueue_lib/src/network/protocol.rs", 50),
            )
        })?;
        self.stream.write_all(payload).map_err(|e| {
            Report::new(
                format!("I/O error while sending request:\n{}", io_error_display(&e)),
                ("/workspace/pueue_lib/src/network/protocol.rs", 50),
            )
        })?;
        let _ = self.stream.flush();
        Ok(())
    }

    pub fn send_request(&mut self, request: &Request) -> Result<()> {
        if logging::enabled(logging::Level::Debug) {
            logging::log_event(
                logging::Level::Debug,
                "pueue_lib::network::protocol",
                "pueue_lib/src/network/protocol.rs:50",
                &format!("Sending message: {:#?}", request),
            );
        }
        let mut payload: Vec<u8> = Vec::new();
        ciborium::into_writer(request, &mut payload).expect("serializing a request cannot fail");
        self.send_bytes(&payload)
    }

    /// Receive raw payload.  Errors are returned as plain strings so
    /// callers can add their own wrapping/location.
    fn receive_bytes_inner(&mut self) -> std::result::Result<Vec<u8>, String> {
        let mut header = [0u8; 8];
        self.stream
            .read_exact(&mut header)
            .map_err(|e| format!("I/O error while reading request size header:\n{}", io_error_display(&e)))?;
        let length = u64::from_be_bytes(header);
        if length > 100_000_000 {
            logging::log_event(
                logging::Level::Warn,
                "pueue_lib::network::protocol",
                "pueue_lib/src/network/protocol.rs:80",
                &format!("Client is sending a large payload: {} bytes.", length),
            );
        }
        if length == 0 {
            return Ok(Vec::new());
        }
        let mut payload: Vec<u8> = Vec::new();
        // Reading in chunks avoids a huge up-front allocation for a
        // hostile/corrupt length header while still mirroring the
        // reference behaviour for well-formed payloads.
        let mut remaining = length;
        let mut buf = vec![0u8; 8192];
        while remaining > 0 {
            let to_read = std::cmp::min(buf.len() as u64, remaining) as usize;
            match self.stream.read(&mut buf[..to_read]) {
                Ok(0) => {
                    return Err("Connection went away while receiving payload.".to_string());
                }
                Ok(n) => {
                    payload.extend_from_slice(&buf[..n]);
                    remaining -= n as u64;
                }
                Err(e) => {
                    return Err(format!(
                        "I/O error while receiving payload:\n{}",
                        io_error_display(&e)
                    ));
                }
            }
        }
        Ok(payload)
    }

    pub fn receive_response(&mut self, location: (&str, u32)) -> Result<Response> {
        let payload = self
            .receive_bytes_inner()
            .map_err(|msg| Report::new(msg, location))?;
