    3h                    // 3 hours from now
    3600s                 // 3600 seconds from now";

fn task_ids_arg(help: &'static str, required: bool) -> Arg {
    let mut arg = Arg::new("task_ids")
        .value_name("TASK_IDS")
        .help(help)
        .value_parser(clap::value_parser!(usize))
        .num_args(0..)
        .action(ArgAction::Append);
    if required {
        arg = arg.required(true).num_args(1..);
    }
    arg
}

fn group_arg(help: &'static str, conflicts_all: bool) -> Arg {
    let mut arg = Arg::new("group")
        .short('g')
        .long("group")
        .value_name("GROUP")
        .help(help)
        .num_args(1);
    if conflicts_all {
        arg = arg.conflicts_with("all");
    }
    arg
}

fn all_arg(help: &'static str) -> Arg {
    Arg::new("all")
        .short('a')
        .long("all")
        .help(help)
        .action(ArgAction::SetTrue)
}

pub fn build_cli() -> Command {
    let add = Command::new("add")
        .about("Enqueue a task for execution")
        .long_about("Enqueue a task for execution.\n\nThere're many different options when scheduling a task. Check the individual option help texts for more information. Furthermore, please remember that scheduled commands are executed via your system shell. This means that the command needs proper shell escaping. The safest way to preserve shell escaping is to surround your command with quotes, for example:\n\npueue add 'ls $HOME && echo \"Some string\"'")
        .arg(
            Arg::new("command")
                .value_name("COMMAND")
                .help("The command to be added")
                .required(true)
                .num_args(1..)
                .trailing_var_arg(true)
                .allow_hyphen_values(true),
        )
        .arg(
            Arg::new("working_directory")
                .short('w')
                .long("working-directory")
                .value_name("working-directory")
                .help("Specify current working directory")
                .value_parser(clap::value_parser!(PathBuf))
                .num_args(1),
        )
        .arg(
            Arg::new("escape")
                .short('e')
                .long("escape")
                .help("Escape any special shell characters (\" \", \"&\", \"!\", etc.).\nBeware: This implicitly disables nearly all shell specific syntax (\"&&\", \"&>\").")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("start_immediately")
                .short('i')
                .long("immediate")
                .help("Immediately start the task")
                .action(ArgAction::SetTrue)
                .conflicts_with("stashed"),
        )
        .arg(
            Arg::new("follow")
                .long("follow")
                .help("Immediately follow a task, if it's started with --immediate")
                .action(ArgAction::SetTrue)
                .conflicts_with("print_task_id")
                .requires("start_immediately"),
        )
        .arg(
            Arg::new("stashed")
                .short('s')
                .long("stashed")
                .help("Create the task in Stashed state")
                .long_help("Create the task in Stashed state.\n\nUseful to avoid immediate execution if the queue is empty.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("delay_until")
                .short('d')
                .long("delay")
                .value_name("delay")
                .help("Prevents the task from being enqueued until 'delay' elapses. See \"enqueue\" for accepted formats")
                .value_parser(delay_parser)
                .num_args(1)
                .conflicts_with("start_immediately"),
        )
        .arg(
            Arg::new("group")
                .short('g')
                .long("group")
                .value_name("GROUP")
                .help("Assign the task to a group")
                .long_help("Assign the task to a group.\n\nGroups kind of act as separate queues. All groups run in parallel and you can specify the amount of parallel tasks for each group. If no group is specified, the default group will be used.\n\nCreate groups via the `pueue group` subcommand")
                .num_args(1),
        )
        .arg(
            Arg::new("dependencies")
                .short('a')
                .long("after")
                .value_name("after")
                .help("Start the task once all specified tasks have successfully finished")
                .long_help("Start the task once all specified tasks have successfully finished.\n\nAs soon as one of the dependencies fails, this task will fail as well.")
                .value_parser(clap::value_parser!(usize))
                .num_args(1..)
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("priority")
                .short('o')
                .long("priority")
                .value_name("PRIORITY")
                .help("Start this task with a higher priority")
                .long_help("Start this task with a higher priority.\n\nThe higher the number, the faster it will be processed.")
                .value_parser(clap::value_parser!(i32))
                .num_args(1),
        )
        .arg(
            Arg::new("label")
                .short('l')
                .long("label")
                .value_name("LABEL")
                .help("Add some information for yourself")
                .long_help("Add some information for yourself.\n\nThis string will be shown in the \"status\" table. There's no additional logic connected to it.")
                .num_args(1),
        )
        .arg(
            Arg::new("print_task_id")
                .short('p')
                .long("print-task-id")
                .help("Only return the task id instead of a text")
                .long_help("Only return the task id instead of a text.\n\nThis is useful when working with dependencies in scripts.")
                .action(ArgAction::SetTrue),
        );

    let remove = Command::new("remove")
        .alias("rm")
        .about("Remove tasks from the list. Running or paused tasks need to be killed first")
        .arg(task_ids_arg("The task ids to be removed", true));

    let switch = Command::new("switch")
        .about("Switches the queue position of two commands")
        .long_about("Switches the queue position of two commands.\n\nOnly works on queued and stashed commands.")
        .arg(Arg::new("task_id_1").value_name("TASK_ID_1").help("The first task id").required(true).value_parser(clap::value_parser!(usize)))
        .arg(Arg::new("task_id_2").value_name("TASK_ID_2").help("The second task id").required(true).value_parser(clap::value_parser!(usize)));

    let stash = Command::new("stash")
        .about("Stash a task. Stashed tasks won't be automatically started")
        .long_about("Stash a task. Stashed tasks won't be automatically started.\n\nThe enqueue an item, use the `pueue enqueue` subcommand. Stashed entries can also be explicitely started via `pueue start $task_id`.")
        .arg(task_ids_arg("Stash these specific tasks", false))
        .arg(group_arg("Stash all queued tasks in a group", true))
        .arg(all_arg("Stash all queued tasks across all groups"))
        .arg(
            Arg::new("delay_until")
                .short('d').long("delay").value_name("delay")
                .help("Delay enqueuing these tasks until 'delay' elapses. See DELAY FORMAT below")
                .value_parser(delay_parser).num_args(1),
        );

    let enqueue = Command::new("enqueue")
        .about("Enqueue stashed tasks. They'll be handled normally afterwards")
        .long_about("Enqueue stashed tasks. They'll be handled normally afterwards.\n\nEnqueues all stashed task in the default group if no arguments are given.")
        .after_help(DELAY_FORMAT)
        .after_long_help(DELAY_FORMAT)
        .arg(task_ids_arg("Enqueue these specific tasks", false))
        .arg(group_arg("Enqueue all stashed tasks in a group", true))
        .arg(all_arg("Enqueue all stashed tasks across all groups"))
        .arg(
            Arg::new("delay_until")
                .short('d').long("delay").value_name("delay")
                .help("Delay enqueuing these tasks until 'delay' elapses. See DELAY FORMAT below")
                .value_parser(delay_parser).num_args(1),
        );

    let start = Command::new("start")
        .about("Resume operation of specific tasks or groups of tasks")
        .long_about("Resume operation of specific tasks or groups of tasks.\n\nWithout any parameters this resumes the default group and all its tasks. Can also be used force-start specific tasks, which **ignores** any group parallelism limits or dependencies a task my have!")
        .arg(task_ids_arg("Start these specific tasks. Paused tasks will resumed. Queued/Stashed tasks will be force-started", false))
        .arg(
            Arg::new("group").short('g').long("group").value_name("GROUP")
                .help("Resume a specific group and all paused tasks in it")
                .long_help("Resume a specific group and all paused tasks in it.\n\nThe group will be set to running and its paused tasks will be resumed.")
                .num_args(1).conflicts_with("all")
        )
        .arg(
            Arg::new("all").short('a').long("all")
                .help("Resume all groups!")
                .long_help("Resume all groups!\n\nAll groups will be set to running and paused tasks will be resumed.")
                .action(ArgAction::SetTrue)
        );

    let restart = Command::new("restart")
        .alias("re")
        .about("Restart failed or successful task(s)")
        .long_about("Restart failed or successful task(s).\n\nBy default, identical tasks will be created and enqueued, but it's possible to restart in-place. You can also edit a few properties, such as the path and the command, before restarting.")
        .arg(task_ids_arg("Restart these specific tasks", false))
        .arg(
            Arg::new("all_failed").short('a').long("all-failed")
                .help("Restart all failed tasks across all groups")
                .long_help("Restart all failed tasks across all groups.\n\nThis is nice for usage in combination with `-i/--in-place` (or the respective config option).")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("failed_in_group").short('g').long("failed-in-group").value_name("FAILED_IN_GROUP")
                .help("Like `--all-failed`, but only restart tasks failed tasks of a specific group")
                .num_args(1).conflicts_with("all_failed")
        )
        .arg(
            Arg::new("start_immediately").short('k').long("immediate")
