                .action(ArgAction::SetTrue).conflicts_with("stashed")
        )
        .arg(
            Arg::new("stashed").short('s').long("stashed")
                .help("Set the restarted task to a \"Stashed\" state. Useful to avoid immediate execution")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("in_place").short('i').long("in-place")
                .help("Restart the task by reusing the already existing tasks. This will overwrite any previous logs of the restarted tasks")
                .long_help("Restart the task by reusing the already existing tasks. This will overwrite any previous logs of the restarted tasks.\n\nThis can also be enabled by default via the `restart_in_place` config option.")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("not_in_place").long("not-in-place")
                .help("Restart the task by creating a new identical tasks. Only necessary if you have the `restart_in_place` configuration set to true")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("edit").short('e').long("edit")
                .help("Edit the task before restarting")
                .action(ArgAction::SetTrue)
