    let pause = Command::new("pause")
        .about("Either pause running tasks or specific groups of tasks")
        .long_about("Either pause running tasks or specific groups of tasks.\n\nBy default, pauses the default group and all its tasks. A paused queue (group) won't start any new tasks.")
        .arg(task_ids_arg("Pause these specific tasks", false))
        .arg(group_arg("Pause a specific group", true))
        .arg(all_arg("Pause all groups!"))
        .arg(
            Arg::new("wait").short('w').long("wait")
                .help("Pause the specified groups, but let already running tasks finish by themselves")
                .action(ArgAction::SetTrue)
        );

    let kill = Command::new("kill")
        .about("Kill specific running tasks or whole task groups")
        .long_about("Kill specific running tasks or whole task groups.\n\nKills all tasks of the default group when no ids or a specific group are provided.")
        .arg(task_ids_arg("Kill these specific tasks", false))
        .arg(group_arg("Kill all running tasks in a group. This also pauses the group", true))
        .arg(all_arg("Kill all running tasks across ALL groups. This also pauses all groups"))
        .arg(
            Arg::new("signal").short('s').long("signal").value_name("SIGNAL")
