const STATUS_QUERY_LONG: &str = "\
Users can specify a custom query to filter for specific values, order by a column
or limit the amount of tasks listed.

Syntax:
   [column_selection]? [filter]* [order_by]? [limit]?

where:
  - column_selection := `columns=[column]([column],)*`
  - column := `id | status | command | label | path | enqueue_at | dependencies | start |
  end`
  - filter := `[filter_column] [filter_op] [filter_value]`
    (note: not all columns support all operators, see \"Filter columns\" below.)
  - filter_column := `status | command | label | start | end | enqueue_at`
  - filter_op := `= | != | < | > | %=`
    (`%=` means 'contains', as in the test value is a substring of the column value)
  - order_by := `order_by [column] [order_direction]`
  - order_direction := `asc | desc`
  - limit := `[limit_type]? [limit_count]`
  - limit_type := `first | last`
  - limit_count := a positive integer

Filter columns:
  - `status` supports the operators `=`, `!=`
    against test values that are:
      - strings like `queued`, `stashed`, `paused`, `running`, `success`, `failed`
  - `command`, `label` support the operators `=`, `!=`, `%=`
    against test values that are:
      - strings like `some text`
  - `start`, `end`, `enqueue_at` contain a datetime
    which support the operators `=`, `!=`, `<`, `>`
    against test values that are:
      - date like `YYYY-MM-DD`
      - time like `HH:mm:ss` or `HH:mm`
      - datetime like `YYYY-MM-DDHH:mm:ss`
        (note there is currently no separator between the date and the time)

Examples:
  - `status=running`
  - `command%=echo`
  - `label=mytask`
  - `columns=id,status,command status=running start > 2023-05-2112:03:17 order_by command
  first 5`

The formal syntax is defined here:
https://github.com/Nukesor/pueue/blob/main/pueue/src/client/commands/state/query/syntax.pest

More documentation is on the query syntax PR:
https://github.com/Nukesor/pueue/issues/350#issue-1359083118";

fn get_many<T: Clone + Send + Sync + 'static>(
    matches: &clap::ArgMatches,
    id: &str,
) -> Vec<T> {
    matches
        .get_many::<T>(id)
        .map(|values| values.cloned().collect())
        .unwrap_or_default()
}

pub fn parse_opt(matches: &clap::ArgMatches) -> Opt {
    let verbose = *matches.get_one::<u8>("verbose").unwrap_or(&0);
    let color = match matches.get_one::<String>("color").map(|s| s.as_str()) {
        Some("never") => ColorChoice::Never,
        Some("always") => ColorChoice::Always,
        _ => ColorChoice::Auto,
    };
    let config = matches.get_one::<PathBuf>("config").cloned();
    let profile = matches.get_one::<String>("profile").cloned();

    let command = match matches.subcommand() {
        Some(("add", sub)) => Some(SubCommand::Add {
            command: get_many::<String>(sub, "command"),
            working_directory: sub.get_one::<PathBuf>("working_directory").cloned(),
            escape: sub.get_flag("escape"),
            start_immediately: sub.get_flag("start_immediately"),
            follow: sub.get_flag("follow"),
            stashed: sub.get_flag("stashed"),
            delay_until: sub.get_one::<DateTime<Utc>>("delay_until").cloned(),
            group: sub.get_one::<String>("group").cloned(),
            dependencies: get_many::<usize>(sub, "dependencies"),
            priority: sub.get_one::<i32>("priority").cloned(),
            label: sub.get_one::<String>("label").cloned(),
            print_task_id: sub.get_flag("print_task_id"),
        }),
        Some(("remove", sub)) => Some(SubCommand::Remove {
            task_ids: get_many::<usize>(sub, "task_ids"),
        }),
        Some(("switch", sub)) => Some(SubCommand::Switch {
            task_id_1: *sub.get_one::<usize>("task_id_1").unwrap(),
            task_id_2: *sub.get_one::<usize>("task_id_2").unwrap(),
        }),
        Some(("stash", sub)) => Some(SubCommand::Stash {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            delay_until: sub.get_one::<DateTime<Utc>>("delay_until").cloned(),
        }),
        Some(("enqueue", sub)) => Some(SubCommand::Enqueue {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            delay_until: sub.get_one::<DateTime<Utc>>("delay_until").cloned(),
        }),
        Some(("start", sub)) => Some(SubCommand::Start {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
        }),
        Some(("restart", sub)) => Some(SubCommand::Restart {
            task_ids: get_many::<usize>(sub, "task_ids"),
            all_failed: sub.get_flag("all_failed"),
            failed_in_group: sub.get_one::<String>("failed_in_group").cloned(),
            start_immediately: sub.get_flag("start_immediately"),
            stashed: sub.get_flag("stashed"),
            in_place: sub.get_flag("in_place"),
            not_in_place: sub.get_flag("not_in_place"),
            edit: sub.get_flag("edit"),
        }),
        Some(("pause", sub)) => Some(SubCommand::Pause {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            wait: sub.get_flag("wait"),
        }),
        Some(("kill", sub)) => Some(SubCommand::Kill {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            signal: sub.get_one::<Signal>("signal").cloned(),
        }),
        Some(("send", sub)) => Some(SubCommand::Send {
            task_id: *sub.get_one::<usize>("task_id").unwrap(),
            input: sub.get_one::<String>("input").unwrap().clone(),
        }),
        Some(("edit", sub)) => Some(SubCommand::Edit {
            task_ids: get_many::<usize>(sub, "task_ids"),
        }),
        Some(("env", sub)) => match sub.subcommand() {
            Some(("set", subsub)) => Some(SubCommand::Env {
                cmd: EnvCmd::Set {
                    task_id: *subsub.get_one::<usize>("task_id").unwrap(),
                    key: subsub.get_one::<String>("key").unwrap().clone(),
                    value: subsub.get_one::<String>("value").unwrap().clone(),
                },
            }),
            Some(("unset", subsub)) => Some(SubCommand::Env {
                cmd: EnvCmd::Unset {
                    task_id: *subsub.get_one::<usize>("task_id").unwrap(),
                    key: subsub.get_one::<String>("key").unwrap().clone(),
                },
            }),
            _ => None,
        },
        Some(("group", sub)) => {
            let cmd = match sub.subcommand() {
                Some(("add", subsub)) => Some(GroupCmd::Add {
                    name: subsub.get_one::<String>("name").unwrap().clone(),
                    parallel: subsub.get_one::<usize>("parallel").cloned(),
                }),
                Some(("remove", subsub)) => Some(GroupCmd::Remove {
                    name: subsub.get_one::<String>("name").unwrap().clone(),
                }),
                _ => None,
            };
            Some(SubCommand::Group {
                json: sub.get_flag("json"),
                cmd,
            })
        }
        Some(("status", sub)) => Some(SubCommand::Status {
            query: get_many::<String>(sub, "query"),
            json: sub.get_flag("json"),
            group: sub.get_one::<String>("group").cloned(),
        }),
        Some(("log", sub)) => Some(SubCommand::Log {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            json: sub.get_flag("json"),
            lines: sub.get_one::<usize>("lines").cloned(),
            full: sub.get_flag("full"),
        }),
        Some(("follow", sub)) => Some(SubCommand::Follow {
            task_id: sub.get_one::<usize>("task_id").cloned(),
            lines: sub.get_one::<usize>("lines").cloned(),
        }),
        Some(("wait", sub)) => Some(SubCommand::Wait {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            quiet: sub.get_flag("quiet"),
            status: sub.get_one::<WaitStatus>("status").cloned(),
        }),
        Some(("clean", sub)) => Some(SubCommand::Clean {
            successful_only: sub.get_flag("successful_only"),
            group: sub.get_one::<String>("group").cloned(),
        }),
        Some(("reset", sub)) => Some(SubCommand::Reset {
            groups: get_many::<String>(sub, "groups"),
            force: sub.get_flag("force"),
        }),
        Some(("shutdown", _)) => Some(SubCommand::Shutdown),
        Some(("parallel", sub)) => Some(SubCommand::Parallel {
            parallel_tasks: sub.get_one::<usize>("parallel_tasks").cloned(),
            group: sub.get_one::<String>("group").cloned(),
        }),
        Some(("completions", sub)) => Some(SubCommand::Completions {
            shell: sub.get_one::<String>("shell").unwrap().clone(),
            output_directory: sub.get_one::<PathBuf>("output_directory").cloned(),
        }),
        _ => None,
    };

    Opt {
        verbose,
        color,
        config,
        profile,
        command,
    }
}
