#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WaitStatus {
    Queued,
    Running,
    Done,
    Success,
}

impl FromStr for WaitStatus {
    type Err = String;
    fn from_str(s: &str) -> std::result::Result<Self, Self::Err> {
        match s {
            "Queued" | "queued" => Ok(WaitStatus::Queued),
            "Running" | "running" => Ok(WaitStatus::Running),
            "Done" | "done" => Ok(WaitStatus::Done),
            "Success" | "success" => Ok(WaitStatus::Success),
            _ => Err("Matching variant not found".to_string()),
        }
    }
}

