    pub config: Option<PathBuf>,
    pub profile: Option<String>,
    pub command: Option<SubCommand>,
}

fn delay_parser(s: &str) -> std::result::Result<DateTime<Utc>, String> {
    parse_delay(s)
}

const DELAY_FORMAT: &str = "\
DELAY FORMAT:

    The --delay argument must be either a number of seconds or a \"date expression\" similar to GNU
    \"date -d\" with some extensions. It does not attempt to parse all natural language, but is
    incredibly flexible. Here are some supported examples.

    2020-04-01T18:30:00   // RFC 3339 timestamp
    2020-4-1 18:2:30      // Optional leading zeros
    2020-4-1 5:30pm       // Informal am/pm time
    2020-4-1 5pm          // Optional minutes and seconds
    April 1 2020 18:30:00 // English months
    1 Apr 8:30pm          // Implies current year
    4/1                   // American form date
    wednesday 10:30pm     // The closest wednesday in the future at 22:30
    wednesday             // The closest wednesday in the future
    4 months              // 4 months from today at 00:00:00
    1 week                // 1 week at the current time
    1days                 // 1 day from today at the current time
    1d 03:00              // The closest 3:00 after 1 day (24 hours)
    3h                    // 3 hours from now
    3600s                 // 3600 seconds from now";

fn task_ids_arg(help: &'static str, required: bool) -> Arg {
    let mut arg = Arg::new("task_ids")
        .value_name("TASK_IDS")
        .help(help)
        .value_parser(clap::value_parser!(usize))
        .num_args(0..)
        .action(ArgAction::Append);
    if required {
        arg = arg.required(true).num_args(1..);
    }
    arg
}

fn group_arg(help: &'static str, conflicts_all: bool) -> Arg {
    let mut arg = Arg::new("group")
        .short('g')
        .long("group")
        .value_name("GROUP")
        .help(help)
        .num_args(1);
    if conflicts_all {
        arg = arg.conflicts_with("all");
    }
    arg
}

fn all_arg(help: &'static str) -> Arg {
    Arg::new("all")
        .short('a')
        .long("all")
        .help(help)
        .action(ArgAction::SetTrue)
}

pub fn build_cli() -> Command {
    let add = Command::new("add")
        .about("Enqueue a task for execution")
        .long_about("Enqueue a task for execution.\n\nThere're many different options when scheduling a task. Check the individual option help texts for more information. Furthermore, please remember that scheduled commands are executed via your system shell. This means that the command needs proper shell escaping. The safest way to preserve shell escaping is to surround your command with quotes, for example:\n\npueue add 'ls $HOME && echo \"Some string\"'")
        .arg(
            Arg::new("command")
                .value_name("COMMAND")
                .help("The command to be added")
                .required(true)
                .num_args(1..)
                .trailing_var_arg(true)
                .allow_hyphen_values(true),
        )
        .arg(
            Arg::new("working_directory")
                .short('w')
                .long("working-directory")
                .value_name("working-directory")
                .help("Specify current working directory")
                .value_parser(clap::value_parser!(PathBuf))
                .num_args(1),
        )
        .arg(
            Arg::new("escape")
                .short('e')
                .long("escape")
                .help("Escape any special shell characters (\" \", \"&\", \"!\", etc.).\nBeware: This implicitly disables nearly all shell specific syntax (\"&&\", \"&>\").")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("start_immediately")
                .short('i')
                .long("immediate")
                .help("Immediately start the task")
                .action(ArgAction::SetTrue)
                .conflicts_with("stashed"),
        )
        .arg(
            Arg::new("follow")
                .long("follow")
                .help("Immediately follow a task, if it's started with --immediate")
                .action(ArgAction::SetTrue)
                .conflicts_with("print_task_id")
                .requires("start_immediately"),
        )
        .arg(
            Arg::new("stashed")
                .short('s')
                .long("stashed")
                .help("Create the task in Stashed state")
                .long_help("Create the task in Stashed state.\n\nUseful to avoid immediate execution if the queue is empty.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("delay_until")
                .short('d')
                .long("delay")
                .value_name("delay")
                .help("Prevents the task from being enqueued until 'delay' elapses. See \"enqueue\" for accepted formats")
                .value_parser(delay_parser)
                .num_args(1)
                .conflicts_with("start_immediately"),
        )
        .arg(
            Arg::new("group")
                .short('g')
                .long("group")
                .value_name("GROUP")
                .help("Assign the task to a group")
                .long_help("Assign the task to a group.\n\nGroups kind of act as separate queues. All groups run in parallel and you can specify the amount of parallel tasks for each group. If no group is specified, the default group will be used.\n\nCreate groups via the `pueue group` subcommand")
                .num_args(1),
        )
        .arg(
            Arg::new("dependencies")
                .short('a')
                .long("after")
                .value_name("after")
                .help("Start the task once all specified tasks have successfully finished")
                .long_help("Start the task once all specified tasks have successfully finished.\n\nAs soon as one of the dependencies fails, this task will fail as well.")
                .value_parser(clap::value_parser!(usize))
                .num_args(1..)
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("priority")
                .short('o')
                .long("priority")
                .value_name("PRIORITY")
                .help("Start this task with a higher priority")
                .long_help("Start this task with a higher priority.\n\nThe higher the number, the faster it will be processed.")
                .value_parser(clap::value_parser!(i32))
                .num_args(1),
        )
        .arg(
            Arg::new("label")
                .short('l')
                .long("label")
                .value_name("LABEL")
                .help("Add some information for yourself")
                .long_help("Add some information for yourself.\n\nThis string will be shown in the \"status\" table. There's no additional logic connected to it.")
                .num_args(1),
        )
        .arg(
            Arg::new("print_task_id")
                .short('p')
                .long("print-task-id")
                .help("Only return the task id instead of a text")
                .long_help("Only return the task id instead of a text.\n\nThis is useful when working with dependencies in scripts.")
                .action(ArgAction::SetTrue),
        );

    let remove = Command::new("remove")
        .alias("rm")
        .about("Remove tasks from the list. Running or paused tasks need to be killed first")
        .arg(task_ids_arg("The task ids to be removed", true));

    let switch = Command::new("switch")
        .about("Switches the queue position of two commands")
        .long_about("Switches the queue position of two commands.\n\nOnly works on queued and stashed commands.")
        .arg(Arg::new("task_id_1").value_name("TASK_ID_1").help("The first task id").required(true).value_parser(clap::value_parser!(usize)))
        .arg(Arg::new("task_id_2").value_name("TASK_ID_2").help("The second task id").required(true).value_parser(clap::value_parser!(usize)));

    let stash = Command::new("stash")
        .about("Stash a task. Stashed tasks won't be automatically started")
        .long_about("Stash a task. Stashed tasks won't be automatically started.\n\nThe enqueue an item, use the `pueue enqueue` subcommand. Stashed entries can also be explicitely started via `pueue start $task_id`.")
        .arg(task_ids_arg("Stash these specific tasks", false))
        .arg(group_arg("Stash all queued tasks in a group", true))
        .arg(all_arg("Stash all queued tasks across all groups"))
        .arg(
            Arg::new("delay_until")
                .short('d').long("delay").value_name("delay")
                .help("Delay enqueuing these tasks until 'delay' elapses. See DELAY FORMAT below")
                .value_parser(delay_parser).num_args(1),
        );

    let enqueue = Command::new("enqueue")
        .about("Enqueue stashed tasks. They'll be handled normally afterwards")
        .long_about("Enqueue stashed tasks. They'll be handled normally afterwards.\n\nEnqueues all stashed task in the default group if no arguments are given.")
        .after_help(DELAY_FORMAT)
        .after_long_help(DELAY_FORMAT)
        .arg(task_ids_arg("Enqueue these specific tasks", false))
        .arg(group_arg("Enqueue all stashed tasks in a group", true))
        .arg(all_arg("Enqueue all stashed tasks across all groups"))
        .arg(
            Arg::new("delay_until")
                .short('d').long("delay").value_name("delay")
                .help("Delay enqueuing these tasks until 'delay' elapses. See DELAY FORMAT below")
                .value_parser(delay_parser).num_args(1),
        );

    let start = Command::new("start")
        .about("Resume operation of specific tasks or groups of tasks")
        .long_about("Resume operation of specific tasks or groups of tasks.\n\nWithout any parameters this resumes the default group and all its tasks. Can also be used force-start specific tasks, which **ignores** any group parallelism limits or dependencies a task my have!")
        .arg(task_ids_arg("Start these specific tasks. Paused tasks will resumed. Queued/Stashed tasks will be force-started", false))
        .arg(
            Arg::new("group").short('g').long("group").value_name("GROUP")
                .help("Resume a specific group and all paused tasks in it")
                .long_help("Resume a specific group and all paused tasks in it.\n\nThe group will be set to running and its paused tasks will be resumed.")
                .num_args(1).conflicts_with("all")
        )
        .arg(
            Arg::new("all").short('a').long("all")
                .help("Resume all groups!")
                .long_help("Resume all groups!\n\nAll groups will be set to running and paused tasks will be resumed.")
                .action(ArgAction::SetTrue)
        );

    let restart = Command::new("restart")
        .alias("re")
        .about("Restart failed or successful task(s)")
        .long_about("Restart failed or successful task(s).\n\nBy default, identical tasks will be created and enqueued, but it's possible to restart in-place. You can also edit a few properties, such as the path and the command, before restarting.")
        .arg(task_ids_arg("Restart these specific tasks", false))
        .arg(
            Arg::new("all_failed").short('a').long("all-failed")
                .help("Restart all failed tasks across all groups")
                .long_help("Restart all failed tasks across all groups.\n\nThis is nice for usage in combination with `-i/--in-place` (or the respective config option).")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("failed_in_group").short('g').long("failed-in-group").value_name("FAILED_IN_GROUP")
                .help("Like `--all-failed`, but only restart tasks failed tasks of a specific group")
                .num_args(1).conflicts_with("all_failed")
        )
        .arg(
            Arg::new("start_immediately").short('k').long("immediate")
                .help("Immediately start the tasks, no matter how many open slots there are. This will ignore any dependencies tasks may have")
                .action(ArgAction::SetTrue).conflicts_with("stashed")
        )
        .arg(
            Arg::new("stashed").short('s').long("stashed")
                .help("Set the restarted task to a \"Stashed\" state. Useful to avoid immediate execution")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("in_place").short('i').long("in-place")
                .help("Restart the task by reusing the already existing tasks. This will overwrite any previous logs of the restarted tasks")
                .long_help("Restart the task by reusing the already existing tasks. This will overwrite any previous logs of the restarted tasks.\n\nThis can also be enabled by default via the `restart_in_place` config option.")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("not_in_place").long("not-in-place")
                .help("Restart the task by creating a new identical tasks. Only necessary if you have the `restart_in_place` configuration set to true")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("edit").short('e').long("edit")
                .help("Edit the task before restarting")
                .action(ArgAction::SetTrue)
        );

    let pause = Command::new("pause")
        .about("Either pause running tasks or specific groups of tasks")
        .long_about("Either pause running tasks or specific groups of tasks.\n\nBy default, pauses the default group and all its tasks. A paused queue (group) won't start any new tasks.")
        .arg(task_ids_arg("Pause these specific tasks", false))
        .arg(group_arg("Pause a specific group", true))
        .arg(all_arg("Pause all groups!"))
        .arg(
            Arg::new("wait").short('w').long("wait")
                .help("Pause the specified groups, but let already running tasks finish by themselves")
                .action(ArgAction::SetTrue)
        );

    let kill = Command::new("kill")
        .about("Kill specific running tasks or whole task groups")
        .long_about("Kill specific running tasks or whole task groups.\n\nKills all tasks of the default group when no ids or a specific group are provided.")
        .arg(task_ids_arg("Kill these specific tasks", false))
        .arg(group_arg("Kill all running tasks in a group. This also pauses the group", true))
        .arg(all_arg("Kill all running tasks across ALL groups. This also pauses all groups"))
        .arg(
            Arg::new("signal").short('s').long("signal").value_name("SIGNAL")
                .help("Send a UNIX signal instead of simply killing the process")
                .long_help("Send a UNIX signal instead of simply killing the process.\n\nDISCLAIMER: This bypasses Pueue's process handling logic! You might enter weird invalid states, use at your own descretion.\n\nThis argument also excepts the integer representation as well as the signal short name. E.g. `sigint`, `int`, or `2` are the same.")
                .value_parser(clap::value_parser!(Signal)).num_args(1)
        );

    let send = Command::new("send")
        .about("Send something to a task. Useful for sending confirmations such as 'y\\n'")
        .arg(Arg::new("task_id").value_name("TASK_ID").help("The id of the task").required(true).value_parser(clap::value_parser!(usize)))
        .arg(Arg::new("input").value_name("INPUT").help("The input that should be sent to the process").required(true));

    let edit = Command::new("edit")
        .about("Adjust editable properties of a task")
        .long_about("Adjust editable properties of a task.\n\nOnly stashed or queued tasks can be edited. A temporary folder folder/file will be opened by your $EDITOR to edit the tasks.")
        .arg(task_ids_arg("The ids of all tasks that should be edited", false));

    let env_set = Command::new("set")
        .about("Set a variable for a specific task's environment")
        .arg(Arg::new("task_id").value_name("TASK_ID").help("The id of the task for which the variable should be set").required(true).value_parser(clap::value_parser!(usize)))
        .arg(Arg::new("key").value_name("KEY").help("The name of the environment variable to set").required(true))
        .arg(Arg::new("value").value_name("VALUE").help("The value of the environment variable to set").required(true));
    let env_unset = Command::new("unset")
        .about("Remove a specific variable from a task's environment")
        .arg(Arg::new("task_id").value_name("TASK_ID").help("The id of the task for which the variable should be set").required(true).value_parser(clap::value_parser!(usize)))
        .arg(Arg::new("key").value_name("KEY").help("The name of the environment variable to set").required(true));
    let env_cmd = Command::new("env")
        .about("Use this to add or remove environment variables from tasks")
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(env_set)
        .subcommand(env_unset);

    let group_add = Command::new("add")
        .about("Add a group by name")
        .arg(Arg::new("name").value_name("NAME").required(true))
        .arg(
            Arg::new("parallel").short('p').long("parallel").value_name("PARALLEL")
                .help("Set the amount of parallel tasks this group can have")
                .long_help("Set the amount of parallel tasks this group can have.\n\nSetting this to 0 means an unlimited amount of parallel tasks.")
                .value_parser(clap::value_parser!(usize)).num_args(1)
        );
    let group_remove = Command::new("remove")
        .about("Remove a group by name. This will move all tasks in this group to the default group!")
        .arg(Arg::new("name").value_name("NAME").required(true));
    let group = Command::new("group")
        .about("Use this to add or remove groups")
        .long_about("Use this to add or remove groups.\n\nBy default, this will simply display all known groups.")
        .arg(Arg::new("json").short('j').long("json").help("Print the list of groups as json").action(ArgAction::SetTrue))
        .subcommand(group_add)
        .subcommand(group_remove);

    let status = Command::new("status")
        .about("Display the current status of all tasks")
        .arg(
            Arg::new("query").value_name("QUERY")
                .help("Users can specify a custom query to filter for specific values, order by a column or limit the amount of tasks listed. Use `--help` for the full syntax definition")
                .long_help(STATUS_QUERY_LONG)
                .num_args(0..).action(ArgAction::Append)
        )
        .arg(Arg::new("json").short('j').long("json").help("Print the current state as json to stdout. This does not include the output of tasks. Use `log -j` if you want everything").action(ArgAction::SetTrue))
        .arg(group_arg("Only show tasks of a specific group", false));

    let log = Command::new("log")
        .about("Display the log output of finished tasks")
        .long_about("Display the log output of finished tasks.\n\nOnly the last few lines will be shown by default. If you want to follow the output of a task, please use the \"follow\" subcommand.")
        .arg(task_ids_arg("View the task output of these specific tasks", false))
        .arg(group_arg("View the outputs of this specific group's tasks", false))
        .arg(all_arg("Show the logs of all groups' tasks"))
        .arg(
            Arg::new("json").short('j').long("json")
                .help("Print the resulting tasks and output as json")
                .long_help("Print the resulting tasks and output as json.\n\nBy default only the last lines will be returned unless --full is provided. Take care, as the json cannot be streamed! If your logs are really huge, using --full can use all of your machine's RAM.")
                .action(ArgAction::SetTrue)
        )
        .arg(
            Arg::new("lines").short('l').long("lines").value_name("LINES")
                .help("Only print the last X lines of each task's output")
                .long_help("Only print the last X lines of each task's output.\n\nThis is done by default if you're looking at multiple tasks.")
                .value_parser(clap::value_parser!(usize)).num_args(1).conflicts_with("full")
        )
        .arg(Arg::new("full").short('f').long("full").help("Show the whole output").action(ArgAction::SetTrue));

    let follow = Command::new("follow")
        .alias("fo")
        .about("Follow the output of a currently running task. This command works like \"tail -f\"")
        .arg(
            Arg::new("task_id").value_name("TASK_ID")
                .help("The id of the task you want to watch")
                .long_help("The id of the task you want to watch.\n\nIf no or multiple tasks are running, you have to specify the id. If only a single task is running, you can omit the id.")
                .value_parser(clap::value_parser!(usize))
        )
        .arg(
            Arg::new("lines").short('l').long("lines").value_name("LINES")
                .help("Only print the last X lines of the output before following")
                .value_parser(clap::value_parser!(usize)).num_args(1)
        );

    let wait = Command::new("wait")
        .about("Wait until tasks are finished")
        .long_about("Wait until tasks are finished.\n\nBy default, this will wait for all tasks in the default group to finish.\n\nNote: This will also wait for all tasks that aren't somehow 'Done'. Includes: [Paused, Stashed, Locked, Queued, ...]")
        .arg(task_ids_arg("This allows you to wait for specific tasks to finish", false))
        .arg(group_arg("Wait for all tasks in a specific group", true))
        .arg(all_arg("Wait for all tasks across all groups and the default group"))
        .arg(Arg::new("quiet").short('q').long("quiet").help("Don't show any log output while waiting").action(ArgAction::SetTrue))
        .arg(
            Arg::new("status").short('s').long("status").value_name("STATUS")
                .help("Wait for tasks to reach a specific task status")
                .value_parser(clap::value_parser!(WaitStatus)).num_args(1)
        );

    let clean = Command::new("clean")
        .about("Remove all finished tasks from the list")
        .arg(Arg::new("successful_only").short('s').long("successful-only").help("Only clean tasks that finished successfully").action(ArgAction::SetTrue))
        .arg(Arg::new("group").short('g').long("group").value_name("GROUP").help("Only clean tasks of a specific group").num_args(1));

    let reset = Command::new("reset")
        .about("Kill all tasks, clean up afterwards and reset EVERYTHING!")
        .arg(
            Arg::new("groups").short('g').long("groups").value_name("GROUPS")
                .help("If groups are specified, only those specific groups will be reset")
                .num_args(1).action(ArgAction::Append)
        )
        .arg(Arg::new("force").short('f').long("force").help("Don't ask for any confirmation").action(ArgAction::SetTrue));

    let shutdown = Command::new("shutdown")
        .about("Remotely shut down the daemon. Should only be used if the daemon isn't started by a service manager");

    let parallel = Command::new("parallel")
        .about("Set the amount of allowed parallel tasks")
        .long_about("Set the amount of allowed parallel tasks\n\nBy default, adjusts the amount of the default group.\n\nNo tasks will be stopped, if this is lowered. This limit is only considered when tasks are scheduled.")
        .arg(
            Arg::new("parallel_tasks").value_name("PARALLEL_TASKS")
                .help("The amount of allowed parallel tasks")
                .long_help("The amount of allowed parallel tasks.\n\nSetting this to 0 means an unlimited amount of parallel tasks.")
                .value_parser(clap::value_parser!(usize))
        )
        .arg(
            Arg::new("group").short('g').long("group").value_name("group")
                .help("Set the amount for a specific group").num_args(1)
        );

    let completions = Command::new("completions")
        .about("Generates shell completion files")
        .long_about("Generates shell completion files.\n\nThis can be ignored during normal operations.")
        .arg(
            Arg::new("shell").value_name("SHELL").help("The target shell").required(true)
                .value_parser(["bash", "elvish", "fish", "power-shell", "zsh", "nushell"])
        )
        .arg(
            Arg::new("output_directory").value_name("OUTPUT_DIRECTORY")
                .help("The output directory to which the file should be written")
                .value_parser(clap::value_parser!(PathBuf))
        );

    Command::new("pueue")
        .version("4.0.4")
        .about("Interact with the Pueue daemon\n\nUse the `--help` long form to get detailed help output on each subcommand!")
        .disable_colored_help(true)
        .arg(
            Arg::new("verbose")
                .short('v').long("verbose")
                .help("Verbose mode (-v, -vv, -vvv)")
                .action(ArgAction::Count),
        )
        .arg(
            Arg::new("color")
                .long("color").value_name("COLOR")
                .help("Colorize the output; auto enables color output when connected to a tty")
                .value_parser(["auto", "never", "always"])
                .default_value("auto")
                .num_args(1),
        )
        .arg(
            Arg::new("config")
                .short('c').long("config").value_name("CONFIG")
                .help("If provided, Pueue only uses this config file")
                .long_help("If provided, Pueue only uses this config file.\n\nThis path can also be set via the \"PUEUE_CONFIG_PATH\" environment variable. The commandline option overwrites the environment variable!")
                .value_parser(clap::value_parser!(PathBuf)).num_args(1),
        )
        .arg(
            Arg::new("profile")
                .short('p').long("profile").value_name("PROFILE")
                .help("The name of the profile that should be loaded from your config file")
                .num_args(1),
        )
        .subcommand(add)
        .subcommand(remove)
        .subcommand(switch)
        .subcommand(stash)
        .subcommand(enqueue)
        .subcommand(start)
        .subcommand(restart)
        .subcommand(pause)
        .subcommand(kill)
        .subcommand(send)
        .subcommand(edit)
        .subcommand(env_cmd)
        .subcommand(group)
        .subcommand(status)
        .subcommand(log)
        .subcommand(follow)
        .subcommand(wait)
        .subcommand(clean)
        .subcommand(reset)
        .subcommand(shutdown)
        .subcommand(parallel)
        .subcommand(completions)
}

const STATUS_QUERY_LONG: &str = "\
Users can specify a custom query to filter for specific values, order by a column
or limit the amount of tasks listed.

Syntax:
   [column_selection]? [filter]* [order_by]? [limit]?

where:
  - column_selection := `columns=[column]([column],)*`
  - column := `id | status | command | label | path | enqueue_at | dependencies | start |
  end`
  - filter := `[filter_column] [filter_op] [filter_value]`
    (note: not all columns support all operators, see \"Filter columns\" below.)
  - filter_column := `status | command | label | start | end | enqueue_at`
  - filter_op := `= | != | < | > | %=`
    (`%=` means 'contains', as in the test value is a substring of the column value)
  - order_by := `order_by [column] [order_direction]`
  - order_direction := `asc | desc`
  - limit := `[limit_type]? [limit_count]`
  - limit_type := `first | last`
  - limit_count := a positive integer

Filter columns:
  - `status` supports the operators `=`, `!=`
    against test values that are:
      - strings like `queued`, `stashed`, `paused`, `running`, `success`, `failed`
  - `command`, `label` support the operators `=`, `!=`, `%=`
    against test values that are:
      - strings like `some text`
  - `start`, `end`, `enqueue_at` contain a datetime
    which support the operators `=`, `!=`, `<`, `>`
    against test values that are:
      - date like `YYYY-MM-DD`
      - time like `HH:mm:ss` or `HH:mm`
      - datetime like `YYYY-MM-DDHH:mm:ss`
        (note there is currently no separator between the date and the time)

Examples:
  - `status=running`
  - `command%=echo`
  - `label=mytask`
  - `columns=id,status,command status=running start > 2023-05-2112:03:17 order_by command
  first 5`

The formal syntax is defined here:
https://github.com/Nukesor/pueue/blob/main/pueue/src/client/commands/state/query/syntax.pest

More documentation is on the query syntax PR:
https://github.com/Nukesor/pueue/issues/350#issue-1359083118";

fn get_many<T: Clone + Send + Sync + 'static>(
    matches: &clap::ArgMatches,
    id: &str,
) -> Vec<T> {
    matches
        .get_many::<T>(id)
        .map(|values| values.cloned().collect())
        .unwrap_or_default()
}

pub fn parse_opt(matches: &clap::ArgMatches) -> Opt {
    let verbose = *matches.get_one::<u8>("verbose").unwrap_or(&0);
    let color = match matches.get_one::<String>("color").map(|s| s.as_str()) {
        Some("never") => ColorChoice::Never,
        Some("always") => ColorChoice::Always,
        _ => ColorChoice::Auto,
    };
    let config = matches.get_one::<PathBuf>("config").cloned();
    let profile = matches.get_one::<String>("profile").cloned();

    let command = match matches.subcommand() {
        Some(("add", sub)) => Some(SubCommand::Add {
            command: get_many::<String>(sub, "command"),
            working_directory: sub.get_one::<PathBuf>("working_directory").cloned(),
            escape: sub.get_flag("escape"),
            start_immediately: sub.get_flag("start_immediately"),
            follow: sub.get_flag("follow"),
            stashed: sub.get_flag("stashed"),
            delay_until: sub.get_one::<DateTime<Utc>>("delay_until").cloned(),
            group: sub.get_one::<String>("group").cloned(),
            dependencies: get_many::<usize>(sub, "dependencies"),
            priority: sub.get_one::<i32>("priority").cloned(),
            label: sub.get_one::<String>("label").cloned(),
            print_task_id: sub.get_flag("print_task_id"),
        }),
        Some(("remove", sub)) => Some(SubCommand::Remove {
            task_ids: get_many::<usize>(sub, "task_ids"),
        }),
        Some(("switch", sub)) => Some(SubCommand::Switch {
            task_id_1: *sub.get_one::<usize>("task_id_1").unwrap(),
            task_id_2: *sub.get_one::<usize>("task_id_2").unwrap(),
        }),
        Some(("stash", sub)) => Some(SubCommand::Stash {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            delay_until: sub.get_one::<DateTime<Utc>>("delay_until").cloned(),
        }),
        Some(("enqueue", sub)) => Some(SubCommand::Enqueue {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            delay_until: sub.get_one::<DateTime<Utc>>("delay_until").cloned(),
        }),
        Some(("start", sub)) => Some(SubCommand::Start {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
        }),
        Some(("restart", sub)) => Some(SubCommand::Restart {
            task_ids: get_many::<usize>(sub, "task_ids"),
            all_failed: sub.get_flag("all_failed"),
            failed_in_group: sub.get_one::<String>("failed_in_group").cloned(),
            start_immediately: sub.get_flag("start_immediately"),
            stashed: sub.get_flag("stashed"),
            in_place: sub.get_flag("in_place"),
            not_in_place: sub.get_flag("not_in_place"),
            edit: sub.get_flag("edit"),
        }),
        Some(("pause", sub)) => Some(SubCommand::Pause {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            wait: sub.get_flag("wait"),
        }),
        Some(("kill", sub)) => Some(SubCommand::Kill {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            signal: sub.get_one::<Signal>("signal").cloned(),
        }),
        Some(("send", sub)) => Some(SubCommand::Send {
            task_id: *sub.get_one::<usize>("task_id").unwrap(),
            input: sub.get_one::<String>("input").unwrap().clone(),
        }),
        Some(("edit", sub)) => Some(SubCommand::Edit {
            task_ids: get_many::<usize>(sub, "task_ids"),
        }),
        Some(("env", sub)) => match sub.subcommand() {
            Some(("set", subsub)) => Some(SubCommand::Env {
                cmd: EnvCmd::Set {
                    task_id: *subsub.get_one::<usize>("task_id").unwrap(),
                    key: subsub.get_one::<String>("key").unwrap().clone(),
                    value: subsub.get_one::<String>("value").unwrap().clone(),
                },
            }),
            Some(("unset", subsub)) => Some(SubCommand::Env {
                cmd: EnvCmd::Unset {
                    task_id: *subsub.get_one::<usize>("task_id").unwrap(),
                    key: subsub.get_one::<String>("key").unwrap().clone(),
                },
            }),
            _ => None,
        },
        Some(("group", sub)) => {
            let cmd = match sub.subcommand() {
                Some(("add", subsub)) => Some(GroupCmd::Add {
                    name: subsub.get_one::<String>("name").unwrap().clone(),
                    parallel: subsub.get_one::<usize>("parallel").cloned(),
                }),
                Some(("remove", subsub)) => Some(GroupCmd::Remove {
                    name: subsub.get_one::<String>("name").unwrap().clone(),
                }),
                _ => None,
            };
            Some(SubCommand::Group {
                json: sub.get_flag("json"),
                cmd,
            })
        }
        Some(("status", sub)) => Some(SubCommand::Status {
            query: get_many::<String>(sub, "query"),
            json: sub.get_flag("json"),
            group: sub.get_one::<String>("group").cloned(),
        }),
        Some(("log", sub)) => Some(SubCommand::Log {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            json: sub.get_flag("json"),
            lines: sub.get_one::<usize>("lines").cloned(),
            full: sub.get_flag("full"),
        }),
        Some(("follow", sub)) => Some(SubCommand::Follow {
            task_id: sub.get_one::<usize>("task_id").cloned(),
            lines: sub.get_one::<usize>("lines").cloned(),
        }),
        Some(("wait", sub)) => Some(SubCommand::Wait {
            task_ids: get_many::<usize>(sub, "task_ids"),
            group: sub.get_one::<String>("group").cloned(),
            all: sub.get_flag("all"),
            quiet: sub.get_flag("quiet"),
            status: sub.get_one::<WaitStatus>("status").cloned(),
        }),
        Some(("clean", sub)) => Some(SubCommand::Clean {
            successful_only: sub.get_flag("successful_only"),
            group: sub.get_one::<String>("group").cloned(),
        }),
        Some(("reset", sub)) => Some(SubCommand::Reset {
            groups: get_many::<String>(sub, "groups"),
            force: sub.get_flag("force"),
        }),
        Some(("shutdown", _)) => Some(SubCommand::Shutdown),
        Some(("parallel", sub)) => Some(SubCommand::Parallel {
            parallel_tasks: sub.get_one::<usize>("parallel_tasks").cloned(),
            group: sub.get_one::<String>("group").cloned(),
        }),
        Some(("completions", sub)) => Some(SubCommand::Completions {
            shell: sub.get_one::<String>("shell").unwrap().clone(),
            output_directory: sub.get_one::<PathBuf>("output_directory").cloned(),
        }),
        _ => None,
    };

    Opt {
        verbose,
        color,
        config,
        profile,
        command,
    }
}
EOF
"}

