use crate::cli::ColorChoice;
use std::io::IsTerminal;

#[derive(Clone, Copy)]
pub struct Style {
    pub enabled: bool,
    pub dark_mode: bool,
}

impl Style {
    pub fn new(color: ColorChoice, dark_mode: bool) -> Self {
        let enabled = match color {
            ColorChoice::Always => true,
            ColorChoice::Never => false,
            ColorChoice::Auto => std::io::stdout().is_terminal(),
        };
        Style { enabled, dark_mode }
    }
    pub fn green_code(&self) -> u32 {
        if self.dark_mode { 2 } else { 10 }
