        if self.dark_mode { 1 } else { 9 }
    }
    pub fn white_code(&self) -> u32 {
        15
    }
    pub fn group_header(&self, name: &str, parallel: usize, status_lower: &str, running: bool) -> String {
        if self.enabled {
            let code = if running { self.green_code() } else { self.yellow_code() };
            format!(
                "\x1b[1mGroup \"{}\"\x1b[0m ({} parallel): \x1b[38;5;{}m{}\x1b[39m",
