use crate::style::Style;

#[derive(Clone)]
pub struct CellData {
    pub text: String,
    /// ANSI 256 colour code to apply to the whole cell when styling.
    pub color: Option<u32>,
}

impl CellData {
    pub fn plain(text: impl Into<String>) -> Self {
        Self { text: text.into(), color: None }
    }
    pub fn colored(text: impl Into<String>, code: u32) -> Self {
        Self { text: text.into(), color: Some(code) }
    }
}

fn display_width(s: &str) -> usize {
    // Deliberately simple width calculation: count Unicode scalar values,
    // treating tabs as a single column for width arithmetic.  This matches
    // the reference output for typical ASCII content; wide / zero width
    // graphemes are an accepted approximation.
    s.chars().count()
}

/// Render a table in the shape produced by the reference's comfy-table
/// configuration: horizontal rules only, one space of cell padding on each
/// side and a single separator space between cells.
pub fn render_table(headers: &[String], rows: &[Vec<CellData>], style: &Style, max_lines: Option<usize>) -> String {
    if let Some(0) = max_lines {
        if !rows.is_empty() {
            crate::errors::panic_like(
                "We know it's this long.",
                (
                    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/comfy-table-7.2.1/src/utils/formatting/content_format.rs",
                    116,
                ),
            );
        }
    }

    // Apply max-lines truncation to each cell's text.
    let truncate = |text: &str| -> String {
        if let Some(limit) = max_lines {
            if limit > 0 {
                let lines: Vec<&str> = text.lines().collect();
                if lines.len() > limit {
                    let mut kept: Vec<String> = lines[..limit].iter().map(|s| s.to_string()).collect();
                    if let Some(last) = kept.last_mut() {
                        last.push_str("...");
                    }
                    return kept.join("\n");
                }
            }
        }
        text.to_string()
    };

    let prepared_headers: Vec<String> = headers.iter().map(|h| truncate(h)).collect();
    let prepared_rows: Vec<Vec<CellData>> = rows
        .iter()
        .map(|row| {
            row.iter()
                .map(|c| CellData { text: truncate(&c.text), color: c.color })
                .collect()
        })
        .collect();

    let ncols = headers.len();
    let mut widths: Vec<usize> = vec![0; ncols];
    for (i, h) in prepared_headers.iter().enumerate() {
        for line in h.lines() {
            widths[i] = widths[i].max(display_width(line));
        }
        if h.is_empty() {
            // width stays 0
        }
    }
    for row in &prepared_rows {
        for (i, cell) in row.iter().enumerate() {
            if i >= ncols {
                break;
            }
            for line in cell.text.lines() {
                widths[i] = widths[i].max(display_width(line));
            }
        }
    }

    let total: usize = 1 + widths.iter().sum::<usize>() + 3 * (ncols.saturating_sub(1)) + 1;
    let mut out = String::new();
    let thin = "─".repeat(total);
    let thick = "═".repeat(total);

    let render_row = |cells: &[CellData], out: &mut String| {
        // Determine physical lines for every cell.
        let mut cell_lines: Vec<Vec<String>> = Vec::new();
        let mut max_height = 1usize;
        for cell in cells {
            let lines: Vec<String> = if cell.text.is_empty() {
                vec![String::new()]
            } else {
                cell.text.lines().map(|s| s.to_string()).collect()
            };
            max_height = max_height.max(lines.len());
            cell_lines.push(lines);
        }
        for phys in 0..max_height {
            let mut line = String::new();
            for col in 0..ncols {
                if col > 0 {
                    line.push(' ');
                }
                let content = cell_lines
                    .get(col)
                    .and_then(|lines| lines.get(phys))
                    .cloned()
                    .unwrap_or_default();
                let width = widths[col];
                let pad_right = width.saturating_sub(display_width(&content));
                let cell_text = format!(" {}{} ", content, " ".repeat(pad_right));
                if style.enabled {
                    if let Some(code) = cells[col].color {
                        line.push_str(&format!("\x1b[38;5;{}m{}\x1b[39m", code, cell_text));
                    } else {
                        line.push_str(&cell_text);
                    }
                } else {
                    line.push_str(&cell_text);
                }
            }
            out.push_str(&line);
            out.push('\n');
        }
    };

    out.push_str(&thin);
    out.push('\n');
    let header_cells: Vec<CellData> = prepared_headers.iter().map(|h| CellData::plain(h.clone())).collect();
    render_row(&header_cells, &mut out);
    out.push_str(&thick);
    out.push('\n');
    for row in &prepared_rows {
        render_row(row, &mut out);
        out.push_str(&thin);
        out.push('\n');
    }
    if prepared_rows.is_empty() {
        out.push_str(&thin);
        out.push('\n');
    }
    out
}
