use crate::errors::{panic_like, Report, Result};
use crate::protocol::{Group, GroupStatus, State, Task, TaskResult, TaskStatus};
use crate::settings::Settings;
use crate::style::Style;
use crate::table::{render_table, CellData};
use chrono::{DateTime, Datelike, Local, NaiveDate, NaiveDateTime, NaiveTime, TimeZone, Utc};
use std::collections::BTreeMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Column {
    Id,
    Status,
    Command,
    Label,
    Path,
    EnqueueAt,
    Dependencies,
    Start,
    End,
}

impl Column {
    pub fn header(self) -> &'static str {
        match self {
            Column::Id => "Id",
            Column::Status => "Status",
            Column::Command => "Command",
            Column::Label => "Label",
            Column::Path => "Path",
            Column::EnqueueAt => "Enqueue At",
            Column::Dependencies => "Deps",
            Column::Start => "Start",
            Column::End => "End",
        }
    }
    fn parse(s: &str) -> Option<Self> {
        match s {
            "id" => Some(Column::Id),
            "status" => Some(Column::Status),
            "command" => Some(Column::Command),
            "label" => Some(Column::Label),
            "path" => Some(Column::Path),
            "enqueue_at" => Some(Column::EnqueueAt),
            "dependencies" => Some(Column::Dependencies),
            "start" => Some(Column::Start),
            "end" => Some(Column::End),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
enum FilterValue {
    Text(String),
    Date(NaiveDate),
    Time(NaiveTime),
    DateTime(NaiveDateTime),
}

#[derive(Debug, Clone)]
struct Filter {
    column: String,
    op: String,
    value: FilterValue,
    raw: String,
}

#[derive(Debug, Clone, Default)]
pub struct Query {
    pub columns: Option<Vec<Column>>,
    filters: Vec<Filter>,
    order_by: Option<(Column, bool)>, // desc
    limit: Option<(bool, usize)>,     // last?
}

fn pest_error(query: &str, pos: usize, expected: &str) -> Report {
    // pos is 0-based byte offset where parsing failed.
    let col = query[..pos.min(query.len())].chars().count() + 1;
    let message = format!(
        " --> 1:{}\n  |\n1 | {}\n  | {}^---\n  |\n  = expected {}",
        col,
        query,
        " ".repeat(col - 1),
        expected
    );
    Report::chain(
        vec!["Failed to parse query".to_string(), message],
        ("pueue/src/client/commands/state/query/mod.rs", 163),
    )
}

fn parse_datetime_value(s: &str) -> Option<FilterValue> {
    // YYYY-MM-DDHH:mm:ss or YYYY-MM-DDHH:mm
    // Date components are 10 chars.
    if s.len() > 10 {
        let (date_part, time_part) = s.split_at(10);
        if let Ok(date) = NaiveDate::parse_from_str(date_part, "%Y-%m-%d") {
            if let Ok(time) = NaiveTime::parse_from_str(time_part, "%H:%M:%S") {
                return Some(FilterValue::DateTime(date.and_time(time)));
            }
            if let Ok(time) = NaiveTime::parse_from_str(time_part, "%H:%M") {
                return Some(FilterValue::DateTime(date.and_time(time)));
            }
        }
    }
    if let Ok(date) = NaiveDate::parse_from_str(s, "%Y-%m-%d") {
        return Some(FilterValue::Date(date));
    }
    if let Ok(time) = NaiveTime::parse_from_str(s, "%H:%M:%S") {
        return Some(FilterValue::Time(time));
    }
    if let Ok(time) = NaiveTime::parse_from_str(s, "%H:%M") {
        return Some(FilterValue::Time(time));
    }
    None
}

impl Query {
    pub fn parse(tokens: &[String]) -> Result<Query> {
        if tokens.is_empty() {
            return Ok(Query::default());
        }
        let query_str = tokens.join(" ");
        let q = query_str.as_str();
        let mut pos = 0usize;
        let mut result = Query::default();

        let skip_ws = |mut p: usize| -> usize {
            while p < q.len() && q.as_bytes()[p].is_ascii_whitespace() {
                p += 1;
            }
            p
        };

        pos = skip_ws(pos);
        if pos >= q.len() {
            return Ok(result);
        }

        // columns=
        if q[pos..].starts_with("columns=") {
            pos += "columns=".len();
            let mut cols: Vec<Column> = Vec::new();
            loop {
                pos = skip_ws(pos);
                let start = pos;
                while pos < q.len() {
                    let c = q.as_bytes()[pos] as char;
                    if c.is_ascii_alphanumeric() || c == '_' {
                        pos += 1;
                    } else {
                        break;
                    }
                }
                if start == pos {
                    return Err(pest_error(q, pos, "column"));
                }
                let name = &q[start..pos];
                let column = Column::parse(name)
                    .ok_or_else(|| pest_error(q, start, "column"))?;
                cols.push(column);
                pos = skip_ws(pos);
                if pos < q.len() && q.as_bytes()[pos] == b',' {
                    pos += 1;
                    continue;
                }
                break;
            }
            result.columns = Some(cols);
        }

        loop {
            pos = skip_ws(pos);
            if pos >= q.len() {
                break;
            }
            // order_by
            if q[pos..].starts_with("order_by") {
                let after = pos + "order_by".len();
                // must be separated or end
                let mut p = skip_ws(after);
                let start = p;
                while p < q.len() {
                    let c = q.as_bytes()[p] as char;
                    if c.is_ascii_alphanumeric() || c == '_' {
                        p += 1;
                    } else {
                        break;
                    }
                }
                if start == p {
                    return Err(pest_error(q, p, "column"));
                }
                let column = Column::parse(&q[start..p])
                    .ok_or_else(|| pest_error(q, start, "column"))?;
                p = skip_ws(p);
                let mut desc = false;
                let dstart = p;
                while p < q.len() && (q.as_bytes()[p] as char).is_ascii_alphabetic() {
                    p += 1;
                }
                if p > dstart {
                    match &q[dstart..p] {
                        "asc" => desc = false,
                        "desc" => desc = true,
                        other => {
                            // Could be a limit keyword following.
                            if other == "first" || other == "last" {
                                // rewind and let limit parsing handle
                                p = dstart;
                            } else if other.chars().all(|c| c.is_ascii_digit()) {
                                p = dstart;
                            } else {
                                return Err(pest_error(q, dstart, "order_direction"));
                            }
                        }
                    }
                }
                result.order_by = Some((column, desc));
                pos = p;
                continue;
            }
            // limit forms
            if starts_limit(&q[pos..]) {
                let mut p = pos;
                let mut is_last = false;
                let mut had_type = false;
                if q[p..].starts_with("first") {
                    p += 5;
                    had_type = true;
                } else if q[p..].starts_with("last") {
                    p += 4;
                    is_last = true;
                    had_type = true;
                }
                p = skip_ws(p);
                let start = p;
                while p < q.len() && (q.as_bytes()[p] as char).is_ascii_digit() {
                    p += 1;
                }
                if start == p {
                    return Err(pest_error(q, p, "positive integer"));
                }
                let count: usize = q[start..p]
                    .parse()
                    .map_err(|_| pest_error(q, start, "positive integer"))?;
                if count == 0 {
                    return Err(pest_error(q, start, "positive integer"));
                }
                let _ = had_type;
                result.limit = Some((is_last, count));
                pos = p;
                continue;
            }
            // filter
            // filter column name
            let col_start = pos;
            while pos < q.len() {
                let c = q.as_bytes()[pos] as char;
                if c.is_ascii_alphanumeric() || c == '_' {
                    pos += 1;
                } else {
                    break;
                }
            }
            if col_start == pos {
                if result.columns.is_none() && result.filters.is_empty() && result.order_by.is_none() && result.limit.is_none() {
                    return Err(pest_error(q, 0, "query"));
                }
                return Err(pest_error(q, pos, "filter_column"));
            }
            let col_name = q[col_start..pos].to_string();
            if !matches!(col_name.as_str(), "status" | "command" | "label" | "start" | "end" | "enqueue_at") {
                if result.columns.is_none() && result.filters.is_empty() && result.order_by.is_none() && result.limit.is_none() {
                    return Err(pest_error(q, 0, "query"));
                }
                return Err(pest_error(q, col_start, "filter_column"));
            }
            pos = skip_ws(pos);
            // operator
            let op_start = pos;
            let op = if q[pos..].starts_with("%=") || q[pos..].starts_with("!=") {
                let op = q[pos..pos + 2].to_string();
                pos += 2;
                op
            } else if pos < q.len() && matches!(q.as_bytes()[pos], b'=' | b'<' | b'>') {
                let op = (q.as_bytes()[pos] as char).to_string();
                pos += 1;
                op
            } else {
                return Err(pest_error(q, op_start, "filter_op"));
            };
            pos = skip_ws(pos);
            if pos >= q.len() {
                return Err(pest_error(q, pos, "filter_value"));
            }
            // Value parsing depends on column.
            let (value, raw, new_pos, greedy) = if col_name == "command" || col_name == "label" {
                // In the reference grammar, a free text value consumes
                // the remainder of the query.
                let raw = q[pos..].trim().to_string();
                if raw.is_empty() {
                    return Err(pest_error(q, pos, "filter_value"));
                }
                (FilterValue::Text(raw.clone()), raw, q.len(), true)
            } else if col_name == "status" {
                let start = pos;
                while pos < q.len() && !(q.as_bytes()[pos] as char).is_ascii_whitespace() {
                    pos += 1;
                }
                let raw = q[start..pos].to_string();
                if raw.is_empty() {
                    return Err(pest_error(q, pos, "filter_value"));
                }
                (FilterValue::Text(raw.clone()), raw, pos, false)
            } else {
                // date/time columns: consume one non-space token.
                let start = pos;
                while pos < q.len() && !(q.as_bytes()[pos] as char).is_ascii_whitespace() {
                    pos += 1;
                }
                let raw = q[start..pos].to_string();
                let parsed = parse_datetime_value(&raw)
                    .ok_or_else(|| pest_error(q, start, "date, time, or datetime"))?;
                (parsed, raw, pos, false)
            };
            result.filters.push(Filter {
                column: col_name,
                op,
                value,
                raw,
            });
            pos = new_pos;
            if greedy {
                break;
            }
        }

        Ok(result)
    }

    pub fn apply(&self, mut tasks: Vec<Task>, settings: &Settings) -> Vec<Task> {
        for filter in &self.filters {
            tasks.retain(|task| filter.matches(task, settings));
        }
        if let Some((column, desc)) = self.order_by {
            sort_tasks(&mut tasks, column, desc, settings);
        }
        if let Some((is_last, count)) = self.limit {
            if tasks.len() > count {
                if is_last {
                    let start = tasks.len() - count;
                    tasks = tasks[start..].to_vec();
                } else {
                    tasks.truncate(count);
                }
            }
        }
        tasks
    }
}

fn starts_limit(s: &str) -> bool {
    if s.starts_with("first") || s.starts_with("last") {
        return true;
    }
    // A bare positive integer.
    let mut chars = s.chars();
    if let Some(first) = chars.next() {
        if first.is_ascii_digit() {
            return true;
        }
    }
    false
}

fn status_filter_value(task: &Task) -> &'static str {
    match &task.status {
        TaskStatus::Queued { .. } => "queued",
        TaskStatus::Stashed { .. } => "stashed",
        TaskStatus::Paused { .. } => "paused",
        TaskStatus::Running { .. } => "running",
        TaskStatus::Locked { .. } => "locked",
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => "success",
            TaskResult::Failed(_) => "failed",
            TaskResult::Errored => "failed",
            TaskResult::Killed => "failed",
            TaskResult::DependencyFailed => "failed",
        },
    }
}

fn command_display(task: &Task, settings: &Settings) -> String {
    if settings.client.show_expanded_aliases {
        task.command.clone()
    } else {
        task.original_command.clone()
    }
}

impl Filter {
    fn matches(&self, task: &Task, settings: &Settings) -> bool {
        match self.column.as_str() {
            "status" => {
                let value = status_filter_value(task);
                let target = self.raw.to_ascii_lowercase();
                match self.op.as_str() {
                    "=" => value == target,
                    "!=" => value != target,
                    _ => false,
                }
            }
            "command" => {
                let value = command_display(task, settings);
                match self.op.as_str() {
                    "=" => value == self.raw,
                    "!=" => value != self.raw,
                    "%=" => value.contains(&self.raw),
                    _ => false,
                }
            }
            "label" => {
                let value = task.label.clone().unwrap_or_default();
                match self.op.as_str() {
                    "=" => value == self.raw,
                    "!=" => value != self.raw,
                    "%=" => value.contains(&self.raw),
                    _ => false,
                }
            }
            "start" | "end" | "enqueue_at" => {
                let dt = match self.column.as_str() {
                    "start" => task.start(),
                    "end" => task.end(),
                    _ => task.enqueue_at(),
                };
                let Some(dt) = dt else { return false };
                compare_datetime(dt, &self.value, &self.op)
            }
            _ => false,
        }
    }
}

fn compare_datetime(dt: DateTime<Utc>, value: &FilterValue, op: &str) -> bool {
    let local = dt.with_timezone(&Local);
    let (is_eq, is_less, is_greater) = match value {
        FilterValue::Date(date) => {
            let d = local.date_naive();
            (d == *date, d < *date, d > *date)
        }
        FilterValue::Time(time) => {
            let t = local.time();
            (t == *time, t < *time, t > *time)
        }
        FilterValue::DateTime(ndt) => {
            let n = local.naive_local();
            (n == *ndt, n < *ndt, n > *ndt)
        }
        FilterValue::Text(_) => return false,
    };
    match op {
        "=" => is_eq,
        "!=" => !is_eq,
        "<" => is_less,
        ">" => is_greater,
        _ => false,
    }
}

fn sort_tasks(tasks: &mut Vec<Task>, column: Column, desc: bool, settings: &Settings) {
    let key_for = |task: &Task| -> SortKey {
        match column {
            Column::Id => SortKey::Int(task.id as i128),
            Column::Status => SortKey::Text(task.display_status().to_ascii_lowercase()),
            Column::Command => SortKey::Text(command_display(task, settings)),
            Column::Label => SortKey::Text(task.label.clone().unwrap_or_default()),
            Column::Path => SortKey::Text(task.path.display().to_string()),
            Column::EnqueueAt => SortKey::Date(task.enqueue_at()),
            Column::Dependencies => SortKey::Text(
                task.dependencies
                    .iter()
                    .map(|d| d.to_string())
                    .collect::<Vec<_>>()
                    .join(", "),
            ),
            Column::Start => SortKey::Date(task.start()),
            Column::End => SortKey::Date(task.end()),
        }
    };
    tasks.sort_by(|a, b| {
        let ord = key_for(a).cmp_key(&key_for(b));
        if desc { ord.reverse() } else { ord }
    });
}

#[derive(Clone)]
enum SortKey {
    Int(i128),
    Text(String),
    Date(Option<DateTime<Utc>>),
}
impl SortKey {
    fn cmp_key(&self, other: &Self) -> std::cmp::Ordering {
        use std::cmp::Ordering;
        match (self, other) {
            (SortKey::Int(a), SortKey::Int(b)) => a.cmp(b),
            (SortKey::Text(a), SortKey::Text(b)) => a.cmp(b),
            (SortKey::Date(a), SortKey::Date(b)) => match (a, b) {
                (None, None) => Ordering::Equal,
                (None, Some(_)) => Ordering::Less,
                (Some(_), None) => Ordering::Greater,
                (Some(x), Some(y)) => x.cmp(y),
            },
            _ => Ordering::Equal,
        }
    }
}

fn datetime_format(settings: &Settings) -> String {
    settings
        .client
        .status_datetime_format
        .clone()
        .unwrap_or_else(|| "%Y-%m-%d\n%H:%M:%S".to_string())
}
fn time_format(settings: &Settings) -> String {
    settings
        .client
        .status_time_format
        .clone()
        .unwrap_or_else(|| "%H:%M:%S".to_string())
}

fn format_start_end(dt: Option<DateTime<Utc>>, settings: &Settings) -> String {
    let Some(dt) = dt else { return String::new() };
    let local = dt.with_timezone(&Local);
    let today = Local::now().date_naive();
    if local.date_naive() < today {
        local.format(&datetime_format(settings)).to_string()
    } else {
        local.format(&time_format(settings)).to_string()
    }
}

fn format_enqueue_at(dt: Option<DateTime<Utc>>, settings: &Settings) -> String {
    let Some(dt) = dt else { return String::new() };
    let local = dt.with_timezone(&Local);
    let today = Local::now().date_naive();
    if local.date_naive() > today {
        local.format(&datetime_format(settings)).to_string()
    } else {
        local.format(&time_format(settings)).to_string()
    }
}

fn group_header(style: &Style, name: &str, group: &Group) -> String {
    let (status_lower, running) = match group.status {
        GroupStatus::Running => ("running", true),
        GroupStatus::Paused => ("paused", false),
    };
    style.group_header(name, group.parallel_tasks, status_lower, running)
}

fn default_columns(tasks: &[&Task]) -> Vec<Column> {
    let mut columns = vec![Column::Id, Column::Status];
    if tasks.iter().any(|t| t.enqueue_at().is_some()) {
        columns.push(Column::EnqueueAt);
    }
    if tasks.iter().any(|t| !t.dependencies.is_empty()) {
        columns.push(Column::Dependencies);
    }
    if tasks.iter().any(|t| t.label.is_some()) {
        columns.push(Column::Label);
    }
    columns.push(Column::Command);
    columns.push(Column::Path);
    columns.push(Column::Start);
    columns.push(Column::End);
    columns
}

fn cell_value(task: &Task, column: Column, settings: &Settings, style: &Style) -> CellData {
    match column {
        Column::Id => CellData::plain(task.id.to_string()),
        Column::Status => {
            let text = task.display_status();
            if style.enabled {
                CellData::colored(text.clone(), style.status_code(&text))
            } else {
                CellData::plain(text)
            }
        }
        Column::Command => CellData::plain(command_display(task, settings)),
        Column::Label => CellData::plain(task.label.clone().unwrap_or_default()),
        Column::Path => CellData::plain(task.path.display().to_string()),
        Column::EnqueueAt => CellData::plain(format_enqueue_at(task.enqueue_at(), settings)),
        Column::Dependencies => CellData::plain(
            task.dependencies
                .iter()
                .map(|d| d.to_string())
                .collect::<Vec<_>>()
                .join(", "),
        ),
        Column::Start => CellData::plain(format_start_end(task.start(), settings)),
        Column::End => CellData::plain(format_start_end(task.end(), settings)),
    }
}

fn build_table(tasks: &[&Task], columns: &[Column], settings: &Settings, style: &Style) -> String {
    let headers: Vec<String> = columns.iter().map(|c| c.header().to_string()).collect();
    let mut rows: Vec<Vec<CellData>> = Vec::new();
    for task in tasks {
        rows.push(columns.iter().map(|c| cell_value(task, *c, settings, style)).collect());
    }
    render_table(&headers, &rows, style, settings.client.max_status_lines)
}

pub fn print_state(
    state: &State,
    settings: &Settings,
    style: &Style,
    group_filter: Option<&str>,
    query_tokens: &[String],
    json: bool,
) -> Result<()> {
