fn pest_error(query: &str, pos: usize, expected: &str) -> Report {
    // pos is 0-based byte offset where parsing failed.
    let col = query[..pos.min(query.len())].chars().count() + 1;
    let message = format!(
        " --> 1:{}\n  |\n1 | {}\n  | {}^---\n  |\n  = expected {}",
