use crate::errors::panic_like;
use crate::logging;
use crate::settings::Settings;
use std::collections::BTreeMap;
use std::process::{Command, ExitStatus};

pub fn compile_shell_command(settings: &Settings, command_string: &str) -> Vec<String> {
    let mut shell_command = settings
        .daemon
        .shell_command
        .clone()
        .unwrap_or_else(|| {
            vec![
                "sh".to_string(),
                "-c".to_string(),
                "{{ pueue_command_string }}".to_string(),
            ]
        });
    if shell_command.is_empty() {
        panic_like(
            "removal index (is 0) should be < len (is 0)",
            ("pueue/src/process_helper/mod.rs", 64),
        );
    }
    for part in shell_command.iter_mut() {
        if part.contains("pueue_command_string") {
            if logging::enabled(logging::Level::Debug) {
                logging::log_event(
                    logging::Level::Debug,
                    "handlebars::render",
                    "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/handlebars-6.4.0/src/render.rs:895",
                    "Rendering value: Path(Relative(([Named(\"pueue_command_string\")], \"pueue_command_string\")))",
                );
            }
            *part = render_template(part, command_string);
        }
    }
    shell_command
}

fn render_template(template: &str, command_string: &str) -> String {
    let mut result = String::new();
    let mut rest = template;
    loop {
        // Support both {{var}} and {{{var}}} spellings.
        let triple = rest.find("{{{");
        let double = rest.find("{{");
        let (start, open_len, close) = match (triple, double) {
            (Some(t), Some(d)) if t == d => (t, 3, "}}}"),
            (_, Some(d)) => (d, 2, "}}"),
            _ => {
                result.push_str(rest);
                break;
            }
        };
        result.push_str(&rest[..start]);
        let after_open = &rest[start + open_len..];
        if let Some(end_rel) = after_open.find(close) {
            let inner = after_open[..end_rel].trim();
            if inner == "pueue_command_string" {
                result.push_str(command_string);
            } else {
                // Unknown variables render empty in handlebars' default
                // (non-strict) mode.
            }
            rest = &after_open[end_rel + close.len()..];
        } else {
            result.push_str(&rest[start..]);
            break;
        }
    }
    result
}

pub fn spawn_shell_command(
    settings: &Settings,
    command_string: &str,
    envs: &BTreeMap<String, String>,
) -> std::io::Result<ExitStatus> {
    let compile = compile_shell_command(settings, command_string);
    if !envs.is_empty() {
        let json = serde_json::to_string(envs).unwrap_or_else(|_| "{}".to_string());
        logging::log_event(
            logging::Level::Info,
            "pueue::process_helper",
            "pueue/src/process_helper/mod.rs:75",
            &format!("Inject environment variables: {}", json),
        );
    }
    let mut command = Command::new(&compile[0]);
    if compile.len() > 1 {
        command.args(&compile[1..]);
    }
    for (key, value) in envs {
        command.env(key, value);
    }
    if logging::enabled(logging::Level::Debug) {
        let pretty_debug = format!("{:#?}", command);
        let inline_debug = format!("{:?}", command);
        logging::log_field_event(
            logging::Level::Debug,
            "pueue::process_helper",
            "pueue/src/process_helper/mod.rs:82",
            "Prepared command before spawn",
            "command",
            &pretty_debug,
            &inline_debug,
        );
    }
    command.status()
}
