    fn from(task: TomlEditableTask) -> Self {
        Self {
            id: task.id,
            original_command: task.command,
            path: task.path,
            label: task.label,
            priority: task.priority,
        }
    }
}

fn edit_report(message: String, line: u32) -> Report {
    Report::new(message, ("pueue/src/client/commands/edit.rs", line))
}

fn invoke_editor(settings: &Settings, edit_path: &Path) -> Result<()> {
    let editor = std::env::var("EDITOR").map_err(|_| {
        edit_report(
            "The '$EDITOR' environment variable couldn't be read. Aborting.".to_string(),
            170,
        )
    })?;

    let command_string = format!("{} {}", editor, edit_path.display());
    let mut envs = BTreeMap::new();
    envs.insert(
        "PUEUE_EDIT_PATH".to_string(),
        edit_path.display().to_string(),
    );
    let status = spawn_shell_command(settings, &command_string, &envs).map_err(|e| {
        Report::chain(
            vec![
                "Editor command did somehow fail. Aborting.".to_string(),
                e.to_string(),
            ],
            ("pueue/src/client/commands/edit.rs", 185),
        )
    })?;
    if !status.success() {
        return Err(edit_report(
            "The editor exited with a non-zero code. Aborting.".to_string(),
            188,
        ));
    }
    Ok(())
}

