    let content = std::fs::read_to_string(path)?;
    // Editors commonly terminate files with a final newline; the reference
    // strips trailing newlines from these one-value files.
    Ok(content.trim_end_matches('\n').to_string())
}

pub fn edit_tasks(
    settings: &Settings,
    tasks: Vec<EditableTask>,
) -> Result<Vec<EditableTask>> {
    match settings.client.edit_mode {
