    let dir = tempfile::tempdir().map_err(|e| {
        Report::chain(
            vec![
                "Failed to create temporary directory.".to_string(),
                e.to_string(),
            ],
            ("pueue/src/client/commands/edit.rs", 120),
        )
    })?;
    let path = dir.path().join("tasks.toml");
    let map: BTreeMap<usize, TomlEditableTask> = tasks
        .iter()
        .map(|task| (task.id, TomlEditableTask::from(task)))
        .collect();
