fn edit_tasks_files(settings: &Settings, tasks: Vec<EditableTask>) -> Result<Vec<EditableTask>> {
    let dir = tempfile::tempdir().map_err(|e| {
        Report::chain(
            vec![
                "Failed to create temporary directory.".to_string(),
                e.to_string(),
            ],
            ("pueue/src/client/commands/edit.rs", 120),
        )
    })?;
    for task in &tasks {
        let task_dir = dir.path().join(task.id.to_string());
        std::fs::create_dir(&task_dir).map_err(|e| {
            Report::chain(
                vec!["Failed to create temporary directory.".to_string(), e.to_string()],
                ("pueue/src/client/commands/edit.rs", 120),
            )
        })?;
        std::fs::write(task_dir.join("command"), &task.original_command).map_err(io_edit_err)?;
        std::fs::write(task_dir.join("path"), task.path.display().to_string())
            .map_err(io_edit_err)?;
        std::fs::write(task_dir.join("label"), task.label.clone().unwrap_or_default())
            .map_err(io_edit_err)?;
        std::fs::write(task_dir.join("priority"), task.priority.to_string())
            .map_err(io_edit_err)?;
    }

    invoke_editor(settings, dir.path())?;

    let mut edited = Vec::new();
    for task in &tasks {
        let task_dir = dir.path().join(task.id.to_string());
        let command = read_trimmed_file(&task_dir.join("command")).map_err(io_edit_err)?;
        let path_text = read_trimmed_file(&task_dir.join("path")).map_err(io_edit_err)?;
        let label_text = read_trimmed_file(&task_dir.join("label")).map_err(io_edit_err)?;
        let priority_text = read_trimmed_file(&task_dir.join("priority")).map_err(io_edit_err)?;
        let priority: i32 = priority_text
            .trim()
            .parse()
            .map_err(|e| edit_report(format!("{}", e), 220))?;
        edited.push(EditableTask {
            id: task.id,
            original_command: command,
            path: PathBuf::from(path_text),
            label: if label_text.is_empty() { None } else { Some(label_text) },
            priority,
        });
    }
    Ok(edited)
}

fn io_edit_err(e: std::io::Error) -> Report {
    Report::chain(
        vec!["Failed to write temporary file.".to_string(), e.to_string()],
        ("pueue/src/client/commands/edit.rs", 140),
    )
}
