        Response::Group(response) => {
            if let Some(SubCommand::Group { json, .. }) = &opt.command {
                if *json {
                    let text = serde_json::to_string(&response.groups)
                        .unwrap_or_else(|_| "{}".to_string());
                    println!("{}", text);
                } else {
