                            style.group_header(name, group.parallel_tasks, status_lower, running)
                        );
                    }
                }
                Ok(0)
            } else {
                log_unhandled();
                Ok(0)
            }
        }
        Response::Log(logs) => {
            if let Some(SubCommand::Log {
                json,
                lines,
                full,
                tasks_selection: _,
                ..
            }) = log_command_context(opt)
            {
                handle_logs(settings, logs, json, lines, full, opt)
            } else {
