fn handle_response(
    response: Response,
    settings: &Settings,
    style: &Style,
    opt: &Opt,
    client: &mut Client,
) -> Result<i32> {
    match response {
        Response::Success(message) => {
            println!("{}", message);
            Ok(0)
        }
        Response::Failure(message) => {
            eprintln!("{}", message);
            Ok(1)
        }
        Response::Close => Ok(0),
        Response::Group(response) => {
            if let Some(SubCommand::Group { json, .. }) = &opt.command {
                if *json {
                    let text = serde_json::to_string(&response.groups)
                        .unwrap_or_else(|_| "{}".to_string());
                    println!("{}", text);
                } else {
                    for (name, group) in &response.groups {
                        let (status_lower, running) = match group.status {
                            GroupStatus::Running => ("running", true),
                            GroupStatus::Paused => ("paused", false),
                        };
                        println!(
                            "{}",
                            style.group_header(name, group.parallel_tasks, status_lower, running)
                        );
                    }
                }
                Ok(0)
            } else {
                log_unhandled();
                Ok(0)
            }
        }
        Response::Log(logs) => {
            if let Some(SubCommand::Log {
                json,
                lines,
                full,
                tasks_selection: _,
                ..
            }) = log_command_context(opt)
            {
                handle_logs(settings, logs, json, lines, full, opt)
            } else {
                log_unhandled();
                Ok(0)
            }
