        Response::Edit(tasks) => {
            if let Some(SubCommand::Edit { task_ids }) = &opt.command {
                handle_edit(settings, client, tasks, task_ids.clone())
            } else {
                log_unhandled();
                Ok(0)
            }
        }
        Response::Status(_) => {
            log_unhandled();
            Ok(0)
        }
    }
}

fn log_command_context(opt: &Opt) -> Option<LogContext> {
    if let Some(SubCommand::Log {
        json,
        lines,
        full,
        ..
    }) = &opt.command
    {
        Some(LogContext {
            json: *json,
            lines: *lines,
