fn no_finished_message(selection: &TaskSelection) -> String {
    match selection {
        TaskSelection::TaskIds(_) => "There are no finished tasks for your specified ids".to_string(),
        TaskSelection::Group(group) => format!("There are no finished tasks for group '{}'", group),
        TaskSelection::All => "There are no finished tasks".to_string(),
    }
}

fn build_command_string(command: &[String], escape: bool) -> String {
    if escape {
        command
            .iter()
            .map(|token| shell_escape(token))
            .collect::<Vec<_>>()
            .join(" ")
    } else {
        command.join(" ")
    }
}

pub fn shell_escape(token: &str) -> String {
    if token.is_empty() {
        return "''".to_string();
    }
    let safe = token.chars().all(|c| {
        c.is_ascii_alphanumeric()
            || matches!(c, '@' | '%' | '_' | '-' | '+' | '=' | ':' | ',' | '.' | '/')
    });
    if safe {
        return token.to_string();
    }
    let escaped = token.replace('\'', "'\\''");
    format!("'{}'", escaped)
}

fn handle_edit(
    settings: &Settings,
    client: &mut Client,
    tasks: Vec<EditableTask>,
    task_ids: Vec<usize>,
) -> Result<i32> {
