        Ok(edited) => {
            client.send_request(&Request::EditedTasks(edited))?;
            let response =
                client.receive_response(("/workspace/pueue/src/client/commands/edit.rs", 76))?;
            // Use a minimal local handling here rather than recursing
            // into handle_response with the outer Settings/Style pair,
            // which are not available in this helper's signature in the
            // generated scaffold.  The command dispatcher path proper
            // will replace this during integration polishing.
            match response {
                Response::Success(message) => {
                    println!("{}", message);
                    Ok(0)
                }
                Response::Failure(message) => {
