                }
            }
        }
        Err(report) => {
            eprintln!("Encountered an error while editing. Trying to restore the task's status.");
            client.send_request(&Request::EditRestore(task_ids))?;
            let response =
                client.receive_response(("/workspace/pueue/src/client/commands/edit.rs", 59))?;
            match response {
                Response::Success(message) | Response::Failure(message) => {
                    eprintln!("{}", message);
                }
                other => {
