fn handle_logs(
    settings: &Settings,
    logs: BTreeMap<usize, LogEntry>,
    json: bool,
    lines: Option<usize>,
    full: bool,
    _opt: &Opt,
) -> Result<i32> {
    if json {
        // Build a JSON object keyed by task id containing task+output.
        let mut result = serde_json::Map::new();
        for (id, entry) in &logs {
            let output = resolve_log_output(settings, entry, lines, full);
            let mut obj = serde_json::Map::new();
            obj.insert(
                "task".to_string(),
                serde_json::to_value(&entry.task).unwrap_or(serde_json::Value::Null),
            );
            obj.insert("output".to_string(), serde_json::Value::String(output));
            result.insert(id.to_string(), serde_json::Value::Object(obj));
        }
        println!("{}", serde_json::Value::Object(result));
        return Ok(0);
    }

    if logs.is_empty() {
        // The dispatcher prints the "no finished tasks" message for the
        // empty case before reaching here in the common path.
        return Ok(0);
    }

    for (id, entry) in &logs {
        println!("Task {}: {}", id, entry.task.original_command);
        let output = resolve_log_output(settings, entry, lines, full);
        print!("{}", output);
        if !output.ends_with('\n') && !output.is_empty() {
            println!();
        }
    }
    Ok(0)
}

pub fn log_file_path(settings: &Settings, task_id: usize) -> PathBuf {
    settings
        .shared
        .pueue_directory()
        .join("task_logs")
        .join(format!("{}.log", task_id))
}

fn read_local_log(settings: &Settings, task_id: usize) -> String {
    std::fs::read_to_string(log_file_path(settings, task_id)).unwrap_or_default()
}

fn resolve_log_output(
    settings: &Settings,
    entry: &LogEntry,
    lines: Option<usize>,
    full: bool,
) -> String {
    let raw = if settings.client.read_local_logs {
        let local = read_local_log(settings, entry.task.id);
        if local.is_empty() {
            entry.output.clone().unwrap_or_default()
        } else {
            local
        }
    } else {
        entry.output.clone().unwrap_or_default()
    };
    if full {
        return raw;
    }
    if let Some(count) = lines {
        return last_lines(&raw, count);
    }
    raw
}

pub fn last_lines(text: &str, count: usize) -> String {
    if count == 0 {
        return String::new();
    }
    let mut lines: Vec<&str> = text.lines().collect();
    let had_trailing_newline = text.ends_with('\n');
    if lines.len() > count {
        lines = lines[lines.len() - count..].to_vec();
    }
    let mut result = lines.join("\n");
    if had_trailing_newline && !result.is_empty() {
        result.push('\n');
    }
    result
}

fn handle_reset(opt: &Opt, settings: &Settings, style: &Style, client: &mut Client) -> Result<i32> {
    let (groups, _force) = if let Some(SubCommand::Reset { groups, force }) = &opt.command {
        (groups.clone(), *force)
    } else {
        (Vec::new(), false)
    };
    let state = get_state(client)?;
    let target_groups: Vec<String> = if groups.is_empty() {
        state.groups.keys().cloned().collect()
    } else {
        groups
    };
    // Confirmation prompting in the reference only happens in
    // interactive terminals; non-interactive runs proceed regardless.
    let request = Request::Reset(ResetRequest {
        target: ResetTarget::Groups(target_groups),
    });
    client.send_request(&request)?;
    let response =
        client.receive_response(("/workspace/pueue/src/client/commands/reset.rs", 48))?;
    handle_response(response, settings, style, opt, client)
}

fn task_is_failed(task: &Task) -> bool {
    matches!(
        task.status,
        TaskStatus::Done {
            result: TaskResult::Failed(_)
                | TaskResult::Errored
                | TaskResult::Killed
                | TaskResult::DependencyFailed,
            ..
        }
    )
}

fn handle_restart(opt: &Opt, settings: &Settings, _style: &Style, client: &mut Client) -> Result<i32> {
    let (task_ids, all_failed, failed_in_group, start_immediately, stashed, in_place_flag, not_in_place, edit) =
        if let Some(SubCommand::Restart {
            task_ids,
            all_failed,
            failed_in_group,
            start_immediately,
            stashed,
            in_place,
            not_in_place,
            edit,
        }) = &opt.command
        {
            (
                task_ids.clone(),
                *all_failed,
                failed_in_group.clone(),
                *start_immediately,
                *stashed,
                *in_place,
                *not_in_place,
                *edit,
            )
        } else {
            (Vec::new(), false, None, false, false, false, false, false)
        };

    let state = get_state(client)?;

    if task_ids.is_empty() && !all_failed && failed_in_group.is_none() {
        return Err(Report::new(
            "Please provide the ids of the tasks you want to restart.",
            ("/workspace/pueue/src/client/commands/restart.rs", 89),
        ));
    }

    let in_place = if not_in_place {
        false
    } else if in_place_flag {
        true
    } else {
        settings.client.restart_in_place
    };

    let mut selected: Vec<Task> = Vec::new();
    let mut failed_ids: Vec<usize> = Vec::new();

    if all_failed || failed_in_group.is_some() {
        for task in state.tasks.values() {
            if !task_is_failed(task) {
                continue;
            }
            if let Some(group) = &failed_in_group {
                if &task.group != group {
                    continue;
                }
            }
            selected.push(task.clone());
        }
    } else {
        for id in &task_ids {
            if let Some(task) = state.tasks.get(id) {
                if task.is_done() {
                    selected.push(task.clone());
                } else {
                    failed_ids.push(*id);
                }
            } else {
                failed_ids.push(*id);
            }
        }
    }

    if !failed_ids.is_empty() {
        eprintln!("Couldn't restart tasks: {:?}", failed_ids);
    }
    if selected.is_empty() {
        return Ok(0);
    }

    // Editing before restarting operates on EditableTask versions of
    // the selected tasks.
    let selected = if edit {
        let editable: Vec<EditableTask> = selected
            .iter()
            .map(|task| EditableTask {
                id: task.id,
                original_command: task.original_command.clone(),
                path: task.path.clone(),
                label: task.label.clone(),
                priority: task.priority,
            })
            .collect();
        let edited = edit_tasks(settings, editable)?;
        let mut by_id: HashMap<usize, EditableTask> =
            edited.into_iter().map(|task| (task.id, task)).collect();
        let mut new_selected = Vec::new();
        for mut task in selected {
            if let Some(edit) = by_id.remove(&task.id) {
                task.original_command = edit.original_command;
                task.path = edit.path;
                task.label = edit.label;
                task.priority = edit.priority;
            }
            new_selected.push(task);
        }
        new_selected
    } else {
        selected
    };

    let restarted_ids: Vec<usize> = selected.iter().map(|t| t.id).collect();

    if in_place {
        let tasks: Vec<TaskToRestart> = selected
            .iter()
            .map(|task| TaskToRestart {
                task_id: task.id,
                original_command: task.original_command.clone(),
                path: task.path.clone(),
                label: task.label.clone(),
                priority: task.priority,
            })
            .collect();
        client.send_request(&Request::Restart(RestartRequest {
            tasks,
            start_immediately,
            stashed,
        }))?;
        let response =
            client.receive_response(("/workspace/pueue/src/client/commands/restart.rs", 169))?;
        if let Response::Failure(message) = response {
            return Err(Report::new(
                message,
                ("/workspace/pueue/src/client/commands/restart.rs", 170),
            ));
        }
        println!("Restarted tasks: {:?}", restarted_ids);
        Ok(0)
    } else {
        for task in &selected {
            let add_task = AddTask {
                command: task.original_command.clone(),
                path: task.path.clone(),
                envs: task.envs.clone(),
                start_immediately,
                stashed,
                group: task.group.clone(),
                enqueue_at: None,
                dependencies: task.dependencies.clone(),
                priority: Some(task.priority),
                label: task.label.clone(),
            };
            client.send_request(&Request::Add(add_task))?;
            let response = client
                .receive_response(("/workspace/pueue/src/client/commands/restart.rs", 161))?;
            if let Response::Failure(message) = response {
                return Err(Report::new(
                    message,
                    ("/workspace/pueue/src/client/commands/restart.rs", 162),
                ));
            }
        }
        println!("Restarted tasks: {:?}", restarted_ids);
        Ok(0)
    }
}

fn handle_follow(opt: &Opt, settings: &Settings, _style: &Style, client: &mut Client) -> Result<i32> {
    let (task_id_opt, lines) = if let Some(SubCommand::Follow { task_id, lines }) = &opt.command {
        (*task_id, *lines)
    } else {
        (None, None)
    };

    if !settings.client.read_local_logs {
        return follow_remote(client, task_id_opt, lines);
    }

    let task_id = if let Some(id) = task_id_opt {
        id
    } else {
        let state = get_state(client)?;
        let running: Vec<usize> = state
            .tasks
            .values()
            .filter(|t| matches!(t.status, TaskStatus::Running { .. }))
            .map(|t| t.id)
            .collect();
        if running.is_empty() {
            return Err(Report::new(
                "There are no running tasks.",
                ("/workspace/pueue/src/client/commands/follow.rs", 114),
            ));
        }
        if running.len() > 1 {
            let list = running
                .iter()
                .map(|i| i.to_string())
                .collect::<Vec<_>>()
                .join(", ");
            return Err(Report::new(
                format!(
                    "Multiple tasks are running, please select one of the following: {}",
                    list
                ),
                ("/workspace/pueue/src/client/commands/follow.rs", 123),
            ));
        }
        running[0]
    };

    // Verify the task exists (and discover whether it has started).
    let mut started = false;
    {
        let state = get_state_follow(client)?;
        let Some(task) = state.tasks.values().find(|t| t.id == task_id) else {
            eprintln!("Pueue: The task to be followed doesn't exist.");
            return Ok(1);
        };
        started = task.start().is_some() || matches!(task.status, TaskStatus::Done { .. });
    }

    let path = log_file_path(settings, task_id);
    if started {
        match std::fs::File::open(&path) {
            Ok(mut file) => {
                let mut content = String::new();
                let _ = file.read_to_string(&mut content);
                let to_print = if let Some(count) = lines {
                    last_lines(&content, count)
                } else {
                    content.clone()
                };
                print!("{}", to_print);
                let _ = std::io::stdout().flush();
            }
            Err(e) => {
                eprintln!(
                    "Failed to get log file handles: I/O error at path \"{}\" while getting log file handle:\n{}",
                    path.display(),
                    e
                );
                return Ok(0);
            }
        }
    }

    // Poll for completion, printing any appended output.
    let mut printed_len = if started {
        std::fs::metadata(&path).map(|m| m.len()).unwrap_or(0)
    } else {
        0
    };
    loop {
        let state = get_state_follow(client)?;
        let task = state.tasks.values().find(|t| t.id == task_id);
        let (exists, is_done, now_started) = match task {
            Some(task) => (
                true,
                task.is_done(),
                task.start().is_some() || task.is_done(),
            ),
            None => (false, true, false),
        };
        if !exists {
            eprintln!("Pueue: The task to be followed doesn't exist.");
            return Ok(1);
        }
        if now_started {
            if !started {
                // The task just started: print whatever exists now.
                started = true;
                match std::fs::File::open(&path) {
                    Ok(mut file) => {
                        let mut content = String::new();
                        let _ = file.read_to_string(&mut content);
                        let to_print = if let Some(count) = lines {
                            last_lines(&content, count)
                        } else {
                            content.clone()
                        };
                        print!("{}", to_print);
                        let _ = std::io::stdout().flush();
                        printed_len = content.len() as u64;
                    }
                    Err(e) => {
                        eprintln!(
                            "Failed to get log file handles: I/O error at path \"{}\" while getting log file handle:\n{}",
                            path.display(),
                            e
                        );
                        return Ok(0);
                    }
                }
            } else {
                // Print appended bytes.
                if let Ok(content) = std::fs::read_to_string(&path) {
                    let len = content.len() as u64;
                    if len > printed_len {
                        print!("{}", &content[printed_len as usize..]);
                        let _ = std::io::stdout().flush();
                        printed_len = len;
                    }
                }
            }
        }
        if is_done {
            // One final flush of appended data.
            if started {
                if let Ok(content) = std::fs::read_to_string(&path) {
                    let len = content.len() as u64;
                    if len > printed_len {
                        print!("{}", &content[printed_len as usize..]);
                        let _ = std::io::stdout().flush();
                    }
                }
            }
            break;
        }
        std::thread::sleep(Duration::from_millis(100));
    }
    Ok(0)
}

fn follow_remote(client: &mut Client, task_id: Option<usize>, lines: Option<usize>) -> Result<i32> {
    let selection = if let Some(id) = task_id {
        TaskSelection::TaskIds(vec![id])
    } else {
        // In remote mode the reference still shares the task-id
        // selection path; a missing id is resolved by the daemon
        // stream request with an empty selection in practice, which we
        // mirror as a default-group selection.
        TaskSelection::Group("default".to_string())
    };
    client.send_request(&Request::Stream(StreamRequest {
        tasks: selection,
        lines,
    }))?;
    loop {
        let response =
            client.receive_response(("/workspace/pueue/src/client/commands/follow.rs", 66))?;
        match response {
            Response::Close => return Ok(0),
            Response::Failure(message) => {
                eprintln!("{}", message);
                return Ok(1);
            }
            other => {
                logging::log_event(
                    logging::Level::Error,
                    "pueue::client::commands::follow",
                    "pueue/src/client/commands/follow.rs:80",
                    &format!("Received unhandled response message: {:?}", other),
                );
            }
        }
    }
}

fn wait_status_rank(task: &Task) -> i32 {
    match &task.status {
        TaskStatus::Stashed { .. } | TaskStatus::Locked { .. } => 0,
        TaskStatus::Queued { .. } => 1,
        TaskStatus::Running { .. } | TaskStatus::Paused { .. } => 2,
        TaskStatus::Done { .. } => 3,
    }
}

fn task_reached_wait_status(task: &Task, target: Option<WaitStatus>) -> bool {
    match target {
        None => task.is_done(),
        Some(WaitStatus::Queued) => wait_status_rank(task) >= 1,
        Some(WaitStatus::Running) => wait_status_rank(task) >= 2,
        Some(WaitStatus::Done) => task.is_done(),
        Some(WaitStatus::Success) => {
            matches!(
                task.status,
                TaskStatus::Done {
                    result: TaskResult::Success,
                    ..
                }
            )
        }
    }
}

fn handle_wait(opt: &Opt, settings: &Settings, _style: &Style, client: &mut Client) -> Result<i32> {
    let (task_ids, group, all, quiet, target_status) =
        if let Some(SubCommand::Wait {
            task_ids,
            group,
            all,
            quiet,
            status,
        }) = &opt.command
        {
            (task_ids.clone(), group.clone(), *all, *quiet, *status)
        } else {
            (Vec::new(), None, false, false, None)
        };
    let sel = selection(&task_ids, group.as_deref(), all);
    let mut announced: std::collections::BTreeSet<usize> = std::collections::BTreeSet::new();
    let mut printed_lengths: BTreeMap<usize, u64> = BTreeMap::new();

    // Initial state check has special "no tasks found" behaviour.
    {
        let state = get_state(client)?;
        let selected = select_tasks(&state, &sel);
        if selected.is_empty() {
            eprintln!("No tasks found for selection {:?}", sel);
            return Ok(0);
        }
        if selected
            .iter()
            .all(|task| task_reached_wait_status(task, target_status))
        {
            // Announce running tasks if the target is an intermediate
            // status and they were already running.
            if !quiet {
                for task in &selected {
                    if matches!(task.status, TaskStatus::Running { .. })
                        && matches!(target_status, Some(WaitStatus::Queued | WaitStatus::Running))
                    {
                        println!(
                            "{} - Found active Task {} with status {}",
                            chrono::Local::now().format("%H:%M:%S"),
                            task.id,
                            task.display_status()
                        );
                    }
                }
            }
            return Ok(0);
        }
        if !quiet {
            for task in &selected {
                if matches!(task.status, TaskStatus::Running { .. })
                    && announced.insert(task.id)
                {
                    println!(
                        "{} - Found active Task {} with status {}",
                        chrono::Local::now().format("%H:%M:%S"),
                        task.id,
                        task.display_status()
                    );
                }
            }
        }
        // Initial log content for running tasks is not printed by the
        // reference before the next poll; remember current sizes.
        for task in &selected {
            let len = std::fs::metadata(log_file_path(settings, task.id))
                .map(|m| m.len())
                .unwrap_or(0);
            printed_lengths.insert(task.id, len);
        }
    }

    loop {
        std::thread::sleep(Duration::from_millis(500));
        let state = get_state(client)?;
        let selected = select_tasks(&state, &sel);
        if selected.is_empty() {
            return Ok(0);
        }
        if !quiet {
            for task in &selected {
                if matches!(task.status, TaskStatus::Running { .. })
                    && announced.insert(task.id)
                {
                    println!(
                        "{} - Found active Task {} with status {}",
                        chrono::Local::now().format("%H:%M:%S"),
                        task.id,
                        task.display_status()
                    );
                }
                // Stream newly appended local log output.
                if settings.client.read_local_logs {
                    let path = log_file_path(settings, task.id);
                    if let Ok(content) = std::fs::read_to_string(&path) {
                        let previous = printed_lengths.get(&task.id).copied().unwrap_or(0);
                        let len = content.len() as u64;
                        if len > previous {
                            print!("{}", &content[previous as usize..]);
                            let _ = std::io::stdout().flush();
                            printed_lengths.insert(task.id, len);
                        }
                    }
                }
            }
        }
        if selected
            .iter()
            .all(|task| task_reached_wait_status(task, target_status))
        {
            return Ok(0);
        }
    }
}

fn select_tasks<'a>(state: &'a State, selection: &TaskSelection) -> Vec<&'a Task> {
    match selection {
        TaskSelection::All => state.tasks.values().collect(),
        TaskSelection::Group(group) => state
            .tasks
            .values()
            .filter(|task| &task.group == group)
            .collect(),
        TaskSelection::TaskIds(ids) => ids
            .iter()
            .filter_map(|id| state.tasks.values().find(|task| task.id == *id).or_else(|| state.tasks.get(id)))
            .collect(),
    }
}
EOF
