fn read_secret(settings: &settings::Settings) -> errors::Result<Vec<u8>> {
    let path = settings.shared.shared_secret_path();
    let mut file = std::fs::File::open(&path).map_err(|e| {
        Report::new(
            format!(
                "I/O error at path \"{}\" while opening secret file. Did you start the daemon at least once?:\n{}",
                path.display(),
                e
            ),
            ("pueue/src/bin/pueue.rs", 91),
        )
    })?;
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes).map_err(|e| {
        Report::new(
            format!(
                "I/O error at path \"{}\" while reading secret file:\n{}",
                path.display(),
                e
            ),
            ("pueue/src/bin/pueue.rs", 91),
        )
    })?;
    Ok(bytes)
}

fn generate_completions(
    shell: &str,
    output_directory: Option<&PathBuf>,
) -> errors::Result<()> {
    let (display, filename, content): (&str, &str, &str) = match shell {
        "bash" => ("Bash", "pueue.bash", include_str!("../assets/completions/pueue.bash")),
        "elvish" => ("Elvish", "pueue.elv", include_str!("../assets/completions/pueue.elv")),
        "fish" => ("Fish", "pueue.fish", include_str!("../assets/completions/pueue.fish")),
        "power-shell" => (
            "PowerShell",
            "_pueue.ps1",
            include_str!("../assets/completions/_pueue.ps1"),
        ),
        "zsh" => ("Zsh", "_pueue", include_str!("../assets/completions/_pueue")),
        "nushell" => ("Nushell", "pueue.nu", include_str!("../assets/completions/pueue.nu")),
        _ => unreachable!(),
    };

    let write_result: std::io::Result<()> = (|| {
        if let Some(dir) = output_directory {
            let path = dir.join(filename);
            let mut file = std::fs::File::create(path)?;
            file.write_all(content.as_bytes())
        } else {
            let mut stdout = std::io::stdout().lock();
            stdout.write_all(content.as_bytes())
        }
    })();

    write_result.map_err(|e| {
        Report::chain(
            vec![
                format!("Failed to generate completions for {}", display),
                e.to_string(),
            ],
            ("pueue/src/bin/pueue.rs", 125),
        )
    })
}
