    // deriving any per-command behaviour.
    let mut opt = opt;
    if opt.command.is_none() {
        opt.command = Some(SubCommand::Status {
            query: Vec::new(),
            json: false,
            group: None,
        });
    }

    let suppress_version_warn = match &opt.command {
        Some(SubCommand::Status { json, .. }) => *json,
        Some(SubCommand::Log { json, .. }) => *json,
        Some(SubCommand::Group { json, .. }) => *json,
        _ => false,
