//! Minimal Unix terminal-size lookup used to satisfy a transitive API
//! dependency of the command-line help formatter.

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct Height(pub u16);

fn size_for_fd(fd: libc::c_int) -> Option<(Width, Height)> {
    unsafe {
        if libc::isatty(fd) == 0 {
            return None;
        }
        let mut winsize: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) != 0 {
            return None;
        }
        if winsize.ws_col == 0 {
            return None;
        }
        Some((Width(winsize.ws_col), Height(winsize.ws_row)))
    }
}

/// Return the size of the controlling terminal, checking stdout, stderr
/// and stdin in that order.
pub fn terminal_size() -> Option<(Width, Height)> {
    size_for_fd(libc::STDOUT_FILENO)
        .or_else(|| size_for_fd(libc::STDERR_FILENO))
        .or_else(|| size_for_fd(libc::STDIN_FILENO))
}
