fn pest_error(query: &str, pos: usize, expected: &str) -> Report {
    let pos = pos.min(query.len());
    let col = query[..pos].chars().count() + 1;
    let message = format!(
        " --> 1:{}\n  |\n1 | {}\n  | {}^---\n  |\n  = expected {}",
        col,
        query,
        " ".repeat(col - 1),
        expected
    );
    Report::chain(
        vec!["Failed to parse query".to_string(), message],
        ("pueue/src/client/commands/state/query/mod.rs", 163),
    )
}

const EXPECTED_NEXT_FILTER: &str =
    "EOI, column_status, column_command, column_label, datetime_filter, order_by, or limit_condition";

fn is_word_char(c: u8) -> bool {
    (c as char).is_ascii_alphanumeric() || c == b'_'
}

impl Query {
    pub fn parse(tokens: &[String]) -> Result<Query> {
        if tokens.is_empty() {
            return Ok(Query::default());
        }
        let query_str = tokens.join(" ");
        let q = query_str.as_str();
        let bytes = q.as_bytes();
        let mut result = Query::default();
        let mut pos = 0usize;
        let mut anything_parsed = false;

        let skip_ws = |mut p: usize| -> usize {
            while p < q.len() && bytes[p].is_ascii_whitespace() {
                p += 1;
            }
            p
        };
        let read_word = |mut p: usize| -> (usize, usize) {
            let start = p;
            while p < q.len() && is_word_char(bytes[p]) {
                p += 1;
            }
            (start, p)
        };
        let starts_word = |p: usize, word: &str| -> bool {
            q[p..].starts_with(word)
                && q[p + word.len()..]
                    .as_bytes()
                    .first()
                    .map(|c| !is_word_char(*c))
                    .unwrap_or(true)
        };

        pos = skip_ws(pos);
        if pos >= q.len() {
            return Ok(result);
        }

        // Optional columns=... selection.  Whitespace is allowed
        // around the '=' by the grammar's implicit whitespace.
        if starts_word(pos, "columns") {
            let mut p = skip_ws(pos + "columns".len());
            if p < q.len() && bytes[p] == b'=' {
                p += 1;
                let mut cols: Vec<Column> = Vec::new();
                loop {
                    p = skip_ws(p);
                    let (start, end) = read_word(p);
                    if start == end {
                        return Err(pest_error(q, p, "column"));
                    }
                    let column = Column::parse(&q[start..end])
                        .ok_or_else(|| pest_error(q, start, "column"))?;
                    cols.push(column);
                    p = skip_ws(end);
                    if p < q.len() && bytes[p] == b',' {
                        p += 1;
                        continue;
                    }
                    break;
                }
                result.columns = Some(cols);
                pos = p;
                anything_parsed = true;
            }
        }

        // Zero or more filters.
        let mut greedy_text_filter = false;
        loop {
            pos = skip_ws(pos);
            if pos >= q.len() {
                break;
            }
            if starts_word(pos, "order_by") || starts_word(pos, "first") || starts_word(pos, "last") {
                break;
            }
            // Determine a filter column.
            let (col_start, col_end) = read_word(pos);
            if col_start == col_end {
                if !anything_parsed {
                    return Err(pest_error(q, 0, "query"));
                }
                return Err(pest_error(q, pos, EXPECTED_NEXT_FILTER));
            }
            let col_name = q[col_start..col_end].to_string();
            let is_status = col_name == "status";
            let is_text = col_name == "command" || col_name == "label";
            let is_datetime = matches!(col_name.as_str(), "start" | "end" | "enqueue_at");
            if !is_status && !is_text && !is_datetime {
                if !anything_parsed {
                    return Err(pest_error(q, 0, "query"));
                }
                return Err(pest_error(q, col_start, EXPECTED_NEXT_FILTER));
            }
            let mut p = skip_ws(col_end);
            // Operator, restricted by column kind.
            let op_start = p;
            let op: String = if q[p..].starts_with("%=") {
                p += 2;
                "%=".to_string()
            } else if q[p..].starts_with("!=") {
                p += 2;
                "!=".to_string()
            } else if p < q.len() && matches!(bytes[p], b'=' | b'<' | b'>') {
                let op = (bytes[p] as char).to_string();
                p += 1;
                op
            } else {
                let expected = if is_status {
                    "eq or neq"
                } else if is_text {
                    "eq, neq, or contains"
                } else {
                    "eq, neq, lt, or gt"
                };
                return Err(pest_error(q, op_start, expected));
            };
            let op_valid = if is_status {
                op == "=" || op == "!="
            } else if is_text {
                op == "=" || op == "!=" || op == "%="
            } else {
                op == "=" || op == "!=" || op == "<" || op == ">"
            };
            if !op_valid {
                let expected = if is_status {
                    "eq or neq"
                } else if is_text {
                    "eq, neq, or contains"
                } else {
                    "eq, neq, lt, or gt"
                };
                return Err(pest_error(q, op_start, expected));
            }
            p = skip_ws(p);
            if p >= q.len() {
                if is_status {
                    return Err(pest_error(
                        q,
                        p,
                        "status_queued, status_stashed, status_paused, status_running, status_success, or status_failed",
                    ));
                } else if is_datetime {
                    return Err(pest_error(q, p, "datetime, date, or time"));
                } else {
                    // Text values are arbitrary strings; an empty one is
                    // reported by pest as whatever could follow, but use a
                    // close approximation.
                    return Err(pest_error(q, p, EXPECTED_NEXT_FILTER));
                }
            }

            if is_text {
                // Free-text filter values consume the rest of the query.
                let raw = q[p..].trim().to_string();
                result.filters.push(Filter {
                    column: col_name,
                    op,
                    value: FilterValue::Text(raw.clone()),
                    raw,
                });
                anything_parsed = true;
                greedy_text_filter = true;
                pos = q.len();
                break;
            } else if is_status {
                let start = p;
                while p < q.len() && !bytes[p].is_ascii_whitespace() {
                    p += 1;
                }
                let raw_token = &q[start..p];
                let lowered = raw_token.to_ascii_lowercase();
                const STATUSES: [&str; 6] =
                    ["queued", "stashed", "paused", "running", "success", "failed"];
                if !STATUSES.contains(&lowered.as_str()) {
                    return Err(pest_error(
                        q,
                        start,
                        "status_queued, status_stashed, status_paused, status_running, status_success, or status_failed",
                    ));
                }
                result.filters.push(Filter {
                    column: col_name,
                    op,
                    value: FilterValue::Text(lowered.clone()),
                    raw: lowered,
                });
                pos = p;
                anything_parsed = true;
            } else {
                // Datetime / date / time values.
                let (value, raw, new_pos) = parse_datetime_token(q, p).ok_or_else(|| {
                    pest_error(q, p, "datetime, date, or time")
                })?;
                result.filters.push(Filter {
                    column: col_name,
                    op,
                    value,
                    raw,
                });
                pos = new_pos;
                anything_parsed = true;
            }

            // After a non-greedy filter, validate that what follows can
            // begin an allowable continuation.  This catches trailing
            // junk attached to a syntactically valid prefix.
            let next = skip_ws(pos);
            if next < q.len() {
                let valid_next = starts_word(next, "status")
                    || starts_word(next, "command")
                    || starts_word(next, "label")
                    || starts_word(next, "start")
                    || starts_word(next, "end")
                    || starts_word(next, "enqueue_at")
                    || starts_word(next, "order_by")
                    || starts_word(next, "first")
                    || starts_word(next, "last");
                if !valid_next {
                    return Err(pest_error(q, next, EXPECTED_NEXT_FILTER));
                }
            }
        }

        if greedy_text_filter {
            return Ok(result);
        }

        // Optional order_by.
        pos = skip_ws(pos);
        if pos < q.len() && starts_word(pos, "order_by") {
            pos += "order_by".len();
            let p = skip_ws(pos);
            let (start, end) = read_word(p);
            // pest reports the position of the '=' (or other separator)
            // itself when a separator other than whitespace is used.
            if start == end {
                return Err(pest_error(q, p, "column"));
            }
            if start == pos && !(pos < q.len() && bytes[pos].is_ascii_whitespace()) {
                // e.g. order_by=id - failure is at the '='.
                return Err(pest_error(q, pos, "column"));
            }
            let column = Column::parse(&q[start..end])
                .ok_or_else(|| pest_error(q, start, "column"))?;
            let mut p = skip_ws(end);
            let mut desc = false;
            let mut direction_parsed = false;
            if p < q.len() {
                if starts_word(p, "asc") {
                    p += 3;
                    direction_parsed = true;
                } else if starts_word(p, "desc") {
                    p += 4;
                    desc = true;
                    direction_parsed = true;
                } else if !(starts_word(p, "first") || starts_word(p, "last")) {
                    return Err(pest_error(
                        q,
                        p,
                        "EOI, ascending, descending, or limit_condition",
                    ));
                }
            }
            result.order_by = Some((column, desc));
            pos = p;
            if direction_parsed {
                let next = skip_ws(pos);
                if next < q.len() && !(starts_word(next, "first") || starts_word(next, "last")) {
                    return Err(pest_error(q, next, "EOI or limit_condition"));
                }
                pos = next;
            }
        }

        // Optional limit condition.
        pos = skip_ws(pos);
        if pos < q.len() {
            let is_first = if starts_word(pos, "first") {
                pos += 5;
                true
            } else if starts_word(pos, "last") {
                pos += 4;
                false
            } else {
                if !anything_parsed && result.order_by.is_none() {
                    return Err(pest_error(q, 0, "query"));
                }
                if result.order_by.is_some() {
                    return Err(pest_error(
                        q,
                        pos,
                        "EOI, ascending, descending, or limit_condition",
                    ));
                }
                return Err(pest_error(q, pos, EXPECTED_NEXT_FILTER));
            };
            // The count itself.
            let after_kw = pos;
            let mut p = skip_ws(pos);
            if p >= q.len() {
                // Missing count is accepted by the grammar and then
                // fails when the empty string is parsed as a number.
                return Err(Report::chain(
                    vec![
                        "Expected a number 0 for limit condition".to_string(),
                        "cannot parse integer from empty string".to_string(),
                    ],
                    ("pueue/src/client/commands/state/query/limit.rs", 62),
                ));
            }
            if !bytes[p].is_ascii_digit() {
                return Err(pest_error(q, p, "EOI"));
            }
            // Capture the digit span, allowing digit groups separated
            // by whitespace (pest's implicit whitespace inside a
            // digit repetition).  A following letter ends the span and
            // is then a trailing-junk error.
            let count_start = p;
            let mut count_end = p;
            loop {
                while count_end < q.len() && bytes[count_end].is_ascii_digit() {
                    count_end += 1;
                }
                let mut probe = count_end;
                while probe < q.len() && bytes[probe].is_ascii_whitespace() {
                    probe += 1;
                }
                if probe > count_end && probe < q.len() && bytes[probe].is_ascii_digit() {
                    count_end = probe;
                    continue;
                }
                break;
            }
            let raw_count = &q[count_start..count_end];
            // Validate that nothing is attached to the count, such as
            // a letter: the grammar ends the query there.
            if count_end < q.len() && !bytes[count_end].is_ascii_whitespace() {
                return Err(pest_error(q, count_end, "EOI"));
            }
            let parsed_count: std::result::Result<usize, _> = raw_count.parse();
            let count = match parsed_count {
                Ok(value) => value,
                Err(e) => {
                    return Err(Report::chain(
                        vec![
                            "Expected a number 0 for limit condition".to_string(),
                            e.to_string(),
                        ],
                        ("pueue/src/client/commands/state/query/limit.rs", 62),
                    ));
                }
            };
            if count == 0 {
                return Err(Report::new(
                    "Expected a number >0 for limit condition",
                    ("pueue/src/client/commands/state/query/limit.rs", 65),
                ));
            }
            result.limit = Some((!is_first, count));
            pos = skip_ws(count_end);
            if pos < q.len() {
                return Err(pest_error(q, pos, "EOI"));
            }
            let _ = after_kw;
        }

        Ok(result)
    }

    pub fn apply(&self, mut tasks: Vec<Task>, settings: &Settings) -> Result<Vec<Task>> {
        // Convert datetime filters once, reporting conversion errors in
        // the same shapes as the reference.
        let mut compiled: Vec<Option<CompiledDateTime>> = Vec::new();
        for filter in &self.filters {
            compiled.push(compile_datetime_filter(filter)?);
        }
        tasks.retain(|task| {
            self.filters
                .iter()
                .zip(compiled.iter())
                .all(|(filter, compiled_value)| {
                    filter_matches(task, filter, compiled_value.as_ref())
                })
        });
        if let Some((column, desc)) = self.order_by {
            sort_tasks(&mut tasks, column, desc, settings);
        }
        if let Some((is_last, count)) = self.limit {
            if tasks.len() > count {
                if is_last {
                    let start = tasks.len() - count;
                    tasks = tasks[start..].to_vec();
                } else {
                    tasks.truncate(count);
                }
            }
        }
        Ok(tasks)
    }
}

#[derive(Debug, Clone)]
enum CompiledDateTime {
    Date(NaiveDate),
    Full(NaiveDateTime),
}

fn compile_datetime_filter(filter: &Filter) -> Result<Option<CompiledDateTime>> {
    match &filter.value {
        FilterValue::Text(_) => Ok(None),
        FilterValue::Date(raw) => {
            let date = NaiveDate::parse_from_str(raw, "%Y-%m-%d").map_err(|e| {
                Report::chain(
                    vec![
                        "Expected YYYY-MM-SS date format".to_string(),
                        e.to_string(),
                    ],
                    ("pueue/src/client/commands/state/query/filters.rs", 98),
                )
            })?;
            Ok(Some(CompiledDateTime::Date(date)))
        }
        FilterValue::Time(raw) => {
            let time = NaiveTime::parse_from_str(raw, "%H:%M:%S").map_err(|e| {
                Report::chain(
                    vec![
                        "Expected hh:mm:ss time format".to_string(),
                        e.to_string(),
                    ],
                    ("pueue/src/client/commands/state/query/filters.rs", 86),
                )
            })?;
            let today = Local::now().date_naive();
            Ok(Some(CompiledDateTime::Full(today.and_time(time))))
        }
        FilterValue::DateTime(raw) => {
            let normalized = raw.replacen('T', " ", 1);
            let formatted = if normalized.len() > 10 && normalized.as_bytes()[10] != b' ' {
                format!("{} {}", &normalized[..10], &normalized[10..])
            } else {
                normalized
            };
            let ndt = NaiveDateTime::parse_from_str(&formatted, "%Y-%m-%d %H:%M:%S").map_err(|e| {
                Report::chain(
                    vec![
                        "Expected YYYY-MM-SS hh:mm:ss date time format".to_string(),
                        e.to_string(),
                    ],
                    ("pueue/src/client/commands/state/query/filters.rs", 93),
                )
            })?;
            Ok(Some(CompiledDateTime::Full(ndt)))
        }
    }
}

fn filter_matches(task: &Task, filter: &Filter, compiled: Option<&CompiledDateTime>) -> bool {
    match filter.column.as_str() {
        "status" => {
            let value = status_filter_value(task);
            match filter.op.as_str() {
                "=" => value == filter.raw,
                "!=" => value != filter.raw,
                _ => false,
            }
        }
        "command" => {
            let value = &task.command;
            match filter.op.as_str() {
                "=" => value == &filter.raw,
                "!=" => value != &filter.raw,
                "%=" => value.contains(&filter.raw),
                _ => false,
            }
        }
        "label" => {
            let value = task.label.as_deref().unwrap_or("");
            match filter.op.as_str() {
                "=" => value == filter.raw,
                "!=" => value != filter.raw,
                "%=" => value.contains(&filter.raw),
                _ => false,
            }
        }
        "start" | "end" | "enqueue_at" => {
            let dt = match filter.column.as_str() {
                "start" => task.start(),
                "end" => task.end(),
                _ => task.enqueue_at(),
            };
            let Some(dt) = dt else { return false };
            let Some(compiled) = compiled else { return false };
            let local = dt.with_timezone(&Local);
            match compiled {
                CompiledDateTime::Date(date) => {
                    let task_date = local.date_naive();
                    match filter.op.as_str() {
                        "=" => task_date == *date,
                        // The reference returns no tasks for a not-equal
                        // comparison against a bare date.
                        "!=" => false,
                        "<" => task_date < *date,
                        ">" => task_date > *date,
                        _ => false,
                    }
                }
                CompiledDateTime::Full(ndt) => {
                    let task_ndt = local.naive_local();
                    match filter.op.as_str() {
                        "=" => task_ndt == *ndt,
                        "!=" => task_ndt != *ndt,
                        "<" => task_ndt < *ndt,
                        ">" => task_ndt > *ndt,
                        _ => false,
                    }
                }
            }
        }
        _ => false,
    }
}

/// Attempts to consume a datetime/date/time token starting at `pos`.
/// Returns the semantic raw value, a display raw string and the new
/// position after the consumed token.
fn parse_datetime_token(q: &str, pos: usize) -> Option<(FilterValue, String, usize)> {
    let bytes = q.as_bytes();
    let digit = |index: usize| -> bool {
        bytes.get(index).map(|c| c.is_ascii_digit()).unwrap_or(false)
    };
    let time_at = |start: usize| -> Option<usize> {
        // HH:MM or HH:MM:SS, each field exactly two digits.
        if !(digit(start) && digit(start + 1) && bytes.get(start + 2) == Some(&b':') && digit(start + 3) && digit(start + 4)) {
            return None;
        }
        let mut end = start + 5;
        if bytes.get(end) == Some(&b':') && digit(end + 1) && digit(end + 2) {
            end += 3;
        }
        Some(end)
    };
    let date_at = |start: usize| -> Option<usize> {
        if digit(start)
            && digit(start + 1)
            && digit(start + 2)
            && digit(start + 3)
            && bytes.get(start + 4) == Some(&b'-')
            && digit(start + 5)
            && digit(start + 6)
            && bytes.get(start + 7) == Some(&b'-')
            && digit(start + 8)
            && digit(start + 9)
        {
            Some(start + 10)
        } else {
            None
        }
    };

    if let Some(date_end) = date_at(pos) {
        // Optional time directly attached or separated by whitespace.
        if let Some(time_end) = time_at(date_end) {
            let raw = q[pos..time_end].to_string();
            return Some((FilterValue::DateTime(raw.clone()), raw, time_end));
        }
        let mut probe = date_end;
        while probe < q.len() && bytes[probe].is_ascii_whitespace() {
            probe += 1;
        }
        if probe > date_end {
            if let Some(time_end) = time_at(probe) {
                let raw = q[pos..time_end].to_string();
                return Some((FilterValue::DateTime(raw.clone()), raw, time_end));
            }
        }
        let raw = q[pos..date_end].to_string();
        return Some((FilterValue::Date(raw.clone()), raw, date_end));
    }
    if let Some(time_end) = time_at(pos) {
        let raw = q[pos..time_end].to_string();
        return Some((FilterValue::Time(raw.clone()), raw, time_end));
    }
    None
}

