use crate::errors::{Report, Result};
use crate::process_helper::spawn_shell_command;
use crate::protocol::EditableTask;
use crate::settings::{EditMode, Settings};
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

#[derive(Debug, Serialize, Deserialize)]
struct TomlEditableTask {
    id: usize,
    command: String,
    path: PathBuf,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    label: Option<String>,
    priority: i32,
}

impl From<&EditableTask> for TomlEditableTask {
    fn from(task: &EditableTask) -> Self {
        Self {
            id: task.id,
            command: task.original_command.clone(),
            path: task.path.clone(),
            label: task.label.clone(),
            priority: task.priority,
        }
    }
}

impl From<TomlEditableTask> for EditableTask {
    fn from(task: TomlEditableTask) -> Self {
        Self {
            id: task.id,
            original_command: task.command,
            path: task.path,
            label: task.label,
            priority: task.priority,
        }
    }
}

fn edit_report(message: String, line: u32) -> Report {
    Report::new(message, ("pueue/src/client/commands/edit.rs", line))
}

fn io_at_path(path: &Path, action: &str, error: &std::io::Error, line: u32) -> Report {
    edit_report(
        format!(
            "I/O error at path \"{}\" while {}:\n{}",
            path.display(),
            action,
            error
        ),
        line,
    )
}

fn invoke_editor(settings: &Settings, edit_path: &Path) -> Result<()> {
    let editor = std::env::var("EDITOR").map_err(|_| {
        edit_report(
            "The '$EDITOR' environment variable couldn't be read. Aborting.".to_string(),
            170,
        )
    })?;

    let command_string = format!("{} {}", editor, edit_path.display());
    let mut envs = BTreeMap::new();
    envs.insert(
        "PUEUE_EDIT_PATH".to_string(),
        edit_path.display().to_string(),
    );
    let status = spawn_shell_command(settings, &command_string, &envs).map_err(|e| {
        Report::chain(
            vec![
                "Editor command did somehow fail. Aborting.".to_string(),
                e.to_string(),
            ],
            ("pueue/src/client/commands/edit.rs", 185),
        )
    })?;
    if !status.success() {
        return Err(edit_report(
            "The editor exited with a non-zero code. Aborting.".to_string(),
            188,
        ));
    }
    Ok(())
}

pub fn edit_tasks(settings: &Settings, tasks: Vec<EditableTask>) -> Result<Vec<EditableTask>> {
    let dir = tempfile::tempdir().map_err(|e| {
        Report::chain(
            vec![
                "Failed to create temporary directory for edtiting.".to_string(),
                e.to_string(),
            ],
            ("pueue/src/client/commands/edit.rs", 91),
        )
    })?;
    match settings.client.edit_mode {
        EditMode::Toml => edit_tasks_toml(settings, tasks, dir.path()),
        EditMode::Files => edit_tasks_files(settings, tasks, dir.path()),
    }
}

fn edit_tasks_toml(
    settings: &Settings,
    tasks: Vec<EditableTask>,
    dir: &Path,
) -> Result<Vec<EditableTask>> {
    let path = dir.join("tasks.toml");
    let map: BTreeMap<usize, TomlEditableTask> = tasks
        .iter()
        .map(|task| (task.id, TomlEditableTask::from(task)))
        .collect();
    let content = toml::to_string(&map).map_err(|e| {
        edit_report(
            format!("Some error occurred. \nFailed to serialize tasks to toml:\n{}", e),
            110,
        )
    })?;
    std::fs::write(&path, content)
        .map_err(|e| io_at_path(&path, "writing temporary file", &e, 115))?;

    invoke_editor(settings, &path)?;

    let edited_content = std::fs::read_to_string(&path)
        .map_err(|e| io_at_path(&path, "reading temporary file", &e, 133))?;
    let parsed: BTreeMap<usize, TomlEditableTask> =
        toml::from_str(&edited_content).map_err(|e| {
            edit_report(
                format!("Some error occurred. \nFailed to deserialize tasks to toml:\n{}", e),
                135,
            )
        })?;
    Ok(parsed.into_values().map(EditableTask::from).collect())
}

fn write_edit_file(path: &Path, content: &str) -> Result<()> {
    std::fs::write(path, content)
        .map_err(|e| io_at_path(path, "creating temporary file", &e, 230))
}

fn read_edit_file(path: &Path, kind: &str, line: u32) -> Result<String> {
    let content = std::fs::read_to_string(path)
        .map_err(|e| io_at_path(path, &format!("reading {} file", kind), &e, line))?;
    Ok(content.trim().to_string())
}

fn edit_tasks_files(
    settings: &Settings,
    tasks: Vec<EditableTask>,
    dir: &Path,
) -> Result<Vec<EditableTask>> {
    for task in &tasks {
        let task_dir = dir.join(task.id.to_string());
        std::fs::create_dir(&task_dir)
            .map_err(|e| io_at_path(&task_dir, "creating temporary directory", &e, 220))?;
        write_edit_file(&task_dir.join("command"), &task.original_command)?;
        write_edit_file(&task_dir.join("path"), &task.path.display().to_string())?;
        write_edit_file(
            &task_dir.join("label"),
            &task.label.clone().unwrap_or_default(),
        )?;
        write_edit_file(&task_dir.join("priority"), &task.priority.to_string())?;
    }

    invoke_editor(settings, dir)?;

    let mut edited = Vec::new();
    for task in &tasks {
        let task_dir = dir.join(task.id.to_string());
        let command = read_edit_file(&task_dir.join("command"), "command", 253)?;
        let path_text = read_edit_file(&task_dir.join("path"), "path", 263)?;
        let label_text = read_edit_file(&task_dir.join("label"), "label", 283)?;
        let priority_text = read_edit_file(&task_dir.join("priority"), "priority", 293)?;
        let priority: i32 = priority_text.parse().map_err(|e| {
            Report::chain(
                vec![
                    format!(
                        "Failed to parse priority string '{}' into an integer for task {}",
                        priority_text, task.id
                    ),
                    format!("{}", e),
                ],
                ("pueue/src/client/commands/edit.rs", 297),
            )
        })?;
        edited.push(EditableTask {
            id: task.id,
            original_command: command,
            path: PathBuf::from(path_text),
            label: if label_text.is_empty() {
                None
            } else {
                Some(label_text)
            },
            priority,
        });
    }
    Ok(edited)
}
EOF
./compile.sh >/tmp/compile.log 2>&1 && python3 /tmp/diff_edit.py && python3 /tmp/diff_edit2.py
