fn task_reached_wait_status(task: &Task, target: Option<WaitStatus>) -> bool {
    match target {
        None | Some(WaitStatus::Done) => task.is_done(),
        Some(WaitStatus::Success) => matches!(
            task.status,
            TaskStatus::Done {
                result: TaskResult::Success,
                ..
            }
        ),
        Some(WaitStatus::Running) => {
            matches!(task.status, TaskStatus::Running { .. }) || task.is_done()
        }
        Some(WaitStatus::Queued) => {
            matches!(task.status, TaskStatus::Queued { .. } | TaskStatus::Running { .. })
                || task.is_done()
        }
    }
}

fn wait_timestamp() -> String {
    chrono::Local::now().format("%H:%M:%S").to_string()
}

fn print_wait_result(task: &Task) {
    let message = match &task.status {
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => format!("Task {} succeeded with 0", task.id),
            TaskResult::Failed(code) => format!("Task {} failed with {}", task.id, code),
            TaskResult::Errored => format!("Task {} experienced an IO error.", task.id),
            TaskResult::Killed => format!("Task {} has been killed", task.id),
            TaskResult::DependencyFailed => {
                format!("Task {} failed due to failed dependencies", task.id)
            }
        },
        _ => return,
    };
    println!("{} - {}", wait_timestamp(), message);
}

fn handle_wait(opt: &Opt, settings: &Settings, _style: &Style, client: &mut Client) -> Result<i32> {
    let (task_ids, group, all, quiet, target_status) =
        if let Some(SubCommand::Wait {
            task_ids,
            group,
            all,
            quiet,
            status,
        }) = &opt.command
        {
            (task_ids.clone(), group.clone(), *all, *quiet, *status)
        } else {
            (Vec::new(), None, false, false, None)
        };
    let sel = selection(&task_ids, group.as_deref(), all);
    let mut previous: BTreeMap<usize, Task> = BTreeMap::new();
    let mut printed_lengths: BTreeMap<usize, u64> = BTreeMap::new();

    // Initial poll.
    {
        let state = get_state(client)?;
        let selected = select_tasks(&state, &sel);
        if selected.is_empty() {
            eprintln!("No tasks found for selection {:?}", sel);
            return Ok(0);
        }
        if !quiet {
            for task in &selected {
                if matches!(
                    task.status,
                    TaskStatus::Running { .. } | TaskStatus::Paused { .. }
                ) {
                    println!(
                        "{} - Found active Task {} with status {}",
                        wait_timestamp(),
                        task.id,
                        task.display_status()
                    );
                }
            }
        }
        for task in &selected {
            previous.insert(task.id, (*task).clone());
            let len = std::fs::metadata(log_file_path(settings, task.id))
                .map(|m| m.len())
                .unwrap_or(0);
            printed_lengths.insert(task.id, len);
        }
        if selected
            .iter()
            .all(|task| task_reached_wait_status(task, target_status))
        {
            return Ok(0);
        }
    }

    loop {
        std::thread::sleep(Duration::from_secs(2));
        let state = get_state(client)?;
        let selected = select_tasks(&state, &sel);
        if selected.is_empty() {
            eprintln!("No tasks found for selection {:?}", sel);
            return Ok(0);
        }

        if !quiet {
            // Stream newly appended local log output first, mirroring
            // the local-log mode in which output appears while waiting.
            if settings.client.read_local_logs {
                for task in &selected {
                    let path = log_file_path(settings, task.id);
                    if let Ok(content) = std::fs::read_to_string(&path) {
                        let previous_len = printed_lengths.get(&task.id).copied().unwrap_or(0);
                        let len = content.len() as u64;
                        if len > previous_len {
                            print!("{}", &content[previous_len as usize..]);
                            let _ = std::io::stdout().flush();
                            printed_lengths.insert(task.id, len);
                        }
                    }
                }
            }

            for task in &selected {
                match previous.get(&task.id) {
                    None => {
                        println!(
                            "{} - New task {} with status {}",
                            wait_timestamp(),
                            task.id,
                            task.display_status()
                        );
                    }
                    Some(old) => {
                        if old.display_status() != task.display_status()
                            || std::mem::discriminant(&old.status)
                                != std::mem::discriminant(&task.status)
                        {
                            if task.is_done() {
                                print_wait_result(task);
                            } else {
                                println!(
                                    "{} - Task {} changed from {} to {}",
                                    wait_timestamp(),
                                    task.id,
                                    old.display_status(),
                                    task.display_status()
                                );
                            }
                        }
                    }
                }
            }
        }

        previous = selected.iter().map(|task| (task.id, (*task).clone())).collect();
        if selected
            .iter()
            .all(|task| task_reached_wait_status(task, target_status))
        {
            return Ok(0);
        }
    }
}
