fn task_reached_wait_status(task: &Task, target: Option<WaitStatus>) -> bool {
    match target {
        None | Some(WaitStatus::Done) => task.is_done(),
        Some(WaitStatus::Success) => matches!(
            task.status,
            TaskStatus::Done {
                result: TaskResult::Success,
                ..
            }
        ),
        Some(WaitStatus::Running) => {
            matches!(task.status, TaskStatus::Running { .. }) || task.is_done()
        }
        Some(WaitStatus::Queued) => {
            matches!(task.status, TaskStatus::Queued { .. } | TaskStatus::Running { .. })
                || task.is_done()
        }
    }
}

fn wait_timestamp() -> String {
    chrono::Local::now().format("%H:%M:%S").to_string()
}

fn print_wait_result(task: &Task) {
    let message = match &task.status {
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => format!("Task {} succeeded with 0", task.id),
            TaskResult::Failed(code) => format!("Task {} failed with {}", task.id, code),
            TaskResult::Errored => format!("Task {} experienced an IO error.", task.id),
            TaskResult::Killed => format!("Task {} has been killed", task.id),
            TaskResult::DependencyFailed => {
                format!("Task {} failed due to failed dependencies", task.id)
            }
        },
        _ => return,
    };
    println!("{} - {}", wait_timestamp(), message);
}

fn handle_wait(opt: &Opt, settings: &Settings, _style: &Style, client: &mut Client) -> Result<i32> {
