    let mut previous: BTreeMap<usize, Task> = BTreeMap::new();
    let mut printed_lengths: BTreeMap<usize, u64> = BTreeMap::new();

    // Initial poll.
    {
        let state = get_state(client)?;
        let selected = select_tasks(&state, &sel);
        if selected.is_empty() {
            eprintln!("No tasks found for selection {:?}", sel);
            return Ok(0);
        }
        if !quiet {
            for task in &selected {
                if matches!(
                    task.status,
                    TaskStatus::Running { .. } | TaskStatus::Paused { .. }
                ) {
                    println!(
