            let date = add_months(now_local.date_naive(), amount_signed)?;
            let time = trailing_time.unwrap_or_else(|| NaiveTime::from_hms_opt(0, 0, 0).unwrap());
            naive_local_to_utc(date.and_time(time))
        }
        "year" | "years" | "yr" | "yrs" | "y" => {
            let date = add_months(now_local.date_naive(), amount_signed.checked_mul(12)?)?;
            let time = trailing_time.unwrap_or_else(|| NaiveTime::from_hms_opt(0, 0, 0).unwrap());
            naive_local_to_utc(date.and_time(time))
        }
        "day" | "days" | "d" => {
            if let Some(time) = trailing_time {
                let date = now_local.date_naive() + Duration::days(amount_signed);
                naive_local_to_utc(date.and_time(time))
            } else {
                Some(local_to_utc(now_local + Duration::days(amount_signed)))
            }
        }
        "week" | "weeks" | "w" => {
            if let Some(time) = trailing_time {
                let date = now_local.date_naive() + Duration::days(amount_signed.checked_mul(7)?);
                naive_local_to_utc(date.and_time(time))
            } else {
                Some(local_to_utc(now_local + Duration::days(amount_signed.checked_mul(7)?)))
            }
        }
        _ => {
            let secs = unit_seconds(&unit)?;
            // A trailing time is ignored after sub-day offsets in the
            // reference behaviour.
            Some(local_to_utc(
                now_local + Duration::seconds(amount_signed.checked_mul(secs)?),
            ))
        }
    }
}

fn split_trailing_time(s: &str) -> (&str, Option<NaiveTime>) {
    let trimmed = s.trim();
    // Find the last whitespace-separated token and see whether it is a
    // time of day.
    if let Some(idx) = trimmed.rfind(|c: char| c.is_whitespace()) {
        let (head, tail) = trimmed.split_at(idx);
        let tail = tail.trim();
        if let Some(time) = parse_time_of_day(tail) {
            return (head.trim(), Some(time));
        }
    }
    (trimmed, None)
}

fn parse_weekday_prefix(word: &str) -> Option<Weekday> {
    // The upstream tokeniser accepts weekday prefixes; in particular a
    // word beginning with "mon" (including "month") denotes Monday in
    // a next/last construct.
    let lower = word.to_ascii_lowercase();
    if lower.starts_with("mon") {
        Some(Weekday::Mon)
    } else if lower.starts_with("tue") {
        Some(Weekday::Tue)
    } else if lower.starts_with("wed") {
        Some(Weekday::Wed)
    } else if lower.starts_with("thu") {
        Some(Weekday::Thu)
    } else if lower.starts_with("fri") {
        Some(Weekday::Fri)
    } else if lower.starts_with("sat") {
        Some(Weekday::Sat)
    } else if lower.starts_with("sun") {
        Some(Weekday::Sun)
    } else {
        None
    }
}
