/// Debug output with a +00:00 suffix instead of Z.  Normalise the
/// corresponding tokens in generated Debug strings.
pub fn fix_datetime_debug(input: &str) -> String {
    let bytes = input.as_bytes();
    let mut out = String::with_capacity(input.len());
    let mut i = 0usize;
    while i < bytes.len() {
        // Look for YYYY-MM-DDTHH:MM:SS(.fraction)?Z followed by a
        // Debug delimiter.
        if i + 20 <= bytes.len()
            && bytes[i].is_ascii_digit()
            && bytes.get(i + 4) == Some(&b'-')
            && bytes.get(i + 7) == Some(&b'-')
            && bytes.get(i + 10) == Some(&b'T')
            && bytes.get(i + 13) == Some(&b':')
            && bytes.get(i + 16) == Some(&b':')
        {
            let mut j = i + 19;
            if bytes.get(j) == Some(&b'.') {
                j += 1;
                while j < bytes.len() && bytes[j].is_ascii_digit() {
                    j += 1;
                }
            }
            if bytes.get(j) == Some(&b'Z') {
                let next = bytes.get(j + 1).cloned();
                if matches!(next, Some(b',') | Some(b'\n') | Some(b')') | Some(b']') | None) {
                    out.push_str(&input[i..j]);
                    out.push_str("+00:00");
                    i = j + 1;
                    continue;
                }
            }
        }
        let ch_len = input[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
        out.push_str(&input[i..i + ch_len]);
        i += ch_len;
    }
    out
}
