                let next = bytes.get(j + 1).cloned();
                if matches!(next, Some(b',') | Some(b'\n') | Some(b')') | Some(b']') | None) {
                    out.push_str(&input[i..j]);
                    out.push_str("+00:00");
                    i = j + 1;
                    continue;
                }
            }
        }
        let ch_len = input[i..].chars().next().map(|c| c.len_utf8()).unwrap_or(1);
        out.push_str(&input[i..i + ch_len]);
        i += ch_len;
    }
    out
}
EOF
