{"command":"cat > src/snappy.rs <<'EOF'
use std::fmt;
use std::io;

#[derive(Clone)]
pub struct SnapError {
    display: String,
    debug: String,
}

impl SnapError {
    fn new(display: String, debug: String) -> Self {
        Self { display, debug }
    }
    fn into_io(self) -> io::Error {
        io::Error::new(io::ErrorKind::Other, self)
    }
}

impl fmt::Display for SnapError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.display)
    }
}
impl fmt::Debug for SnapError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.debug)
    }
}
impl std::error::Error for SnapError {}

fn stream_header_error(byte: u8) -> io::Error {
    SnapError::new(
        format!(
            "snappy: corrupt input (expected stream header but got unexpected chunk type byte {})",
            byte
        ),
        format!("StreamHeader {{ byte: {} }}", byte),
    )
    .into_io()
}

fn stream_header_mismatch(bytes: &[u8]) -> io::Error {
    SnapError::new(
        format!(
            "snappy: corrupt input (expected sNaPpY stream header but got {})",
            String::from_utf8_lossy(bytes)
        ),
        format!("StreamHeaderMismatch {{ bytes: {:?} }}", bytes),
    )
    .into_io()
}

fn unsupported_chunk_type(byte: u8) -> io::Error {
    SnapError::new(
        format!("snappy: corrupt input (unsupported chunk type: {})", byte),
        format!("UnsupportedChunkType {{ byte: {} }}", byte),
    )
    .into_io()
}

fn unsupported_chunk_length(len: usize, header: bool) -> io::Error {
    SnapError::new(
        format!("snappy: corrupt input (unsupported chunk length: {})", len),
        format!(
            "UnsupportedChunkLength {{ len: {}, header: {} }}",
            len, header
        ),
    )
    .into_io()
}

fn corrupt(display: impl Into<String>, debug: impl Into<String>) -> io::Error {
    SnapError::new(display.into(), debug.into()).into_io()
}

const MAX_CHUNK_LENGTH: usize = 76490;
const STREAM_IDENTIFIER: &[u8; 10] = b"\xff\x06\x00\x00sNaPpY";

// CRC-32C (Castagnoli), used by the Snappy framing format.
fn crc32c(data: &[u8]) -> u32 {
    let mut table = [0u32; 256];
    for i in 0..256 {
        let mut crc = i as u32;
        for _ in 0..8 {
            crc = if crc & 1 != 0 {
                (crc >> 1) ^ 0x82F63B78
            } else {
                crc >> 1
            };
        }
        table[i] = crc;
    }
