                    if pos + extra > input.len() {
                        return Err(corrupt(
                            "snappy: corrupt input (unexpected end of input)",
                            "CorruptInput",
                        ));
                    }
                    let mut value = 0usize;
                    for i in 0..extra {
                        value |= (input[pos + i] as usize) << (8 * i);
                    }
                    pos += extra;
                    length = value;
                }
                length += 1;
                if pos + length > input.len() {
                    return Err(corrupt(
                        "snappy: corrupt input (literal length exceeds input)",
                        "CorruptInput",
                    ));
                }
                out.extend_from_slice(&input[pos..pos + length]);
                pos += length;
            }
            1 => {
                let length = (((tag >> 2) & 0x07) + 4) as usize;
                if pos >= input.len() {
                    return Err(corrupt(
                        "snappy: corrupt input (unexpected end of input)",
                        "CorruptInput",
                    ));
                }
                let offset = (((tag as usize) >> 5) << 8) | input[pos] as usize;
                pos += 1;
                copy_from_output(out, offset, length)?;
            }
            2 => {
                let length = ((tag >> 2) as usize) + 1;
                if pos + 2 > input.len() {
                    return Err(corrupt(
                        "snappy: corrupt input (unexpected end of input)",
                        "CorruptInput",
                    ));
                }
                let offset = input[pos] as usize | ((input[pos + 1] as usize) << 8);
                pos += 2;
                copy_from_output(out, offset, length)?;
            }
            _ => {
                let length = ((tag >> 2) as usize) + 1;
                if pos + 4 > input.len() {
                    return Err(corrupt(
                        "snappy: corrupt input (unexpected end of input)",
                        "CorruptInput",
                    ));
                }
                let offset = input[pos] as usize
                    | ((input[pos + 1] as usize) << 8)
                    | ((input[pos + 2] as usize) << 16)
                    | ((input[pos + 3] as usize) << 24);
                pos += 4;
                copy_from_output(out, offset, length)?;
            }
        }
    }
    if out.len() != target_len {
        return Err(corrupt(
            "snappy: corrupt input (uncompressed length mismatch)",
            "CorruptInput",
        ));
    }
    Ok(())
}

fn copy_from_output(
    out: &mut Vec<u8>,
    offset: usize,
    length: usize,
) -> std::result::Result<(), io::Error> {
    if offset == 0 || offset > out.len() {
        return Err(corrupt(
            format!("snappy: corrupt input (invalid copy offset: {})", offset),
            "CorruptInput",
        ));
    }
    for _ in 0..length {
        let index = out.len() - offset;
        let byte = out[index];
        out.push(byte);
    }
    Ok(())
}

fn unexpected_eof() -> io::Error {
    io::Error::new(io::ErrorKind::UnexpectedEof, "failed to fill whole buffer")
}

/// Decode a Snappy framed stream.  Returns the decompressed prefix that
/// was successfully read together with any error that stopped decoding,
/// mirroring the behaviour of a streaming frame decoder.
pub fn decompress_framed(input: &[u8]) -> (Vec<u8>, Option<io::Error>) {
    let mut output: Vec<u8> = Vec::new();
    if input.is_empty() {
        return (output, None);
    }
    // Stream identifier: exactly ten bytes read with read_exact.  Inputs
    // shorter than the identifier fail with UnexpectedEof before any
    // header validation.
    if input.len() < STREAM_IDENTIFIER.len() {
        return (output, Some(unexpected_eof()));
    }
    let first = input[0];
    if first != 0xFF {
        return (output, Some(stream_header_error(first)));
    }
    let header_len = (input[1] as usize) | ((input[2] as usize) << 8) | ((input[3] as usize) << 16);
    if header_len > MAX_CHUNK_LENGTH || header_len != 6 {
        return (output, Some(unsupported_chunk_length(header_len, true)));
    }
    if &input[..STREAM_IDENTIFIER.len()] != STREAM_IDENTIFIER.as_slice() {
        return (
            output,
            Some(stream_header_mismatch(&input[4..STREAM_IDENTIFIER.len()])),
        );
    }

    let mut pos = STREAM_IDENTIFIER.len();
    while pos < input.len() {
        if input.len() - pos < 4 {
            return (output, Some(unexpected_eof()));
        }
        let chunk_type = input[pos];
        let chunk_len =
            (input[pos + 1] as usize) | ((input[pos + 2] as usize) << 8) | ((input[pos + 3] as usize) << 16);
        if chunk_len > MAX_CHUNK_LENGTH {
            return (
                output,
                Some(unsupported_chunk_length(chunk_len, false)),
            );
        }
        // The version of snap used by the reference does not support the
        // padding chunk (0x05) or reserved chunk types.
        if !matches!(chunk_type, 0x00 | 0x01 | 0xFF) && !(0x80..=0xFE).contains(&chunk_type) {
            return (output, Some(unsupported_chunk_type(chunk_type)));
        }
        if input.len() - (pos + 4) < chunk_len {
            return (output, Some(unexpected_eof()));
        }
        let data = &input[pos + 4..pos + 4 + chunk_len];
        match chunk_type {
            0xFF => {
                // A repeated stream identifier.
                let full = &input[pos..pos + 4 + chunk_len];
                if full != STREAM_IDENTIFIER.as_slice() {
                    if chunk_len != 6 {
                        return (output, Some(unsupported_chunk_length(chunk_len, false)));
                    }
                    return (output, Some(stream_header_mismatch(data)));
                }
            }
            0x00 | 0x01 => {
                if data.len() < 4 {
                    return (
                        output,
                        Some(corrupt(
                            "snappy: corrupt input (chunk too short)",
                            "CorruptInput",
                        )),
                    );
                }
                let masked_crc = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);
                let expected_crc = unmask_crc(masked_crc);
                let start_len = output.len();
                if chunk_type == 0x01 {
                    output.extend_from_slice(&data[4..]);
                } else if let Err(error) = decompress_raw(&data[4..], &mut output) {
                    return (output, Some(error));
                }
                let actual_crc = crc32c(&output[start_len..]);
                if actual_crc != expected_crc {
                    // The snap crate reports a checksum error and the
                    // data read for this chunk is not yielded.  Removing
                    // it mirrors that observable behaviour for callers
                    // that stop at the error.
                    output.truncate(start_len);
                    return (
                        output,
                        Some(corrupt(
                            format!(
                                "snappy: corrupt input (checksum mismatch: expected {:#010x}, got {:#010x})",
                                expected_crc, actual_crc
                            ),
                            format!(
                                "ChecksumMismatch {{ expected: {}, actually: {} }}",
                                expected_crc, actual_crc
                            ),
                        )),
                    );
                }
            }
            0x80..=0xFE => {
                // Skippable chunk: ignore its contents.
            }
            _ => unreachable!(),
        }
        pos += 4 + chunk_len;
    }
    (output, None)
}
