    if json {
        let mut result = serde_json::Map::new();
        for (map_id, entry) in &logs {
            let output = if settings.client.read_local_logs {
                match read_local_log_lines(settings, *map_id, requested_lines) {
                    Ok((file_lines, _truncated)) => file_lines.join("\n"),
                    Err(message) => format!("(Pueue error) {}", message),
                }
            } else if entry.output.is_empty() {
                String::new()
            } else {
                let (bytes, error) = crate::snappy::decompress_framed(&entry.output);
                if let Some(error) = error {
                    format!("(Pueue error) Failed to decompress remote log output: {:?}", error)
                } else {
                    match String::from_utf8(bytes) {
                        Ok(text) => text,
                        Err(_) => {
                            // Match the io error produced by
                            // read_to_string on invalid UTF-8 data.
                            let error = std::io::Error::new(
                                std::io::ErrorKind::InvalidData,
                                "stream did not contain valid UTF-8",
                            );
                            format!("(Pueue error) Failed to decompress remote log output: {:?}", error)
                        }
                    }
                }
            };
            let mut obj = serde_json::Map::new();
            obj.insert(
                "task".to_string(),
                serde_json::to_value(&entry.task).unwrap_or(serde_json::Value::Null),
            );
            obj.insert("output".to_string(), serde_json::Value::String(output));
            result.insert(map_id.to_string(), serde_json::Value::Object(obj));
        }
        println!("{}", serde_json::Value::Object(result));
        return Ok(0);
    }

    for (map_id, entry) in &logs {
        let task = &entry.task;
        let Some(header) = log_header(task) else {
            continue;
        };
        eprint!("{}", header);

        if settings.client.read_local_logs {
            match read_local_log_lines(settings, task.id, requested_lines) {
                Ok((file_lines, truncated)) => {
                    if file_lines.is_empty() {
                        continue;
                    }
                    if truncated {
                        let count = requested_lines.unwrap_or(0);
                        eprintln!("\noutput: (last {} lines)", count);
                    } else {
                        eprintln!("\noutput:");
                    }
                    for line in &file_lines {
                        println!("{}", line);
                    }
                }
                Err(message) => {
                    eprintln!("{}", message);
                }
            }
        } else {
            if entry.output.is_empty() {
                continue;
            }
            if entry.output_complete {
                println!("\noutput:");
            } else {
                let count = requested_lines.unwrap_or(15);
                println!("\noutput: (last {} lines)", count);
            }
            let (bytes, error) = crate::snappy::decompress_framed(&entry.output);
            use std::io::Write as _;
            let mut stdout = std::io::stdout().lock();
            let _ = stdout.write_all(&bytes);
            let _ = stdout.flush();
            if let Some(error) = error {
                eprintln!("Error while parsing stdout: {}", error);
            }
            let _ = map_id;
        }
    }
    Ok(0)
}

fn log_header(task: &Task) -> Option<String> {
    let status_text: &str = match &task.status {
        TaskStatus::Running { .. } => "running",
        TaskStatus::Paused { .. } => "paused",
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => "completed successfully",
            TaskResult::Failed(code) => {
                // The text is interpolated below through an owned string
                // held in this scope.  This branch is unreachable via
                // this binding; see the owned construction next.
                let _ = code;
                ""
            }
            TaskResult::Errored => "some IO error.\n Check daemon log.",
            TaskResult::Killed => "killed by system or user",
            TaskResult::DependencyFailed => "dependency failed",
        },
        _ => return None,
    };
    let status_text_owned: String = match &task.status {
        TaskStatus::Done {
            result: TaskResult::Failed(code),
            ..
        } => format!("failed with exit code {}", code),
        _ => status_text.to_string(),
    };
    let prefix = format!("Task {}:    ", task.id);
    let mut content_lines: Vec<String> = Vec::new();
    for (index, line) in status_text_owned.lines().enumerate() {
        if index == 0 {
            content_lines.push(format!("{}{}", prefix, line));
        } else {
            content_lines.push(format!("{}{}", " ".repeat(prefix.len()), line));
        }
    }
    let box_width = content_lines
        .iter()
        .map(|line| line.chars().count())
        .max()
        .unwrap_or(0);
    let mut text = String::new();
    text.push_str(&format!("┌{}┐\n", "─".repeat(box_width + 2)));
    for line in &content_lines {
        text.push_str(&format!("│ {:<width$} │\n", line, width = box_width));
    }
    text.push_str(&format!("└{}┘\n", "─".repeat(box_width + 2)));

    let mut meta: Vec<String> = Vec::new();
    meta.push(format!("Command: {}", task.command));
    meta.push(format!("   Path: {}", task.path.display()));
    if let Some(start) = task.start() {
        meta.push(format!(
            "  Start: {}",
            start.with_timezone(&chrono::Local).to_rfc2822()
        ));
    }
    if let Some(end) = task.end() {
        meta.push(format!(
            "    End: {}",
            end.with_timezone(&chrono::Local).to_rfc2822()
        ));
    }
    let meta_width = meta.iter().map(|line| line.chars().count()).max().unwrap_or(0) + 1;
    for line in &meta {
        text.push_str(&format!("{:<width$}\n", line, width = meta_width));
    }
    Some(text)
}
