fn read_local_log_raw(
    settings: &Settings,
    task_id: usize,
    requested_lines: Option<usize>,
) -> std::result::Result<(Vec<u8>, bool), String> {
    let path = log_file_path(settings, task_id);
    let mut file = std::fs::File::open(&path).map_err(|e| {
        format!(
            "Failed to get log file handle: I/O error at path \"{}\" while getting log file handle:\n{}",
            path.display(),
            e
        )
    })?;
    let mut bytes = Vec::new();
    use std::io::Read as _;
    file.read_to_end(&mut bytes).map_err(|e| {
        format!("Failed reading local log file: {}", e)
    })?;
    if let Some(count) = requested_lines {
        let mut pos = bytes.len();
        let mut remaining = count;
        while pos > 0 {
            pos -= 1;
            if bytes[pos] == b'\n' {
                if remaining == 0 {
                    pos += 1;
                    break;
                }
                remaining -= 1;
            }
        }
        let truncated = pos > 0;
        return Ok((bytes[pos..].to_vec(), truncated));
    }
    Ok((bytes, false))
}

EOF
