pub struct StreamResponse {
    pub logs: BTreeMap<usize, String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Response {
    AddedTask(AddedTaskResponse),
    Edit(Vec<EditableTask>),
    Status(State),
    Log(BTreeMap<usize, LogEntry>),
    Group(GroupResponse),
    Stream(StreamResponse),
    Success(String),
    Failure(String),
    Close,
}

/// The response type used by the remote-follow receive loop in the
/// reference implementation.  It intentionally does not contain the
/// AddedTask or Stream variants.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum FollowResponse {
    Success(String),
    Failure(String),
    Status(State),
    Group(GroupResponse),
    Log(BTreeMap<usize, LogEntry>),
    Edit(Vec<EditableTask>),
    Close,
}'''
