        location: (&str, u32),
    ) -> Result<FollowResponse> {
        self.receive_typed(location)
    }

    fn receive_typed<T>(&mut self, location: (&str, u32)) -> Result<T>
    where
        T: serde::de::DeserializeOwned + std::fmt::Debug,
    {
        let payload = self
            .receive_bytes_inner()
            .map_err(|msg| Report::new(msg, location))?;
