{"command":"cat > src/tls_stream.rs <<'EOF'
use std::ffi::{c_char, c_int, c_long, c_uchar, c_ulong, c_void, CString};
use std::io::{self, Read, Write};
use std::net::TcpStream;
use std::os::unix::io::AsRawFd;
use crate::settings::Settings;

#[allow(non_camel_case_types)]
enum SslMethod {}
#[allow(non_camel_case_types)]
enum SslCtx {}
#[allow(non_camel_case_types)]
enum Ssl {}
#[allow(non_camel_case_types)]
enum X509 {}
#[allow(non_camel_case_types)]
enum X509Store {}

#[link(name = "ssl")]
#[link(name = "crypto")]
extern "C" {
    fn TLS_client_method() -> *const SslMethod;
    fn SSL_CTX_new(method: *const SslMethod) -> *mut SslCtx;
    fn SSL_CTX_free(ctx: *mut SslCtx);
    fn SSL_CTX_get_cert_store(ctx: *mut SslCtx) -> *mut X509Store;
    fn SSL_CTX_set_verify(ctx: *mut SslCtx, mode: c_int, callback: Option<extern "C" fn(c_int, *mut c_void) -> c_int>);
    fn X509_STORE_add_cert(store: *mut X509Store, cert: *mut X509) -> c_int;
    fn d2i_X509(cert: *mut *mut X509, input: *mut *const c_uchar, len: c_long) -> *mut X509;
    fn X509_free(cert: *mut X509);
    fn SSL_new(ctx: *mut SslCtx) -> *mut Ssl;
    fn SSL_free(ssl: *mut Ssl);
    fn SSL_set_fd(ssl: *mut Ssl, fd: c_int) -> c_int;
    fn SSL_set1_host(ssl: *mut Ssl, name: *const c_char) -> c_int;
    fn SSL_ctrl(ssl: *mut Ssl, cmd: c_int, larg: c_long, parg: *mut c_void) -> c_long;
    fn SSL_connect(ssl: *mut Ssl) -> c_int;
    fn SSL_read(ssl: *mut Ssl, buf: *mut c_void, num: c_int) -> c_int;
    fn SSL_write(ssl: *mut Ssl, buf: *const c_void, num: c_int) -> c_int;
    fn SSL_get_error(ssl: *const Ssl, ret: c_int) -> c_int;
    fn SSL_get_verify_result(ssl: *const Ssl) -> c_long;
    fn SSL_shutdown(ssl: *mut Ssl) -> c_int;
    fn ERR_get_error() -> c_ulong;
    fn ERR_error_string_n(error: c_ulong, buf: *mut c_char, len: usize);
    fn ERR_clear_error();
}

const SSL_VERIFY_PEER: c_int = 0x01;
const SSL_CTRL_SET_TLSEXT_HOSTNAME: c_int = 55;

pub struct TlsStream {
    ssl: *mut Ssl,
    ctx: *mut SslCtx,
    // Kept alive for the descriptor used by OpenSSL.
    _tcp: TcpStream,
}

fn drain_openssl_errors() -> Vec<String> {
    let mut messages = Vec::new();
    loop {
        let error = unsafe { ERR_get_error() };
        if error == 0 {
            break;
        }
        let mut buffer = vec![0u8; 256];
        unsafe {
            ERR_error_string_n(
                error,
                buffer.as_mut_ptr() as *mut c_char,
                buffer.len(),
            );
        }
        let end = buffer.iter().position(|b| *b == 0).unwrap_or(buffer.len());
        messages.push(String::from_utf8_lossy(&buffer[..end]).into_owned());
    }
    messages
}

fn map_handshake_error(ssl: *mut Ssl, ret: c_int) -> String {
    let verify_result = unsafe { SSL_get_verify_result(ssl) };
    let ssl_error = unsafe { SSL_get_error(ssl, ret) };
    let openssl_errors = drain_openssl_errors();
    let joined = openssl_errors.join(": ");
    let lower = joined.to_ascii_lowercase();

    if verify_result != 0 {
        // Map common OpenSSL verification results onto the wording
        // produced by the reference implementation's webpki verifier.
        let mapped = match verify_result {
            10 => "invalid peer certificate: Expired".to_string(),
            11 => "invalid peer certificate: NotValidYet".to_string(),
            18 | 19 | 20 | 21 | 27 => {
                "invalid peer certificate: UnknownIssuer".to_string()
            }
            26 => "invalid peer certificate: InvalidPurpose".to_string(),
            62 => "invalid peer certificate: CertNotValidForName".to_string(),
            _ => {
                if lower.contains("ca ") || lower.contains("basic constraints") {
                    "invalid peer certificate: Other(OtherError(CaUsedAsEndEntity))".to_string()
                } else {
                    "invalid peer certificate: UnknownIssuer".to_string()
                }
            }
        };
        return format!("{}.", mapped.trim_end_matches('.'));
    }

    // SSL_ERROR_SYSCALL (5) with an empty error queue is how a clean
    // EOF during the handshake is reported.
    if ssl_error == 5 && openssl_errors.is_empty() {
        return "tls handshake eof.".to_string();
    }
    if lower.contains("wrong version")
        || lower.contains("unknown protocol")
        || lower.contains("packet length too long")
        || lower.contains("record layer")
        || lower.contains("invalid content type")
    {
        return "received corrupt message of type InvalidContentType.".to_string();
    }
    if lower.contains("certificate") {
        return "invalid peer certificate: UnknownIssuer.".to_string();
    }
    if !joined.is_empty() {
        // OpenSSL messages are verbose "NNN:error:CODE:lib:reason:..."
        // Keep the human-oriented tail after the last colon if there is
        // one in the final component, otherwise use the whole text.
        let message = joined
            .rsplit(':')
            .find(|part| !part.trim().is_empty())
            .unwrap_or(joined.as_str())
            .trim()
            .to_string();
        if message.is_empty() {
            "tls handshake eof.".to_string()
        } else if message.ends_with('.') {
            message
        } else {
            format!("{}.", message)
        }
    } else {
        "tls handshake eof.".to_string()
    }
}

impl TlsStream {
    pub fn connect(
        tcp: TcpStream,
        _settings: &Settings,
        cert_der: Option<&[u8]>,
    ) -> std::result::Result<Self, String> {
        unsafe {
            ERR_clear_error();
            let ctx = SSL_CTX_new(TLS_client_method());
            if ctx.is_null() {
                let _ = drain_openssl_errors();
                return Err("tls handshake eof.".to_string());
            }

            let cleanup_ctx = |ctx: *mut SslCtx, message: String| -> String {
                SSL_CTX_free(ctx);
                message
            };

            if let Some(der) = cert_der {
                let store = SSL_CTX_get_cert_store(ctx);
                if store.is_null() {
                    let message = cleanup_ctx(ctx, "tls handshake eof.".to_string());
                    return Err(message);
                }
                let mut input = der.as_ptr();
                let cert = d2i_X509(std::ptr::null_mut(), &mut input as *mut *const c_uchar, der.len() as c_long);
                if cert.is_null() {
                    let _ = drain_openssl_errors();
                    // The certificate was already parsed by the caller
                    // with a PEM parser; a DER blob that openssl itself
                    // cannot interpret should behave like an invalid
                    // peer certificate at handshake time.
                    let message = cleanup_ctx(ctx, "invalid peer certificate: UnknownIssuer.".to_string());
                    return Err(message);
                }
                let added = X509_STORE_add_cert(store, cert);
                X509_free(cert);
                if added != 1 {
                    // Adding an already-present or malformed certificate
                    // is not fatal at this stage; clear the queue and let
                    // handshaking verification report any real issue.
                    ERR_clear_error();
                }
            }

            SSL_CTX_set_verify(ctx, SSL_VERIFY_PEER, None);

            let ssl = SSL_new(ctx);
            if ssl.is_null() {
                let _ = drain_openssl_errors();
                let message = cleanup_ctx(ctx, "tls handshake eof.".to_string());
                return Err(message);
            }
            if SSL_set_fd(ssl, tcp.as_raw_fd()) != 1 {
                let message = map_handshake_error(ssl, -1);
                SSL_free(ssl);
                SSL_CTX_free(ctx);
                return Err(message);
            }

            if let Ok(hostname) = CString::new("pueue.local") {
                let _ = SSL_set1_host(ssl, hostname.as_ptr());
                let _ = SSL_ctrl(
                    ssl,
                    SSL_CTRL_SET_TLSEXT_HOSTNAME,
                    0,
                    hostname.as_ptr() as *mut c_void,
                );
            }

            let result = SSL_connect(ssl);
            if result != 1 {
                let message = map_handshake_error(ssl, result);
                SSL_free(ssl);
                SSL_CTX_free(ctx);
                return Err(message);
            }
            let verify_result = SSL_get_verify_result(ssl);
            if verify_result != 0 {
                // OpenSSL normally aborts the handshake for an
                // unsuccessful verification when SSL_VERIFY_PEER is set,
                // but enforce the result here as a belt-and-braces check
                // and use the same wording as a handshake failure.
                let message = map_handshake_error(ssl, result);
                SSL_free(ssl);
                SSL_CTX_free(ctx);
                return Err(message);
            }

            Ok(TlsStream {
                ssl,
                ctx,
                _tcp: tcp,
            })
        }
    }

    fn io_error_for(&self, result: c_int) -> io::Error {
        let ssl_error = unsafe { SSL_get_error(self.ssl, result) };
        let errors = drain_openssl_errors();
        match ssl_error {
            6 => io::Error::new(io::ErrorKind::ConnectionAborted, "tls connection shut down"),
            5 => {
                // SSL_ERROR_SYSCALL: consult errno if available.
                let errno_error = io::Error::last_os_error();
                if errno_error.raw_os_error() == Some(0) || errors.is_empty() {
                    io::Error::new(io::ErrorKind::UnexpectedEof, "failed to fill whole buffer")
                } else {
                    errno_error
                }
            }
            _ => {
                let message = if errors.is_empty() {
                    "tls error".to_string()
                } else {
                    errors.join(": ")
                };
                io::Error::new(io::ErrorKind::Other, message)
            }
        }
    }
}

impl Read for TlsStream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        if buf.is_empty() {
            return Ok(0);
        }
        let result = unsafe {
            SSL_read(
                self.ssl,
                buf.as_mut_ptr() as *mut c_void,
                buf.len() as c_int,
            )
        };
        if result > 0 {
            Ok(result as usize)
        } else {
            let ssl_error = unsafe { SSL_get_error(self.ssl, result) };
            if ssl_error == 6 {
                // SSL_ERROR_ZERO_RETURN: clean TLS shutdown.
                let _ = drain_openssl_errors();
                Ok(0)
            } else {
                Err(self.io_error_for(result))
            }
        }
    }
