struct Fragment {
    text: String,
    space_before: bool,
}

fn split_long_word(word: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![String::new()];
    }
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut current_width = 0usize;
    for ch in word.chars() {
        let char_width = UnicodeWidthChar::width(ch).unwrap_or(1);
        if current_width + char_width > width && !current.is_empty() {
            parts.push(current);
            current = String::new();
            current_width = 0;
        }
        current.push(ch);
        current_width += char_width;
    }
    if !current.is_empty() || parts.is_empty() {
        parts.push(current);
    }
    parts
}

fn wrap_line(line: &str, width: usize) -> Vec<String> {
    if width == 0 {
        return vec![String::new()];
    }
    if display_width(line) <= width {
        return vec![line.to_string()];
    }
    let mut fragments: Vec<Fragment> = Vec::new();
    for (index, word) in line.split(' ').enumerate() {
        let pieces = split_long_word(word, width);
        for (piece_index, piece) in pieces.into_iter().enumerate() {
            fragments.push(Fragment {
                text: piece,
                space_before: index > 0 && piece_index == 0,
            });
        }
    }
    if fragments.is_empty() {
        return vec![String::new()];
    }
    let mut lines: Vec<String> = Vec::new();
    let mut current = String::new();
    for fragment in fragments {
        let fragment_width = display_width(&fragment.text);
        if current.is_empty() {
            current.push_str(&fragment.text);
            continue;
        }
        let separator_width = if fragment.space_before { 1 } else { 0 };
        if display_width(&current) + separator_width + fragment_width <= width {
            if fragment.space_before {
                current.push(' ');
            }
            current.push_str(&fragment.text);
        } else {
            lines.push(current);
            current = fragment.text;
        }
    }
    if !current.is_empty() || lines.is_empty() {
        lines.push(current);
    }
    lines
}

fn wrap_cell_text(text: &str, width: usize) -> String {
    text.lines()
        .flat_map(|line| wrap_line(line, width))
        .collect::<Vec<_>>()
        .join("\\n")
}

